const TEMA = [{"k":"benda","zh":"日常用品","py":"rì cháng yòng pǐn","title":{"id":"Benda sehari-hari","en":"Everyday objects","tl":"Mga gamit sa araw-araw","vi":"Đồ dùng hằng ngày"},"desc":{"id":"Kamu bisa menyebut dan menanyakan benda-benda di rumah, alat tulis, dan barang bawaan sehari-hari.","en":"You can name and ask about things at home, stationery and everyday items you carry."},"icon":"home","sets":[{"title":{"id":"Di kamar dan ruang tamu","en":"Bedroom and living room"},"words":[{"hz":"床","mw":"張","ex":{"zh":"我的床很大。","py":"wǒ de chuáng hěn dà","id":"Tempat tidurku besar.","en":"My bed is big."}},{"hz":"枕頭","mw":"個","ex":{"zh":"這個枕頭很軟。","py":"zhè ge zhěn tou hěn ruǎn","id":"Bantal ini empuk.","en":"This pillow is very soft."}},{"hz":"沙發","mw":"張","ex":{"zh":"客廳有一張沙發。","py":"kè tīng yǒu yì zhāng shā fā","id":"Di ruang tamu ada satu sofa.","en":"There is a sofa in the living room."}},{"hz":"電視","mw":"台","ex":{"zh":"電視在客廳裡。","py":"diàn shì zài kè tīng lǐ","id":"Televisi ada di ruang tamu.","en":"The TV is in the living room."}},{"hz":"燈","mw":"盞","ex":{"zh":"這裡太暗，我想開燈。","py":"zhè lǐ tài àn wǒ xiǎng kāi dēng","id":"Di sini terlalu gelap, aku mau menyalakan lampu.","en":"It is too dark here. I want to turn on the light."}},{"hz":"窗簾","ex":{"zh":"窗簾是藍色的。","py":"chuāng lián shì lán sè de","id":"Gordennya berwarna biru.","en":"The curtains are blue."}},{"hz":"冷氣","mw":"台","ex":{"zh":"夏天我開冷氣。","py":"xià tiān wǒ kāi lěng qì","id":"Waktu musim panas aku menyalakan AC.","en":"In summer I turn on the air conditioner."}},{"hz":"門","mw":"扇","ex":{"zh":"請把門關上。","py":"qǐng bǎ mén guān shàng","id":"Tolong tutup pintunya.","en":"Please close the door."}}]},{"title":{"id":"Di dapur dan meja makan","en":"Kitchen and dining table"},"words":[{"hz":"冰箱","mw":"台","ex":{"zh":"冰箱裡有牛奶。","py":"bīng xiāng lǐ yǒu niú nǎi","id":"Di dalam kulkas ada susu.","en":"There is milk in the fridge."}},{"hz":"餐桌","mw":"張","ex":{"zh":"我們在餐桌吃飯。","py":"wǒ men zài cān zhuō chī fàn","id":"Kami makan di meja makan.","en":"We eat at the dining table."}},{"hz":"碗","mw":"個","ex":{"zh":"這個碗很漂亮。","py":"zhè ge wǎn hěn piào liang","id":"Mangkuk ini cantik sekali.","en":"This bowl is very pretty."}},{"hz":"湯匙","mw":"支","ex":{"zh":"我需要一支湯匙。","py":"wǒ xū yào yì zhī tāng chí","id":"Aku butuh satu sendok.","en":"I need a spoon."}},{"hz":"盤","mw":"個","ex":{"zh":"桌上有一個盤子。","py":"zhuō shàng yǒu yí ge pán zi","id":"Di atas meja ada satu piring.","en":"There is a plate on the table."}},{"hz":"鍋","mw":"個","ex":{"zh":"媽媽在用鍋煮湯。","py":"mā ma zài yòng guō zhǔ tāng","id":"Ibu sedang memasak sup dengan panci.","en":"Mom is cooking soup in a pot."}},{"hz":"菜刀","mw":"把","ex":{"zh":"菜刀很鋒利，請小心。","py":"cài dāo hěn fēng lì qǐng xiǎo xīn","id":"Pisau dapurnya sangat tajam, hati-hati ya.","en":"The kitchen knife is very sharp. Please be careful."}},{"hz":"垃圾桶","mw":"個","ex":{"zh":"垃圾桶在門口。","py":"lè sè tǒng zài mén kǒu","id":"Tempat sampah ada di depan pintu.","en":"The trash can is by the door."}}]},{"title":{"id":"Di kamar mandi","en":"In the bathroom"},"words":[{"hz":"毛巾","mw":"條","ex":{"zh":"這條毛巾是新的。","py":"zhè tiáo máo jīn shì xīn de","id":"Handuk ini baru.","en":"This towel is new."}},{"hz":"牙刷","mw":"支","ex":{"zh":"這支牙刷是我的。","py":"zhè zhī yá shuā shì wǒ de","id":"Sikat gigi ini milikku.","en":"This toothbrush is mine."}},{"hz":"牙膏","mw":"條","ex":{"zh":"牙膏用完了。","py":"yá gāo yòng wán le","id":"Pasta giginya sudah habis.","en":"The toothpaste is used up."}},{"hz":"肥皂","mw":"塊","ex":{"zh":"洗手要用肥皂。","py":"xǐ shǒu yào yòng féi zào","id":"Cuci tangan harus pakai sabun.","en":"You need to use soap to wash your hands."}},{"hz":"衛生紙","mw":"包","ex":{"zh":"廁所沒有衛生紙了。","py":"cè suǒ méi yǒu wèi shēng zhǐ le","id":"Di toilet tidak ada tisu toilet lagi.","en":"There is no more toilet paper in the restroom."}},{"hz":"洗衣機","mw":"台","ex":{"zh":"洗衣機在浴室旁邊。","py":"xǐ yī jī zài yù shì páng biān","id":"Mesin cuci ada di samping kamar mandi.","en":"The washing machine is next to the bathroom."}},{"hz":"拖鞋","mw":"雙","ex":{"zh":"進門請換拖鞋。","py":"jìn mén qǐng huàn tuō xié","id":"Masuk rumah tolong ganti sandal rumah.","en":"Please change into slippers when you come in."}}]},{"title":{"id":"Alat tulis","en":"Stationery"},"words":[{"hz":"書","mw":"本","ex":{"zh":"我桌上有三本書。","py":"wǒ zhuō shàng yǒu sān běn shū","id":"Di mejaku ada tiga buku.","en":"There are three books on my desk."}},{"hz":"筆","mw":"支","ex":{"zh":"你有筆嗎？","py":"nǐ yǒu bǐ ma","id":"Kamu punya pulpen?","en":"Do you have a pen?"}},{"hz":"紙","mw":"張","ex":{"zh":"請給我一張紙。","py":"qǐng gěi wǒ yì zhāng zhǐ","id":"Tolong beri aku selembar kertas.","en":"Please give me a sheet of paper."}},{"hz":"課本","mw":"本","ex":{"zh":"我忘了帶課本。","py":"wǒ wàng le dài kè běn","id":"Aku lupa membawa buku pelajaran.","en":"I forgot to bring my textbook."}},{"hz":"筆記本","mw":"本","ex":{"zh":"這本筆記本很便宜。","py":"zhè běn bǐ jì běn hěn pián yi","id":"Buku catatan ini murah sekali.","en":"This notebook is very cheap."}},{"hz":"橡皮擦","mw":"個","ex":{"zh":"我的橡皮擦不見了。","py":"wǒ de xiàng pí cā bú jiàn le","id":"Penghapusku hilang.","en":"My eraser is missing."}},{"hz":"膠帶","mw":"捲","ex":{"zh":"你有膠帶嗎？","py":"nǐ yǒu jiāo dài ma","id":"Kamu punya selotip?","en":"Do you have any tape?"}},{"hz":"書包","mw":"個","ex":{"zh":"我的書包很重。","py":"wǒ de shū bāo hěn zhòng","id":"Tasku berat sekali.","en":"My schoolbag is very heavy."}}]},{"title":{"id":"Barang bawaan sehari-hari","en":"Things you carry every day"},"words":[{"hz":"手機","mw":"支","ex":{"zh":"我的手機沒電了。","py":"wǒ de shǒu jī méi diàn le","id":"Baterai ponselku habis.","en":"My phone is out of battery."}},{"hz":"鑰匙","mw":"把","ex":{"zh":"我找不到鑰匙。","py":"wǒ zhǎo bú dào yào shi","id":"Aku tidak bisa menemukan kunci.","en":"I can't find my keys."}},{"hz":"錢包","mw":"個","ex":{"zh":"他的錢包是黑色的。","py":"tā de qián bāo shì hēi sè de","id":"Dompetnya berwarna hitam.","en":"His wallet is black."}},{"hz":"眼鏡","mw":"副","ex":{"zh":"我的眼鏡在哪裡？","py":"wǒ de yǎn jìng zài nǎ lǐ","id":"Di mana kacamataku?","en":"Where are my glasses?"}},{"hz":"雨傘","mw":"把","ex":{"zh":"出門要帶雨傘。","py":"chū mén yào dài yǔ sǎn","id":"Kalau keluar rumah harus bawa payung.","en":"You need to bring an umbrella when you go out."}},{"hz":"手錶","mw":"支","ex":{"zh":"這支手錶很漂亮。","py":"zhè zhī shǒu biǎo hěn piào liang","id":"Jam tangan ini cantik sekali.","en":"This watch is very pretty."}},{"hz":"袋子","mw":"個","ex":{"zh":"你需要袋子嗎？","py":"nǐ xū yào dài zi ma","id":"Kamu perlu kantong?","en":"Do you need a bag?"}},{"hz":"電腦","mw":"台","ex":{"zh":"我用電腦寫功課。","py":"wǒ yòng diàn nǎo xiě gōng kè","id":"Aku mengerjakan PR dengan komputer.","en":"I do my homework on the computer."}}]},{"title":{"id":"Rumah dan perabot","en":"House and furniture"},"words":[{"hz":"房子","ex":{"zh":"這棟房子很大。","py":"zhè dòng fáng zi hěn dà","id":"Rumah ini besar.","en":"This house is big."},"mw":"棟"},{"hz":"屋子","ex":{"zh":"屋子裡很涼快。","py":"wū zi lǐ hěn liáng kuài","id":"Di dalam rumah sejuk.","en":"It is cool inside the house."},"mw":"間"},{"hz":"院子","ex":{"zh":"他家有一個小院子。","py":"tā jiā yǒu yí ge xiǎo yuàn zi","id":"Rumahnya punya halaman kecil.","en":"His home has a small yard."},"mw":"個"},{"hz":"桌子","ex":{"zh":"桌子上有一本書。","py":"zhuō zi shàng yǒu yì běn shū","id":"Di atas meja ada sebuah buku.","en":"There is a book on the table."},"mw":"張"},{"hz":"椅子","ex":{"zh":"請坐這張椅子。","py":"qǐng zuò zhè zhāng yǐ zi","id":"Silakan duduk di kursi ini.","en":"Please sit on this chair."},"mw":"張"},{"hz":"櫃子","ex":{"zh":"衣服在櫃子裡。","py":"yī fú zài guì zi lǐ","id":"Bajunya ada di dalam lemari.","en":"The clothes are in the cabinet."},"mw":"個"},{"hz":"窗子","ex":{"zh":"請把窗子打開。","py":"qǐng bǎ chuāng zi dǎ kāi","id":"Tolong buka jendelanya.","en":"Please open the window."},"mw":"扇"}]},{"title":{"id":"Alat makan dan perkakas kecil","en":"Utensils and small tools"},"words":[{"hz":"筷子","ex":{"zh":"我用筷子吃飯。","py":"wǒ yòng kuài zi chī fàn","id":"Aku makan dengan sumpit.","en":"I eat with chopsticks."},"mw":"雙"},{"hz":"叉子","ex":{"zh":"這支叉子是新的。","py":"zhè zhī chā zi shì xīn de","id":"Garpu ini baru.","en":"This fork is new."},"mw":"支"},{"hz":"刀子","ex":{"zh":"請給我一把刀子。","py":"qǐng gěi wǒ yì bǎ dāo zi","id":"Tolong beri aku sebuah pisau.","en":"Please give me a knife."},"mw":"把"},{"hz":"杯子","ex":{"zh":"桌上有兩個杯子。","py":"zhuō shàng yǒu liǎng ge bēi zi","id":"Di atas meja ada dua gelas.","en":"There are two cups on the table."},"mw":"個"},{"hz":"刷子","ex":{"zh":"請用刷子洗杯子。","py":"qǐng yòng shuā zi xǐ bēi zi","id":"Tolong cuci gelas pakai sikat.","en":"Please wash the cup with a brush."},"mw":"把"},{"hz":"籃子","ex":{"zh":"籃子裡有很多蘋果。","py":"lán zi lǐ yǒu hěn duō píng guǒ","id":"Di dalam keranjang ada banyak apel.","en":"There are many apples in the basket."},"mw":"個"}]}],"grammar":[{"title":{"id":"Menyebut jumlah benda: Num + kata satuan + benda","en":"Counting things"},"pattern":"Num + MW + N","note":{"id":"Dalam bahasa Mandarin, angka tidak langsung diikuti benda, harus ada kata satuan (MW) di antaranya, misalnya 一本書, 兩把傘. Kata satuan tergantung bendanya: 本 untuk buku, 把 untuk benda bergagang, 張 untuk benda datar. Untuk angka dua sebelum kata satuan pakai 兩, bukan 二.","en":"In Mandarin a number cannot go directly before a noun; a measure word comes in between, e.g. 一本書, 兩把傘. The measure word depends on the noun: 本 for books, 把 for objects with a handle, 張 for flat things. Use 兩, not 二, for 'two' before a measure word."},"ex":[{"zh":"我有兩把雨傘。","py":"wǒ yǒu liǎng bǎ yǔ sǎn","id":"Aku punya dua payung.","en":"I have two umbrellas."},{"zh":"書包裡有三本書。","py":"shū bāo lǐ yǒu sān běn shū","id":"Di dalam tas ada tiga buku.","en":"There are three books in the bag."},{"zh":"請給我兩張紙。","py":"qǐng gěi wǒ liǎng zhāng zhǐ","id":"Tolong beri aku dua lembar kertas.","en":"Please give me two sheets of paper."}]},{"title":{"id":"Menyatakan letak: Benda + 在 + tempat","en":"Saying where something is"},"pattern":"N + 在 + Place","note":{"id":"Untuk mengatakan sebuah benda berada di suatu tempat, pakai 在. Setelah nama tempat sering ditambah 上 (di atas), 裡 (di dalam), atau 旁邊 (di samping). Orang Indonesia sering lupa menambahkan 裡 atau 上 setelah kata benda tempat.","en":"Use 在 to say where something is. After a thing-noun used as a place, you usually add 上 (on), 裡 (in) or 旁邊 (next to). Learners often forget to add 裡 or 上 after such nouns."},"ex":[{"zh":"鑰匙在書包裡。","py":"yào shi zài shū bāo lǐ","id":"Kuncinya ada di dalam tas.","en":"The keys are in the bag."},{"zh":"手機在沙發上。","py":"shǒu jī zài shā fā shàng","id":"Ponselnya ada di atas sofa.","en":"The phone is on the sofa."},{"zh":"洗衣機在浴室旁邊。","py":"xǐ yī jī zài yù shì páng biān","id":"Mesin cuci ada di samping kamar mandi.","en":"The washing machine is next to the bathroom."}]},{"title":{"id":"Menyatakan ada apa di suatu tempat: Tempat + 有 + benda","en":"Saying what is in a place"},"pattern":"Place + 有 + N","note":{"id":"Untuk mengatakan 'di tempat ini ada benda ini', susunannya tempat dulu, lalu 有, lalu benda. Bandingkan: 冰箱裡有牛奶 (di kulkas ada susu) dan 牛奶在冰箱裡 (susu ada di kulkas). Kalimat dengan 有 memperkenalkan benda baru, kalimat dengan 在 menunjukkan letak benda yang sudah diketahui. Negatifnya 沒有, bukan 不有.","en":"To say 'there is X in this place', put the place first, then 有, then the thing. Compare 冰箱裡有牛奶 (there is milk in the fridge) with 牛奶在冰箱裡 (the milk is in the fridge). 有 introduces something new; 在 locates something already known. The negative is 沒有, never 不有."},"ex":[{"zh":"客廳有一台電視。","py":"kè tīng yǒu yì tái diàn shì","id":"Di ruang tamu ada satu televisi.","en":"There is a TV in the living room."},{"zh":"房間裡有一張床。","py":"fáng jiān lǐ yǒu yì zhāng chuáng","id":"Di dalam kamar ada satu tempat tidur.","en":"There is a bed in the room."},{"zh":"桌上沒有筆。","py":"zhuō shàng méi yǒu bǐ","id":"Di atas meja tidak ada pulpen.","en":"There is no pen on the table."}]},{"title":{"id":"Menanyakan pemilik: 這是誰的 + benda?","en":"Asking whose something is"},"pattern":"這是誰的 + N？ / 這是我的 + N","note":{"id":"Untuk menanyakan pemilik, pakai 誰的 (milik siapa). Untuk menjawab, pakai 的 setelah pemilik: 我的, 老師的. Benda yang sudah jelas boleh dihilangkan: 這是我的 (ini milikku).","en":"Ask who owns something with 誰的. Answer with 的 after the owner: 我的, 老師的. If the object is clear you can drop it: 這是我的 (this is mine)."},"ex":[{"zh":"這是誰的雨傘？","py":"zhè shì shéi de yǔ sǎn","id":"Ini payung siapa?","en":"Whose umbrella is this?"},{"zh":"這是我朋友的書。","py":"zhè shì wǒ péng yǒu de shū","id":"Ini buku temanku.","en":"This is my friend's book."},{"zh":"那是我的。","py":"nà shì wǒ de","id":"Itu punyaku.","en":"That one is mine."}]}],"dialog":[{"sp":"A","zh":"你看到我的鑰匙了嗎？","py":"nǐ kàn dào wǒ de yào shi le ma","id":"Kamu lihat kunciku tidak?","en":"Have you seen my keys?"},{"sp":"B","zh":"沒看到。你在書包裡找找看。","py":"méi kàn dào nǐ zài shū bāo lǐ zhǎo zhǎo kàn","id":"Nggak lihat. Coba cari di dalam tasmu.","en":"No, I haven't. Try looking in your bag."},{"sp":"A","zh":"書包裡只有手機和錢包。","py":"shū bāo lǐ zhǐ yǒu shǒu jī hé qián bāo","id":"Di dalam tas cuma ada ponsel dan dompet.","en":"There are only a phone and a wallet in my bag."},{"sp":"B","zh":"你看，在沙發上！","py":"nǐ kàn zài shā fā shàng","id":"Lihat, ada di atas sofa!","en":"Look, they are on the sofa!"},{"sp":"A","zh":"找到了！謝謝你。","py":"zhǎo dào le xiè xie nǐ","id":"Ketemu! Terima kasih ya.","en":"Found them! Thank you."},{"sp":"B","zh":"快出門吧，要帶雨傘喔。","py":"kuài chū mén ba yào dài yǔ sǎn o","id":"Ayo cepat keluar, jangan lupa bawa payung ya.","en":"Let's go. Remember to bring an umbrella."}],"n":"01"},{"k":"makan","zh":"食物飲料","py":"shí wù yǐn liào","title":{"id":"Makanan dan minuman","en":"Food and drinks","tl":"Pagkain at inumin","vi":"Đồ ăn và thức uống"},"desc":{"id":"Kamu bisa menyebut makanan dan minuman Taiwan, lalu memesan di warung atau restoran.","en":"You can name Taiwanese foods and drinks and order at a food stall or restaurant."},"icon":"food","sets":[{"title":{"id":"Waktu makan dan lauk pokok","en":"Meals and staples"},"words":[{"hz":"早餐","mw":"份","ex":{"zh":"我每天吃早餐。","py":"wǒ měi tiān chī zǎo cān","id":"Aku sarapan setiap hari.","en":"I eat breakfast every day."}},{"hz":"午餐","mw":"份","ex":{"zh":"午餐你想吃什麼？","py":"wǔ cān nǐ xiǎng chī shén me","id":"Kamu mau makan apa untuk makan siang?","en":"What do you want for lunch?"}},{"hz":"晚餐","mw":"份","ex":{"zh":"今天晚餐我們吃火鍋。","py":"jīn tiān wǎn cān wǒ men chī huǒ guō","id":"Makan malam hari ini kita makan hot pot.","en":"We are having hot pot for dinner today."}},{"hz":"飯","mw":"碗","ex":{"zh":"我想吃一碗飯。","py":"wǒ xiǎng chī yì wǎn fàn","id":"Aku mau makan semangkuk nasi.","en":"I want a bowl of rice."}},{"hz":"麵","mw":"碗","ex":{"zh":"我喜歡吃麵。","py":"wǒ xǐ huān chī miàn","id":"Aku suka makan mi.","en":"I like eating noodles."}},{"hz":"蛋","mw":"顆","ex":{"zh":"早餐我吃了兩顆蛋。","py":"zǎo cān wǒ chī le liǎng kē dàn","id":"Waktu sarapan aku makan dua butir telur.","en":"I ate two eggs for breakfast."}},{"hz":"肉","ex":{"zh":"我不吃肉。","py":"wǒ bù chī ròu","id":"Aku tidak makan daging.","en":"I don't eat meat."}},{"hz":"魚","mw":"條","ex":{"zh":"這條魚很新鮮。","py":"zhè tiáo yú hěn xīn xiān","id":"Ikan ini sangat segar.","en":"This fish is very fresh."}}]},{"title":{"id":"Makanan khas Taiwan","en":"Taiwanese food"},"words":[{"hz":"牛肉麵","mw":"碗","ex":{"zh":"台灣的牛肉麵很有名。","py":"tái wān de niú ròu miàn hěn yǒu míng","id":"Mi daging sapi Taiwan sangat terkenal.","en":"Taiwan's beef noodles are very famous."}},{"hz":"滷肉飯","mw":"碗","ex":{"zh":"我想吃一碗滷肉飯。","py":"wǒ xiǎng chī yì wǎn lǔ ròu fàn","id":"Aku mau makan semangkuk nasi daging babi kecap.","en":"I want a bowl of braised pork rice."}},{"hz":"小籠包","mw":"籠","ex":{"zh":"這家的小籠包很好吃。","py":"zhè jiā de xiǎo lóng bāo hěn hǎo chī","id":"Xiaolongbao di toko ini enak sekali.","en":"The soup dumplings at this place are delicious."}},{"hz":"臭豆腐","mw":"份","ex":{"zh":"夜市有很多臭豆腐。","py":"yè shì yǒu hěn duō chòu dòu fu","id":"Di pasar malam ada banyak tahu bau.","en":"There is a lot of stinky tofu at the night market."}},{"hz":"蛋餅","mw":"份","ex":{"zh":"我早上常吃蛋餅。","py":"wǒ zǎo shàng cháng chī dàn bǐng","id":"Pagi hari aku sering makan dan bing (dadar gulung).","en":"I often eat egg crepes in the morning."}},{"hz":"飯糰","mw":"個","ex":{"zh":"便利商店有賣飯糰。","py":"biàn lì shāng diàn yǒu mài fàn tuán","id":"Minimarket menjual onigiri (nasi kepal).","en":"The convenience store sells rice balls."}},{"hz":"鹹酥雞","mw":"份","ex":{"zh":"晚上我想吃鹹酥雞。","py":"wǎn shàng wǒ xiǎng chī xián sū jī","id":"Malam ini aku mau makan ayam goreng tepung (xiansuji).","en":"I want to eat fried chicken bites tonight."}},{"hz":"便當","mw":"個","ex":{"zh":"我在學校買便當。","py":"wǒ zài xué xiào mǎi biàn dāng","id":"Aku beli bento di sekolah.","en":"I buy a lunch box at school."}},{"hz":"餃子","ex":{"zh":"我們晚上吃餃子。","py":"wǒ men wǎn shàng chī jiǎo zi","id":"Malam ini kami makan pangsit.","en":"We're having dumplings tonight."},"mw":"顆"}]},{"title":{"id":"Buah-buahan","en":"Fruit"},"words":[{"hz":"水果","ex":{"zh":"我常常吃水果。","py":"wǒ cháng cháng chī shuǐ guǒ","id":"Aku sering makan buah.","en":"I often eat fruit."}},{"hz":"蘋果","mw":"顆","ex":{"zh":"這顆蘋果很甜。","py":"zhè kē píng guǒ hěn tián","id":"Apel ini manis sekali.","en":"This apple is very sweet."}},{"hz":"香蕉","mw":"根","ex":{"zh":"我要一根香蕉。","py":"wǒ yào yì gēn xiāng jiāo","id":"Aku mau satu pisang.","en":"I would like a banana."}},{"hz":"西瓜","mw":"顆","ex":{"zh":"夏天我最愛吃西瓜。","py":"xià tiān wǒ zuì ài chī xī guā","id":"Waktu musim panas aku paling suka makan semangka.","en":"In summer I love eating watermelon the most."}},{"hz":"芒果","mw":"顆","ex":{"zh":"台灣的芒果很好吃。","py":"tái wān de máng guǒ hěn hǎo chī","id":"Mangga Taiwan enak sekali.","en":"Taiwan's mangoes are delicious."}},{"hz":"鳳梨","mw":"顆","ex":{"zh":"這個鳳梨有一點酸。","py":"zhè ge fèng lí yǒu yì diǎn suān","id":"Nanas ini agak asam.","en":"This pineapple is a little sour."}},{"hz":"葡萄","mw":"串","ex":{"zh":"你要吃葡萄嗎？","py":"nǐ yào chī pú tao ma","id":"Kamu mau makan anggur?","en":"Do you want some grapes?"}},{"hz":"草莓","mw":"顆","ex":{"zh":"草莓一盒多少錢？","py":"cǎo méi yì hé duō shǎo qián","id":"Stroberi satu kotak berapa harganya?","en":"How much is a box of strawberries?"}},{"hz":"橘子","ex":{"zh":"這些橘子很甜。","py":"zhè xiē jú zi hěn tián","id":"Jeruk-jeruk ini manis sekali.","en":"These tangerines are very sweet."},"mw":"顆"}]},{"title":{"id":"Minuman","en":"Drinks"},"words":[{"hz":"水","mw":"杯","ex":{"zh":"請給我一杯水。","py":"qǐng gěi wǒ yì bēi shuǐ","id":"Tolong beri aku segelas air.","en":"Please give me a glass of water."}},{"hz":"茶","mw":"杯","ex":{"zh":"我想喝熱茶。","py":"wǒ xiǎng hē rè chá","id":"Aku mau minum teh hangat.","en":"I want to drink hot tea."}},{"hz":"咖啡","mw":"杯","ex":{"zh":"他每天早上喝咖啡。","py":"tā měi tiān zǎo shàng hē kā fēi","id":"Dia minum kopi setiap pagi.","en":"He drinks coffee every morning."}},{"hz":"牛奶","mw":"杯","ex":{"zh":"我早餐喝牛奶。","py":"wǒ zǎo cān hē niú nǎi","id":"Aku minum susu saat sarapan.","en":"I drink milk for breakfast."}},{"hz":"果汁","mw":"杯","ex":{"zh":"你要喝果汁嗎？","py":"nǐ yào hē guǒ zhī ma","id":"Kamu mau minum jus?","en":"Do you want some juice?"}},{"hz":"珍珠奶茶","mw":"杯","ex":{"zh":"我要一杯珍珠奶茶。","py":"wǒ yào yì bēi zhēn zhū nǎi chá","id":"Aku mau satu gelas teh susu boba.","en":"I would like a bubble milk tea."}},{"hz":"豆漿","mw":"杯","ex":{"zh":"早餐店的豆漿很好喝。","py":"zǎo cān diàn de dòu jiāng hěn hǎo hē","id":"Susu kedelai di kedai sarapan enak sekali.","en":"The soy milk at the breakfast shop is delicious."}},{"hz":"可樂","mw":"杯","ex":{"zh":"我不喝可樂。","py":"wǒ bù hē kě lè","id":"Aku tidak minum cola.","en":"I don't drink cola."}}]},{"title":{"id":"Memesan di restoran","en":"Ordering at a restaurant"},"words":[{"hz":"菜單","mw":"份","ex":{"zh":"請給我菜單。","py":"qǐng gěi wǒ cài dān","id":"Tolong beri aku menunya.","en":"Please give me the menu."}},{"hz":"點餐","ex":{"zh":"我們可以點餐了嗎？","py":"wǒ men kě yǐ diǎn cān le ma","id":"Boleh kami pesan sekarang?","en":"Can we order now?"}},{"hz":"外帶","ex":{"zh":"這個要外帶。","py":"zhè ge yào wài dài","id":"Yang ini dibawa pulang.","en":"This one is to go."}},{"hz":"內用","ex":{"zh":"請問內用還是外帶？","py":"qǐng wèn nèi yòng hái shi wài dài","id":"Permisi, makan di sini atau dibawa pulang?","en":"Excuse me, dine in or takeout?"}},{"hz":"套餐","mw":"份","ex":{"zh":"套餐有附飲料嗎？","py":"tào cān yǒu fù yǐn liào ma","id":"Paketnya sudah termasuk minuman?","en":"Does the set meal come with a drink?"}},{"hz":"服務生","mw":"位","ex":{"zh":"服務生，請給我水。","py":"fú wù shēng qǐng gěi wǒ shuǐ","id":"Mas, tolong beri saya air.","en":"Waiter, please give me some water."}},{"hz":"好吃","ex":{"zh":"這家餐廳的菜很好吃。","py":"zhè jiā cān tīng de cài hěn hǎo chī","id":"Masakan di restoran ini enak sekali.","en":"The food at this restaurant is delicious."}},{"hz":"辣","ex":{"zh":"這個菜太辣了。","py":"zhè ge cài tài là le","id":"Masakan ini terlalu pedas.","en":"This dish is too spicy."}}]}],"grammar":[{"title":{"id":"Memesan: 我要 + Num + kata satuan + makanan/minuman","en":"Ordering food and drinks"},"pattern":"我要 + Num + MW + N","note":{"id":"Untuk memesan, pakai 我要 diikuti jumlah, kata satuan, dan nama makanan: 我要一碗麵. Kata satuan minuman biasanya 杯, nasi dan mi 碗. Untuk bilang 'dua', pakai 兩, bukan 二. Tambahkan 請 atau 謝謝 supaya lebih sopan.","en":"To order, use 我要 plus a number, a measure word and the food: 我要一碗麵. Drinks usually take 杯, rice and noodles take 碗. Use 兩, not 二, for 'two'. Add 請 or 謝謝 to sound polite."},"ex":[{"zh":"我要一碗牛肉麵。","py":"wǒ yào yì wǎn niú ròu miàn","id":"Aku mau satu mangkuk mi daging sapi.","en":"I would like a bowl of beef noodles."},{"zh":"老闆，我要兩杯珍珠奶茶。","py":"lǎo bǎn wǒ yào liǎng bēi zhēn zhū nǎi chá","id":"Bos, aku mau dua gelas teh susu boba.","en":"Boss, I would like two bubble milk teas."}]},{"title":{"id":"Terlalu...: 太 + sifat + 了","en":"Too much of something"},"pattern":"太 + Adj + 了","note":{"id":"太...了 biasanya berarti 'terlalu...' (ada kesan kurang baik), misalnya untuk rasa 辣 (pedas), 甜 (manis), 鹹 (asin). Dalam seruan seperti 太好了! artinya 'sekali!'. Kalau hanya mau bilang 'sangat' secara netral, pakai 很. Jangan lupa 了 di akhir.","en":"太...了 usually means 'too ...' (a bit negative), e.g. for tastes like 辣 (spicy), 甜 (sweet), 鹹 (salty). In exclamations like 太好了! it means 'so ...!'. To say 'very' neutrally, use 很. Don't forget 了 at the end."},"ex":[{"zh":"這杯茶太甜了。","py":"zhè bēi chá tài tián le","id":"Teh ini terlalu manis.","en":"This tea is too sweet."},{"zh":"這碗麵太鹹了。","py":"zhè wǎn miàn tài xián le","id":"Mi ini terlalu asin.","en":"This bowl of noodles is too salty."},{"zh":"今天太熱了，我想喝冰茶。","py":"jīn tiān tài rè le wǒ xiǎng hē bīng chá","id":"Hari ini terlalu panas, aku mau minum es teh.","en":"It is too hot today. I want an iced tea."}]},{"title":{"id":"Pertanyaan pilihan: A 還是 B？","en":"Choice questions"},"pattern":"A 還是 B？","note":{"id":"Untuk menawarkan dua pilihan dalam pertanyaan, pakai 還是 di antara kedua pilihan, tanpa 嗎. Jangan pakai 或是 untuk pertanyaan, karena 或是 dipakai dalam kalimat pernyataan.","en":"To offer two choices in a question, put 還是 between them and do not add 嗎. Don't use 或是 in questions; it is for statements."},"ex":[{"zh":"你要茶還是咖啡？","py":"nǐ yào chá hái shi kā fēi","id":"Kamu mau teh atau kopi?","en":"Do you want tea or coffee?"},{"zh":"你要吃飯還是吃麵？","py":"nǐ yào chī fàn hái shi chī miàn","id":"Kamu mau makan nasi atau mi?","en":"Do you want rice or noodles?"}]},{"title":{"id":"Menanyakan apakah sudah: V + 了嗎？","en":"Asking if something is done"},"pattern":"V + 了嗎？","note":{"id":"Untuk menanyakan apakah suatu hal sudah dilakukan, tambahkan 了嗎 di akhir kalimat. Orang Taiwan sering menyapa dengan 你吃飯了嗎？ (sudah makan?). Jawaban: 吃了 (sudah) atau 還沒 (belum), bukan 不吃.","en":"To ask whether something has happened, add 了嗎 at the end. Taiwanese people often greet with 你吃飯了嗎？ (Have you eaten?). Answer 吃了 (yes) or 還沒 (not yet), not 不吃."},"ex":[{"zh":"你吃早餐了嗎？","py":"nǐ chī zǎo cān le ma","id":"Kamu sudah sarapan?","en":"Have you had breakfast?"},{"zh":"你吃飽了嗎？","py":"nǐ chī bǎo le ma","id":"Kamu sudah kenyang?","en":"Are you full?"},{"zh":"我吃飽了，謝謝。","py":"wǒ chī bǎo le xiè xie","id":"Aku sudah kenyang, terima kasih.","en":"I'm full, thank you."}]}],"dialog":[{"sp":"A","zh":"你好，請問要吃什麼？","py":"nǐ hǎo qǐng wèn yào chī shén me","id":"Halo, mau makan apa?","en":"Hello, what would you like?"},{"sp":"B","zh":"我要一份蛋餅和一杯豆漿。","py":"wǒ yào yí fèn dàn bǐng hé yì bēi dòu jiāng","id":"Aku mau satu porsi dan bing (dadar telur) dan segelas susu kedelai.","en":"I'd like an egg crepe and a soy milk."},{"sp":"A","zh":"蛋餅要加辣嗎？","py":"dàn bǐng yào jiā là ma","id":"Dan bing-nya mau ditambah sambal?","en":"Do you want spicy sauce on the egg crepe?"},{"sp":"B","zh":"不要辣，謝謝。","py":"bú yào là xiè xie","id":"Tidak usah pedas, terima kasih.","en":"No spicy, thank you."},{"sp":"A","zh":"內用還是外帶？","py":"nèi yòng hái shi wài dài","id":"Makan di sini atau dibawa pulang?","en":"Dine in or takeout?"},{"sp":"B","zh":"內用。一共多少錢？","py":"nèi yòng yí gòng duō shǎo qián","id":"Makan di sini. Totalnya berapa?","en":"Dine in. How much is it in total?"},{"sp":"A","zh":"一共七十五元。","py":"yí gòng qī shí wǔ yuán","id":"Totalnya tujuh puluh lima dolar NT.","en":"That's 75 dollars in total."}],"n":"02"},{"k":"orang","zh":"家人朋友","py":"jiā rén péng yǒu","title":{"id":"Keluarga dan teman","en":"Family and friends","tl":"Pamilya at mga kaibigan","vi":"Gia đình và bạn bè"},"desc":{"id":"Kamu bisa memperkenalkan keluarga, teman, dan asal negaramu, serta menyapa orang dengan sopan.","en":"You can introduce your family, friends and nationality, and address people politely."},"icon":"people","sets":[{"title":{"id":"Keluarga inti","en":"Close family"},"words":[{"hz":"爸爸","ex":{"zh":"我爸爸在銀行工作。","py":"wǒ bà ba zài yín háng gōng zuò","id":"Ayahku bekerja di bank.","en":"My dad works at a bank."}},{"hz":"媽媽","ex":{"zh":"我媽媽做的菜很好吃。","py":"wǒ mā ma zuò de cài hěn hǎo chī","id":"Masakan ibuku enak sekali.","en":"The food my mom cooks is delicious."}},{"hz":"哥哥","ex":{"zh":"我哥哥在台北工作。","py":"wǒ gē ge zài tái běi gōng zuò","id":"Kakak laki-lakiku bekerja di Taipei.","en":"My older brother works in Taipei."}},{"hz":"姊姊","ex":{"zh":"我姊姊今年二十五歲。","py":"wǒ jiě jie jīn nián èr shí wǔ suì","id":"Kakak perempuanku tahun ini berumur dua puluh lima.","en":"My older sister is twenty-five this year."}},{"hz":"弟弟","ex":{"zh":"我弟弟還是學生。","py":"wǒ dì di hái shi xué shēng","id":"Adik laki-lakiku masih pelajar.","en":"My younger brother is still a student."}},{"hz":"妹妹","ex":{"zh":"我妹妹喜歡看電影。","py":"wǒ mèi mei xǐ huān kàn diàn yǐng","id":"Adik perempuanku suka menonton film.","en":"My younger sister likes watching movies."}},{"hz":"爺爺","ex":{"zh":"爺爺每天早上散步。","py":"yé ye měi tiān zǎo shàng sàn bù","id":"Kakek berjalan-jalan setiap pagi.","en":"Grandpa goes for a walk every morning."}},{"hz":"奶奶","ex":{"zh":"我奶奶住在高雄。","py":"wǒ nǎi nai zhù zài gāo xióng","id":"Nenekku tinggal di Kaohsiung.","en":"My grandma lives in Kaohsiung."}}]},{"title":{"id":"Anggota keluarga lain","en":"Wider family"},"words":[{"hz":"家人","ex":{"zh":"我很愛我的家人。","py":"wǒ hěn ài wǒ de jiā rén","id":"Aku sangat sayang keluargaku.","en":"I love my family very much."}},{"hz":"父母","ex":{"zh":"我父母住在印尼。","py":"wǒ fù mǔ zhù zài yìn ní","id":"Orang tuaku tinggal di Indonesia.","en":"My parents live in Indonesia."}},{"hz":"兒子","mw":"個","ex":{"zh":"他有一個兒子。","py":"tā yǒu yí ge ér zi","id":"Dia punya satu anak laki-laki.","en":"He has a son."}},{"hz":"女兒","mw":"個","ex":{"zh":"他的女兒五歲了。","py":"tā de nǚ ér wǔ suì le","id":"Anak perempuannya sudah berumur lima tahun.","en":"His daughter is five now."}},{"hz":"孩子","mw":"個","ex":{"zh":"這些孩子在公園玩。","py":"zhè xiē hái zi zài gōng yuán wán","id":"Anak-anak ini bermain di taman.","en":"These children are playing in the park."}},{"hz":"阿姨","mw":"位","ex":{"zh":"阿姨送我一個禮物。","py":"ā yí sòng wǒ yí ge lǐ wù","id":"Tante memberiku sebuah hadiah.","en":"My aunt gave me a present."}},{"hz":"叔叔","mw":"位","ex":{"zh":"我叔叔是醫生。","py":"wǒ shú shu shì yī shēng","id":"Pamanku seorang dokter.","en":"My uncle is a doctor."}},{"hz":"小孩","ex":{"zh":"那個小孩很可愛。","py":"nà ge xiǎo hái hěn kě ài","id":"Anak kecil itu lucu sekali.","en":"That child is very cute."},"mw":"個"}]},{"title":{"id":"Teman dan sapaan","en":"Friends and forms of address"},"words":[{"hz":"朋友","mw":"個","ex":{"zh":"他是我的好朋友。","py":"tā shì wǒ de hǎo péng yǒu","id":"Dia teman baikku.","en":"He is my good friend."}},{"hz":"同學","mw":"位","ex":{"zh":"他是我的同學。","py":"tā shì wǒ de tóng xué","id":"Dia teman sekelasku.","en":"He is my classmate."}},{"hz":"老師","mw":"位","ex":{"zh":"王老師教我們中文。","py":"wáng lǎo shī jiāo wǒ men zhōng wén","id":"Guru Wang mengajar kami bahasa Mandarin.","en":"Teacher Wang teaches us Chinese."}},{"hz":"室友","mw":"個","ex":{"zh":"我的室友是日本人。","py":"wǒ de shì yǒu shì rì běn rén","id":"Teman sekamarku orang Jepang.","en":"My roommate is Japanese."}},{"hz":"男朋友","mw":"個","ex":{"zh":"小美有男朋友嗎？","py":"xiǎo měi yǒu nán péng yǒu ma","id":"Apakah Xiaomei punya pacar?","en":"Does Xiaomei have a boyfriend?"}},{"hz":"女朋友","mw":"個","ex":{"zh":"他的女朋友是台灣人。","py":"tā de nǚ péng yǒu shì tái wān rén","id":"Pacarnya orang Taiwan.","en":"His girlfriend is Taiwanese."}},{"hz":"鄰居","mw":"位","ex":{"zh":"我的鄰居很友善。","py":"wǒ de lín jū hěn yǒu shàn","id":"Tetanggaku ramah sekali.","en":"My neighbor is very friendly."}},{"hz":"先生","mw":"位","ex":{"zh":"王先生，你好。","py":"wáng xiān sheng nǐ hǎo","id":"Halo, Tuan Wang.","en":"Hello, Mr. Wang."}},{"hz":"小姐","mw":"位","ex":{"zh":"林小姐在等你。","py":"lín xiǎo jiě zài děng nǐ","id":"Nona Lin sedang menunggumu.","en":"Miss Lin is waiting for you."}}]},{"title":{"id":"Kata ganti orang","en":"Pronouns"},"words":[{"hz":"我","ex":{"zh":"我叫小明，我是學生。","py":"wǒ jiào xiǎo míng wǒ shì xué shēng","id":"Namaku Xiaoming, aku seorang pelajar.","en":"My name is Xiaoming. I am a student."}},{"hz":"你","ex":{"zh":"你叫什麼名字？","py":"nǐ jiào shén me míng zi","id":"Siapa namamu?","en":"What is your name?"}},{"hz":"您","ex":{"zh":"老師，您好！","py":"lǎo shī nín hǎo","id":"Halo, Pak/Bu Guru!","en":"Hello, teacher!"}},{"hz":"他","ex":{"zh":"他是我的同事。","py":"tā shì wǒ de tóng shì","id":"Dia rekan kerjaku.","en":"He is my coworker."}},{"hz":"我們","ex":{"zh":"我們一起去夜市吧。","py":"wǒ men yì qǐ qù yè shì ba","id":"Ayo kita pergi ke pasar malam bersama.","en":"Let's go to the night market together."}},{"hz":"你們","ex":{"zh":"你們要去哪裡？","py":"nǐ men yào qù nǎ lǐ","id":"Kalian mau pergi ke mana?","en":"Where are you going?"}},{"hz":"他們","ex":{"zh":"他們是我的朋友。","py":"tā men shì wǒ de péng yǒu","id":"Mereka teman-temanku.","en":"They are my friends."}},{"hz":"大家","ex":{"zh":"大家好，我是小明。","py":"dà jiā hǎo wǒ shì xiǎo míng","id":"Halo semuanya, aku Xiaoming.","en":"Hello everyone, I'm Xiaoming."}}]},{"title":{"id":"Asal negara","en":"Nationalities"},"words":[{"hz":"台灣人","mw":"位","ex":{"zh":"我朋友是台灣人。","py":"wǒ péng yǒu shì tái wān rén","id":"Temanku orang Taiwan.","en":"My friend is Taiwanese."}},{"hz":"日本人","mw":"位","ex":{"zh":"他不是日本人。","py":"tā bú shì rì běn rén","id":"Dia bukan orang Jepang.","en":"He is not Japanese."}},{"hz":"美國人","mw":"位","ex":{"zh":"這位老師是美國人。","py":"zhè wèi lǎo shī shì měi guó rén","id":"Guru ini orang Amerika.","en":"This teacher is American."}},{"hz":"韓國人","mw":"位","ex":{"zh":"我認識一個韓國人。","py":"wǒ rèn shi yí ge hán guó rén","id":"Aku kenal satu orang Korea.","en":"I know a Korean person."}},{"hz":"印尼人","mw":"位","ex":{"zh":"他們都是印尼人。","py":"tā men dōu shì yìn ní rén","id":"Mereka semua orang Indonesia.","en":"They are all Indonesian."}},{"hz":"越南人","mw":"位","ex":{"zh":"這位客人是越南人。","py":"zhè wèi kè rén shì yuè nán rén","id":"Tamu ini orang Vietnam.","en":"This guest is Vietnamese."}},{"hz":"泰國人","mw":"位","ex":{"zh":"泰國人也喜歡吃辣。","py":"tài guó rén yě xǐ huān chī là","id":"Orang Thailand juga suka makanan pedas.","en":"Thai people also like spicy food."}},{"hz":"外國人","mw":"位","ex":{"zh":"台北有很多外國人。","py":"tái běi yǒu hěn duō wài guó rén","id":"Di Taipei ada banyak orang asing.","en":"There are many foreigners in Taipei."}}]}],"grammar":[{"title":{"id":"Menyatakan identitas: A 是 B","en":"Saying who someone is"},"pattern":"A + 是 / 不是 + B","note":{"id":"Pakai 是 untuk menyatakan identitas atau kebangsaan: 我是印尼人. Negatifnya 不是 (dibaca bú shì). Jangan pakai 是 sebelum kata sifat, misalnya bilang 他是高 itu salah; yang benar 他很高.","en":"Use 是 to state identity or nationality: 我是印尼人. The negative is 不是 (pronounced bú shì). Don't use 是 before an adjective: 他是高 is wrong; say 他很高."},"ex":[{"zh":"我是學生，不是老師。","py":"wǒ shì xué shēng bú shì lǎo shī","id":"Aku seorang pelajar, bukan guru.","en":"I am a student, not a teacher."},{"zh":"林先生是台灣人。","py":"lín xiān sheng shì tái wān rén","id":"Tuan Lin orang Taiwan.","en":"Mr. Lin is Taiwanese."}]},{"title":{"id":"Kepemilikan: 的","en":"Possession with 的"},"pattern":"Pemilik + 的 + N","note":{"id":"Untuk menyatakan kepemilikan, taruh 的 di antara pemilik dan bendanya: 我的室友. Untuk anggota keluarga atau tempat yang dekat, 的 biasanya dihilangkan: 我媽媽, 我們學校. Urutan kata berbeda dari bahasa Indonesia: pemilik di depan, bukan di belakang.","en":"Put 的 between the owner and the thing: 我的室友. For close family or places, 的 is usually dropped: 我媽媽, 我們學校. Unlike Indonesian, the owner comes first, not last."},"ex":[{"zh":"我媽媽是老師。","py":"wǒ mā ma shì lǎo shī","id":"Ibuku seorang guru.","en":"My mom is a teacher."},{"zh":"那是我朋友的書。","py":"nà shì wǒ péng yǒu de shū","id":"Itu buku temanku.","en":"That is my friend's book."},{"zh":"我們學校很大。","py":"wǒ men xué xiào hěn dà","id":"Sekolah kami besar.","en":"Our school is big."}]},{"title":{"id":"Menyebut jumlah orang: 有 + Num + 個 + orang","en":"Counting family and friends"},"pattern":"(我/我家) 有 + Num + 個 + N","note":{"id":"Untuk menyebut jumlah anggota keluarga atau teman, pakai 有 + angka + kata satuan 個. Untuk menghormati orang, bisa pakai 位 (misalnya 三位老師). 'Dua' sebelum kata satuan adalah 兩, bukan 二. Untuk jumlah anggota keluarga: 我家有五個人.","en":"To say how many family members or friends you have, use 有 + number + the measure word 個 (位 is more polite). 'Two' before a measure word is 兩, not 二. For family size: 我家有五個人."},"ex":[{"zh":"我家有五個人。","py":"wǒ jiā yǒu wǔ ge rén","id":"Keluargaku ada lima orang.","en":"There are five people in my family."},{"zh":"我有一個姊姊和兩個弟弟。","py":"wǒ yǒu yí ge jiě jie hé liǎng ge dì di","id":"Aku punya satu kakak perempuan dan dua adik laki-laki.","en":"I have one older sister and two younger brothers."},{"zh":"你有兄弟姊妹嗎？","py":"nǐ yǒu xiōng dì jiě mèi ma","id":"Kamu punya saudara kandung?","en":"Do you have any brothers or sisters?"}]},{"title":{"id":"Jamak dan 都 / 也: 們, 都, 也","en":"Plurals and 都 / 也"},"pattern":"我們 / 他們 + 都 / 也 + V","note":{"id":"們 membuat kata ganti jadi jamak: 我們, 你們, 他們. 都 berarti 'semua' dan 也 berarti 'juga'; keduanya diletakkan setelah subjek dan sebelum kata kerja atau 是. Kesalahan umum: menaruh 也 atau 都 di akhir kalimat seperti dalam bahasa Indonesia.","en":"們 makes pronouns plural: 我們, 你們, 他們. 都 means 'all' and 也 means 'also'; both go after the subject and before the verb or 是. A common mistake is putting them at the end of the sentence."},"ex":[{"zh":"我們都是學生。","py":"wǒ men dōu shì xué shēng","id":"Kami semua pelajar.","en":"We are all students."},{"zh":"你們也是學生嗎？","py":"nǐ men yě shì xué shēng ma","id":"Apakah kalian juga pelajar?","en":"Are you students too?"},{"zh":"他們也是印尼人。","py":"tā men yě shì yìn ní rén","id":"Mereka juga orang Indonesia.","en":"They are also Indonesian."}]}],"dialog":[{"sp":"A","zh":"你好，我叫小明。你是哪國人？","py":"nǐ hǎo wǒ jiào xiǎo míng nǐ shì nǎ guó rén","id":"Halo, namaku Xiaoming. Kamu orang mana?","en":"Hello, I'm Xiaoming. Where are you from?"},{"sp":"B","zh":"我是越南人。你呢？","py":"wǒ shì yuè nán rén nǐ ne","id":"Aku orang Vietnam. Kamu?","en":"I'm Vietnamese. And you?"},{"sp":"A","zh":"我是印尼人。我們都是外國人。","py":"wǒ shì yìn ní rén wǒ men dōu shì wài guó rén","id":"Aku orang Indonesia. Kita sama-sama orang asing.","en":"I'm Indonesian. We are both foreigners."},{"sp":"B","zh":"對啊！你的家人也在台灣嗎？","py":"duì a nǐ de jiā rén yě zài tái wān ma","id":"Iya! Apakah keluargamu juga ada di Taiwan?","en":"Yes! Is your family in Taiwan too?"},{"sp":"A","zh":"不在，我爸爸媽媽在印尼。","py":"bú zài wǒ bà ba mā ma zài yìn ní","id":"Tidak, ayah dan ibuku ada di Indonesia.","en":"No, my mom and dad are in Indonesia."},{"sp":"B","zh":"我哥哥在台灣工作，我常常去找他。","py":"wǒ gē ge zài tái wān gōng zuò wǒ cháng cháng qù zhǎo tā","id":"Kakakku bekerja di Taiwan, aku sering mengunjunginya.","en":"My older brother works in Taiwan, and I often go see him."}],"n":"03"},{"k":"kerja","zh":"職業工作","py":"zhí yè gōng zuò","title":{"id":"Pekerjaan","en":"Jobs and work","tl":"Trabaho","vi":"Nghề nghiệp và công việc"},"desc":{"id":"Kamu bisa menyebut profesi, bercerita tentang tempat dan jam kerja, serta membahas gaji dan cari kerja.","en":"You can name jobs, talk about your workplace and working hours, and discuss pay and job hunting."},"icon":"work","sets":[{"title":{"id":"Profesi sehari-hari","en":"Everyday jobs"},"words":[{"hz":"老師","ex":{"zh":"他是我的老師。","py":"tā shì wǒ de lǎo shī","id":"Dia guruku.","en":"He is my teacher."},"mw":"位"},{"hz":"醫生","ex":{"zh":"醫生說我要多休息。","py":"yī shēng shuō wǒ yào duō xiū xí","id":"Dokter bilang aku harus banyak istirahat.","en":"The doctor says I need to rest more."},"mw":"位"},{"hz":"護士","ex":{"zh":"那位護士很親切。","py":"nà wèi hù shì hěn qīn qiè","id":"Perawat itu ramah sekali.","en":"That nurse is very kind."},"mw":"位"},{"hz":"司機","ex":{"zh":"計程車司機很會開車。","py":"jì chéng chē sī jī hěn huì kāi chē","id":"Sopir taksi itu jago menyetir.","en":"The taxi driver is a really good driver."},"mw":"位"},{"hz":"工程師","ex":{"zh":"我哥哥是工程師。","py":"wǒ gē ge shì gōng chéng shī","id":"Kakak laki-lakiku seorang insinyur.","en":"My older brother is an engineer."},"mw":"位"},{"hz":"設計師","ex":{"zh":"她是一位設計師。","py":"tā shì yí wèi shè jì shī","id":"Dia seorang desainer.","en":"She is a designer."},"mw":"位"},{"hz":"服務生","ex":{"zh":"服務生請我們坐這裡。","py":"fú wù shēng qǐng wǒ men zuò zhè lǐ","id":"Pelayan mempersilakan kami duduk di sini.","en":"The waiter asks us to sit here."},"mw":"位"},{"hz":"老闆","ex":{"zh":"老闆今天不在公司。","py":"lǎo bǎn jīn tiān bú zài gōng sī","id":"Bos tidak ada di kantor hari ini.","en":"The boss is not at the company today."},"mw":"位"},{"hz":"店員","ex":{"zh":"店員正在幫客人。","py":"diàn yuán zhèng zài bāng kè rén","id":"Pegawai toko sedang melayani pelanggan.","en":"The shop clerk is helping a customer."},"mw":"位"},{"hz":"工人","ex":{"zh":"工人在蓋大樓。","py":"gōng rén zài gài dà lóu","id":"Para pekerja sedang membangun gedung.","en":"The workers are putting up a building."},"mw":"位"}]},{"title":{"id":"Profesi lainnya","en":"More jobs"},"words":[{"hz":"外送員","ex":{"zh":"外送員把便當送來了。","py":"wài sòng yuán bǎ biàn dāng sòng lái le","id":"Kurir makanan sudah mengantarkan nasi kotaknya.","en":"The delivery person brought the lunch box."},"mw":"位"},{"hz":"快遞員","ex":{"zh":"快遞員送來一個包裹。","py":"kuài dì yuán sòng lái yí ge bāo guǒ","id":"Kurir mengantarkan sebuah paket.","en":"The courier delivered a parcel."},"mw":"位"},{"hz":"牙醫","ex":{"zh":"我下午要去看牙醫。","py":"wǒ xià wǔ yào qù kàn yá yī","id":"Sore ini aku mau ke dokter gigi.","en":"I'm going to see the dentist this afternoon."},"mw":"位"},{"hz":"藥師","ex":{"zh":"藥師告訴我怎麼吃藥。","py":"yào shī gào sù wǒ zěn me chī yào","id":"Apoteker memberi tahu aku cara minum obat.","en":"The pharmacist told me how to take the medicine."},"mw":"位"},{"hz":"消防員","ex":{"zh":"消防員很勇敢。","py":"xiāo fáng yuán hěn yǒng gǎn","id":"Petugas pemadam kebakaran sangat berani.","en":"Firefighters are very brave."},"mw":"位"},{"hz":"攤販","ex":{"zh":"夜市有很多攤販。","py":"yè shì yǒu hěn duō tān fàn","id":"Di pasar malam ada banyak pedagang kaki lima.","en":"There are many stall vendors at the night market."},"mw":"位"},{"hz":"銀行員","ex":{"zh":"銀行員在櫃台工作。","py":"yín háng yuán zài guì tái gōng zuò","id":"Pegawai bank bekerja di loket.","en":"The bank clerk works at the counter."},"mw":"位"},{"hz":"實習生","ex":{"zh":"我是公司的實習生。","py":"wǒ shì gōng sī de shí xí shēng","id":"Aku peserta magang di perusahaan.","en":"I am an intern at the company."},"mw":"位"}]},{"title":{"id":"Di tempat kerja","en":"At the workplace"},"words":[{"hz":"公司","ex":{"zh":"我的公司在台北。","py":"wǒ de gōng sī zài tái běi","id":"Perusahaanku ada di Taipei.","en":"My company is in Taipei."},"mw":"家"},{"hz":"辦公室","ex":{"zh":"辦公室在三樓。","py":"bàn gōng shì zài sān lóu","id":"Kantornya ada di lantai tiga.","en":"The office is on the third floor."},"mw":"間"},{"hz":"電腦","ex":{"zh":"電腦壞了，我不能工作。","py":"diàn nǎo huài le wǒ bù néng gōng zuò","id":"Komputernya rusak, aku tidak bisa bekerja.","en":"The computer is broken, so I can't work."},"mw":"台"},{"hz":"經理","ex":{"zh":"經理在開會。","py":"jīng lǐ zài kāi huì","id":"Manajer sedang rapat.","en":"The manager is in a meeting."},"mw":"位"},{"hz":"上班","ex":{"zh":"我每天騎機車上班。","py":"wǒ měi tiān qí jī chē shàng bān","id":"Setiap hari aku naik motor ke tempat kerja.","en":"I ride my scooter to work every day."}},{"hz":"下班","ex":{"zh":"下班以後我想去夜市。","py":"xià bān yǐ hòu wǒ xiǎng qù yè shì","id":"Setelah pulang kerja aku mau ke pasar malam.","en":"After work I want to go to the night market."}},{"hz":"開會","ex":{"zh":"我們下午兩點開會。","py":"wǒ men xià wǔ liǎng diǎn kāi huì","id":"Kita rapat jam dua siang.","en":"We have a meeting at two this afternoon."}},{"hz":"加班","ex":{"zh":"今天我要加班。","py":"jīn tiān wǒ yào jiā bān","id":"Hari ini aku harus lembur.","en":"I have to work overtime today."}},{"hz":"打卡","ex":{"zh":"上班要先打卡。","py":"shàng bān yào xiān dǎ kǎ","id":"Sebelum bekerja harus absen dulu.","en":"You have to clock in first when you start work."}},{"hz":"午休","ex":{"zh":"午休時間有一個小時。","py":"wǔ xiū shí jiān yǒu yí ge xiǎo shí","id":"Waktu istirahat siang satu jam.","en":"The lunch break is one hour."}}]},{"title":{"id":"Kerja dan gaji","en":"Working and pay"},"words":[{"hz":"工作","ex":{"zh":"你在哪裡工作？","py":"nǐ zài nǎ lǐ gōng zuò","id":"Kamu bekerja di mana?","en":"Where do you work?"}},{"hz":"找工作","ex":{"zh":"他正在找工作。","py":"tā zhèng zài zhǎo gōng zuò","id":"Dia sedang mencari pekerjaan.","en":"He is looking for a job."}},{"hz":"面試","ex":{"zh":"明天我有一個面試。","py":"míng tiān wǒ yǒu yí ge miàn shì","id":"Besok aku ada wawancara kerja.","en":"I have an interview tomorrow."},"mw":"次"},{"hz":"打工","ex":{"zh":"我在便利商店打工。","py":"wǒ zài biàn lì shāng diàn dǎ gōng","id":"Aku kerja paruh waktu di minimarket.","en":"I work part-time at a convenience store."}},{"hz":"賺錢","ex":{"zh":"我想賺錢買機車。","py":"wǒ xiǎng zhuàn qián mǎi jī chē","id":"Aku mau cari uang untuk beli motor.","en":"I want to earn money to buy a scooter."}},{"hz":"月薪","ex":{"zh":"他的月薪是三萬元。","py":"tā de yuè xīn shì sān wàn yuán","id":"Gaji bulanannya tiga puluh ribu dolar Taiwan.","en":"His monthly salary is 30,000 dollars."}},{"hz":"時薪","ex":{"zh":"這裡的時薪是一百八十元。","py":"zhè lǐ de shí xīn shì yì bǎi bā shí yuán","id":"Upah per jam di sini seratus delapan puluh dolar Taiwan.","en":"The hourly wage here is 180 dollars."}},{"hz":"努力","ex":{"zh":"他每天都很努力。","py":"tā měi tiān dōu hěn nǔ lì","id":"Dia setiap hari berusaha keras.","en":"He works hard every day."}},{"hz":"忙","ex":{"zh":"最近工作很忙。","py":"zuì jìn gōng zuò hěn máng","id":"Akhir-akhir ini kerjaan lagi sibuk sekali.","en":"Work has been very busy lately."}}]}],"grammar":[{"title":{"id":"Menyebut profesi: 是 + pekerjaan","en":"Saying your job"},"pattern":"S + 是 + 職業","note":{"id":"Untuk menyebut profesi pakai 是, lalu nama profesinya, tanpa kata sandang. Untuk bertanya: 你做什麼工作？ (kamu kerja apa?). Orang Indonesia sering lupa 是 dan langsung bilang 我老師; ingat bahwa 是 wajib di sini.","en":"Use 是 followed by the job title, with no article. To ask: 你做什麼工作? Learners often drop 是 (我老師), but it is required here."},"ex":[{"zh":"他是醫生。","py":"tā shì yī shēng","id":"Dia seorang dokter.","en":"He is a doctor."},{"zh":"你做什麼工作？","py":"nǐ zuò shén me gōng zuò","id":"Kamu kerja apa?","en":"What do you do for work?"},{"zh":"我姊姊是護士。","py":"wǒ jiě jie shì hù shì","id":"Kakak perempuanku seorang perawat.","en":"My older sister is a nurse."}]},{"title":{"id":"Bekerja di suatu tempat: 在 + tempat + 工作","en":"Working at a place"},"pattern":"S + 在 + 地點 + 工作/上班","note":{"id":"Dalam bahasa Mandarin keterangan tempat (在 + tempat) diletakkan SEBELUM kata kerja, tidak sesudahnya seperti bahasa Indonesia ('bekerja di kantor'). Jadi: 我在公司工作, bukan 我工作在公司.","en":"The place phrase (在 + place) goes BEFORE the verb, unlike English or Indonesian word order. Say 我在公司工作, not 我工作在公司."},"ex":[{"zh":"我在公司上班。","py":"wǒ zài gōng sī shàng bān","id":"Aku bekerja di perusahaan.","en":"I work at a company."},{"zh":"她在醫院工作。","py":"tā zài yī yuàn gōng zuò","id":"Dia bekerja di rumah sakit.","en":"She works at a hospital."},{"zh":"我哥哥在銀行上班。","py":"wǒ gē ge zài yín háng shàng bān","id":"Kakakku bekerja di bank.","en":"My older brother works at a bank."}]},{"title":{"id":"Waktu sebelum kata kerja","en":"Time words before the verb"},"pattern":"S + 時間 + V","note":{"id":"Kata waktu (jam berapa, hari apa) diletakkan sebelum kata kerja, biasanya setelah subjek (boleh juga di awal kalimat). Contoh: 我九點上班. Jangan taruh waktu di akhir kalimat seperti 'Aku kerja jam sembilan'.","en":"Time expressions go before the verb, usually right after the subject (or at the very start of the sentence): 我九點上班. Do not put the time at the end of the sentence."},"ex":[{"zh":"我早上九點上班。","py":"wǒ zǎo shàng jiǔ diǎn shàng bān","id":"Aku mulai kerja jam sembilan pagi.","en":"I start work at nine in the morning."},{"zh":"他六點下班。","py":"tā liù diǎn xià bān","id":"Dia pulang kerja jam enam.","en":"He gets off work at six."},{"zh":"我們下午三點開會。","py":"wǒ men xià wǔ sān diǎn kāi huì","id":"Kita rapat jam tiga sore.","en":"We have a meeting at three in the afternoon."}]},{"title":{"id":"Urutan kegiatan: 先…再…","en":"First…then…"},"pattern":"先 + V1，再 + V2","note":{"id":"先 berarti 'dulu' dan 再 berarti 'lalu/setelah itu'. Pola ini dipakai untuk menjelaskan urutan dua kegiatan. 先 dan 再 diletakkan di depan kata kerja masing-masing.","en":"先 means 'first' and 再 means 'then'. Use the pattern to give the order of two actions; each goes right before its verb."},"ex":[{"zh":"我先打卡，再去辦公室。","py":"wǒ xiān dǎ kǎ zài qù bàn gōng shì","id":"Aku absen dulu, baru ke kantor.","en":"I clock in first, then go to the office."},{"zh":"下班以後我先吃飯，再回家。","py":"xià bān yǐ hòu wǒ xiān chī fàn zài huí jiā","id":"Setelah pulang kerja aku makan dulu, baru pulang.","en":"After work I eat first, then go home."}]}],"dialog":[{"zh":"你現在在哪裡工作？","py":"nǐ xiàn zài zài nǎ lǐ gōng zuò","id":"Sekarang kamu bekerja di mana?","en":"Where do you work now?","sp":"A"},{"zh":"我在台北的一家公司上班。","py":"wǒ zài tái běi de yì jiā gōng sī shàng bān","id":"Aku bekerja di sebuah perusahaan di Taipei.","en":"I work at a company in Taipei.","sp":"B"},{"zh":"你做什麼工作？","py":"nǐ zuò shén me gōng zuò","id":"Kamu kerja sebagai apa?","en":"What do you do?","sp":"A"},{"zh":"我是工程師，常常加班。","py":"wǒ shì gōng chéng shī cháng cháng jiā bān","id":"Aku insinyur, sering lembur.","en":"I'm an engineer and often work overtime.","sp":"B"},{"zh":"那你一定很忙。","py":"nà nǐ yí dìng hěn máng","id":"Kalau begitu kamu pasti sibuk sekali.","en":"Then you must be very busy.","sp":"A"},{"zh":"對啊，可是老闆人很好。","py":"duì a kě shì lǎo bǎn rén hěn hǎo","id":"Iya, tapi bosnya baik.","en":"Yes, but my boss is a nice person.","sp":"B"},{"zh":"你幾點下班？","py":"nǐ jǐ diǎn xià bān","id":"Kamu pulang kerja jam berapa?","en":"What time do you get off work?","sp":"A"},{"zh":"平常六點，今天可能要晚一點。","py":"píng cháng liù diǎn jīn tiān kě néng yào wǎn yì diǎn","id":"Biasanya jam enam, tapi hari ini mungkin agak telat.","en":"Usually at six, but today it may be a bit later.","sp":"B"}],"n":"04"},{"k":"tubuh","zh":"身體健康","py":"shēn tǐ jiàn kāng","title":{"id":"Tubuh dan kesehatan","en":"Body and health","tl":"Katawan at kalusugan","vi":"Cơ thể và sức khỏe"},"desc":{"id":"Kamu bisa menyebut bagian tubuh, menjelaskan keluhan sakit, dan berbicara dengan dokter atau apoteker.","en":"You can name body parts, describe symptoms, and talk to a doctor or pharmacist."},"icon":"body","sets":[{"title":{"id":"Kepala dan wajah","en":"Head and face"},"words":[{"hz":"頭","ex":{"zh":"我的頭很痛。","py":"wǒ de tóu hěn tòng","id":"Kepalaku sakit sekali.","en":"My head hurts a lot."},"mw":"顆"},{"hz":"頭髮","ex":{"zh":"她的頭髮很長。","py":"tā de tóu fǎ hěn cháng","id":"Rambutnya panjang.","en":"Her hair is very long."}},{"hz":"臉","ex":{"zh":"他的臉很紅。","py":"tā de liǎn hěn hóng","id":"Wajahnya merah sekali.","en":"His face is very red."},"mw":"張"},{"hz":"眼睛","ex":{"zh":"我的眼睛很累。","py":"wǒ de yǎn jīng hěn lèi","id":"Mataku sangat lelah.","en":"My eyes are very tired."},"mw":"雙"},{"hz":"耳朵","ex":{"zh":"她的耳朵很小。","py":"tā de ěr duo hěn xiǎo","id":"Telinganya kecil.","en":"Her ears are small."},"mw":"隻"},{"hz":"嘴巴","ex":{"zh":"請張開你的嘴巴。","py":"qǐng zhāng kāi nǐ de zuǐ ba","id":"Tolong buka mulutmu.","en":"Please open your mouth."},"mw":"張"},{"hz":"額頭","ex":{"zh":"他的額頭很燙。","py":"tā de é tóu hěn tàng","id":"Dahinya panas sekali.","en":"His forehead is very hot."}},{"hz":"鼻子","ex":{"zh":"他的鼻子很高。","py":"tā de bí zi hěn gāo","id":"Hidungnya mancung.","en":"He has a high nose."},"mw":"個"},{"hz":"脖子","ex":{"zh":"我的脖子有一點痛。","py":"wǒ de bó zi yǒu yì diǎn tòng","id":"Leherku agak sakit.","en":"My neck hurts a little."}}]},{"title":{"id":"Badan, tangan, dan kaki","en":"Body, hands and feet"},"words":[{"hz":"身體","ex":{"zh":"運動對身體很好。","py":"yùn dòng duì shēn tǐ hěn hǎo","id":"Olahraga baik untuk tubuh.","en":"Exercise is good for the body."}},{"hz":"手","ex":{"zh":"我的手很冷。","py":"wǒ de shǒu hěn lěng","id":"Tanganku dingin sekali.","en":"My hands are very cold."},"mw":"隻"},{"hz":"手臂","ex":{"zh":"我的手臂有一點痛。","py":"wǒ de shǒu bì yǒu yì diǎn tòng","id":"Lengan saya agak sakit.","en":"My arm hurts a little."},"mw":"隻"},{"hz":"手指","ex":{"zh":"他的手指很長。","py":"tā de shǒu zhǐ hěn cháng","id":"Jari-jarinya panjang.","en":"His fingers are very long."},"mw":"根"},{"hz":"背","ex":{"zh":"我的背很痠。","py":"wǒ de bèi hěn suān","id":"Punggungku pegal sekali.","en":"My back is very sore."}},{"hz":"腿","ex":{"zh":"我的腿好痠，走不動了。","py":"wǒ de tuǐ hǎo suān zǒu bú dòng le","id":"Kakiku pegal sekali, sudah tidak kuat jalan.","en":"My legs are so sore I can't walk any more."},"mw":"條"},{"hz":"膝蓋","ex":{"zh":"他的膝蓋受傷了。","py":"tā de xī gài shòu shāng le","id":"Lututnya terluka.","en":"His knee is injured."}},{"hz":"腳","ex":{"zh":"我的腳好痛。","py":"wǒ de jiǎo hǎo tòng","id":"Kakiku sakit sekali.","en":"My foot really hurts."},"mw":"隻"},{"hz":"腳趾","ex":{"zh":"我的腳趾被踩到了。","py":"wǒ de jiǎo zhǐ bèi cǎi dào le","id":"Jari kakiku terinjak.","en":"My toe got stepped on."},"mw":"根"},{"hz":"肚子","ex":{"zh":"我的肚子很餓。","py":"wǒ de dù zi hěn è","id":"Perutku lapar sekali.","en":"I'm really hungry."}}]},{"title":{"id":"Keluhan sakit","en":"Feeling sick"},"words":[{"hz":"不舒服","ex":{"zh":"我今天不舒服。","py":"wǒ jīn tiān bù shū fu","id":"Hari ini aku tidak enak badan.","en":"I don't feel well today."}},{"hz":"感冒","ex":{"zh":"我感冒了。","py":"wǒ gǎn mào le","id":"Aku kena flu.","en":"I caught a cold."}},{"hz":"發燒","ex":{"zh":"孩子昨天發燒了。","py":"hái zi zuó tiān fā shāo le","id":"Anak itu kemarin demam.","en":"The child had a fever yesterday."}},{"hz":"咳嗽","ex":{"zh":"我一直咳嗽。","py":"wǒ yì zhí ké sòu","id":"Aku batuk terus.","en":"I keep coughing."}},{"hz":"頭痛","ex":{"zh":"我頭痛得睡不著。","py":"wǒ tóu tòng de shuì bù zháo","id":"Kepalaku sakit sampai tidak bisa tidur.","en":"My head hurts so much I can't sleep."}},{"hz":"頭暈","ex":{"zh":"我有一點頭暈。","py":"wǒ yǒu yì diǎn tóu yūn","id":"Aku agak pusing.","en":"I feel a little dizzy."}},{"hz":"肚子痛","ex":{"zh":"我肚子痛，想去廁所。","py":"wǒ dù zi tòng xiǎng qù cè suǒ","id":"Perutku sakit, aku mau ke toilet.","en":"I have a stomachache and want to go to the toilet."}},{"hz":"喉嚨痛","ex":{"zh":"我喉嚨痛，不能說話。","py":"wǒ hóu lóng tòng bù néng shuō huà","id":"Tenggorokanku sakit, tidak bisa bicara.","en":"My throat is sore and I can't talk."}},{"hz":"流鼻水","ex":{"zh":"我一直流鼻水。","py":"wǒ yì zhí liú bí shuǐ","id":"Hidungku meler terus.","en":"My nose keeps running."}},{"hz":"牙痛","ex":{"zh":"我牙痛，不能吃東西。","py":"wǒ yá tòng bù néng chī dōng xi","id":"Gigiku sakit, tidak bisa makan.","en":"I have a toothache and can't eat."}}]},{"title":{"id":"Ke dokter dan obat","en":"Seeing a doctor"},"words":[{"hz":"看病","ex":{"zh":"我明天要去看病。","py":"wǒ míng tiān yào qù kàn bìng","id":"Besok aku mau berobat ke dokter.","en":"I'm going to see a doctor tomorrow."}},{"hz":"掛號","ex":{"zh":"你先去掛號。","py":"nǐ xiān qù guà hào","id":"Kamu daftar dulu.","en":"Go register first."}},{"hz":"健保卡","ex":{"zh":"看病要帶健保卡。","py":"kàn bìng yào dài jiàn bǎo kǎ","id":"Kalau berobat harus bawa kartu asuransi kesehatan.","en":"Bring your NHI card when you see a doctor."},"mw":"張"},{"hz":"量體溫","ex":{"zh":"進醫院要先量體溫。","py":"jìn yī yuàn yào xiān liáng tǐ wēn","id":"Masuk rumah sakit harus ukur suhu badan dulu.","en":"You need to take your temperature before entering the hospital."}},{"hz":"吃藥","ex":{"zh":"飯後要吃藥。","py":"fàn hòu yào chī yào","id":"Obatnya diminum sesudah makan.","en":"Take the medicine after meals."}},{"hz":"感冒藥","ex":{"zh":"這是感冒藥，一天三次。","py":"zhè shì gǎn mào yào yì tiān sān cì","id":"Ini obat flu, diminum tiga kali sehari.","en":"This is cold medicine, three times a day."}},{"hz":"藥局","ex":{"zh":"附近有一家藥局。","py":"fù jìn yǒu yì jiā yào jú","id":"Di dekat sini ada apotek.","en":"There is a pharmacy nearby."},"mw":"家"},{"hz":"請病假","ex":{"zh":"我今天要請病假。","py":"wǒ jīn tiān yào qǐng bìng jià","id":"Hari ini aku mau izin sakit.","en":"I'm taking sick leave today."}},{"hz":"休息","ex":{"zh":"你要多休息。","py":"nǐ yào duō xiū xí","id":"Kamu harus banyak istirahat.","en":"You need to rest more."}},{"hz":"早日康復","ex":{"zh":"祝你早日康復。","py":"zhù nǐ zǎo rì kāng fù","id":"Semoga lekas sembuh.","en":"I wish you a speedy recovery."}}]}],"grammar":[{"title":{"id":"Bagian tubuh yang sakit","en":"Saying a body part hurts"},"pattern":"身體部位 + 很痛 / 我的 + 部位 + 很痛","note":{"id":"Untuk bilang bagian tubuh sakit, sebut bagian tubuhnya lalu 痛. Dalam kalimat biasanya ada 很/好 sebelum 痛 (tanpa itu kalimat terdengar menggantung), kecuali bentuk gabungan seperti 頭痛, 牙痛. Untuk sakit ringan pakai 有一點痛.","en":"Name the body part and add 痛. In a sentence you usually put 很 or 好 before 痛 (except in set words like 頭痛, 牙痛). For mild pain use 有一點痛."},"ex":[{"zh":"我的肚子很痛。","py":"wǒ de dù zi hěn tòng","id":"Perutku sakit sekali.","en":"My stomach really hurts."},{"zh":"他的腳有一點痛。","py":"tā de jiǎo yǒu yì diǎn tòng","id":"Kakinya agak sakit.","en":"His foot hurts a bit."},{"zh":"我的牙好痛。","py":"wǒ de yá hǎo tòng","id":"Gigiku sakit sekali.","en":"My tooth hurts so much."}]},{"title":{"id":"Sedikit tidak enak: 有一點 + sifat","en":"A bit (unpleasant): 有一點"},"pattern":"S + 有一點 + Adj/V","note":{"id":"有一點 berarti 'agak', biasanya untuk hal yang tidak nyaman: 我有一點累 (aku agak capek). Letaknya sebelum kata sifat. Berbeda dengan 一點 yang ditaruh sesudah kata sifat: 便宜一點 (murah sedikit).","en":"有一點 means 'a bit', usually for something unpleasant, and goes before the adjective. Compare 一點 after the adjective: 便宜一點 'a little cheaper'."},"ex":[{"zh":"我有一點累。","py":"wǒ yǒu yì diǎn lèi","id":"Aku agak capek.","en":"I'm a little tired."},{"zh":"今天有一點冷。","py":"jīn tiān yǒu yì diǎn lěng","id":"Hari ini agak dingin.","en":"It's a bit cold today."},{"zh":"他有一點發燒。","py":"tā yǒu yì diǎn fā shāo","id":"Dia agak demam.","en":"He has a slight fever."}]},{"title":{"id":"Saran: 要多 + kata kerja","en":"Giving advice: 要多 + V"},"pattern":"你要多 + V","note":{"id":"要多 + kata kerja berarti 'harus lebih banyak …'. Ini cara umum memberi saran sehat di Taiwan, misalnya 多休息, 多喝水. 多 diletakkan sebelum kata kerja, tidak sesudahnya.","en":"要多 + verb means 'you should … more'. It is the usual way to give health advice, and 多 goes before the verb."},"ex":[{"zh":"你要多喝水。","py":"nǐ yào duō hē shuǐ","id":"Kamu harus lebih banyak minum air.","en":"You should drink more water."},{"zh":"生病要多休息。","py":"shēng bìng yào duō xiū xí","id":"Kalau sakit harus banyak istirahat.","en":"When you're sick you should rest more."}]},{"title":{"id":"Perubahan keadaan: …了","en":"New situation: …了"},"pattern":"S + V/Adj + 了","note":{"id":"了 di akhir kalimat menunjukkan keadaan baru: 我感冒了 (aku jadi/sudah kena flu), 我好多了 (aku sudah jauh lebih baik). Jangan lupa 了 saat bercerita bahwa kamu baru sakit atau sudah sembuh.","en":"Sentence-final 了 shows a change of state: 我感冒了 'I've caught a cold', 我好多了 'I'm much better now'."},"ex":[{"zh":"我發燒了。","py":"wǒ fā shāo le","id":"Aku demam.","en":"I have a fever now."},{"zh":"我好多了。","py":"wǒ hǎo duō le","id":"Aku sudah jauh lebih baik.","en":"I'm much better now."}]}],"dialog":[{"zh":"你的臉色不太好，怎麼了？","py":"nǐ de liǎn sè bú tài hǎo zěn me le","id":"Mukamu kelihatan kurang sehat, kenapa?","en":"You don't look well. What's wrong?","sp":"A"},{"zh":"我昨天開始頭痛，還有一點發燒。","py":"wǒ zuó tiān kāi shǐ tóu tòng hái yǒu yì diǎn fā shāo","id":"Sejak kemarin kepalaku sakit, dan agak demam.","en":"My head has hurt since yesterday, and I have a slight fever.","sp":"B"},{"zh":"你有量體溫嗎？","py":"nǐ yǒu liáng tǐ wēn ma","id":"Kamu sudah ukur suhu badan?","en":"Did you take your temperature?","sp":"A"},{"zh":"有，三十八度。","py":"yǒu sān shí bā dù","id":"Sudah, tiga puluh delapan derajat.","en":"Yes, 38 degrees.","sp":"B"},{"zh":"你應該去看病，記得帶健保卡。","py":"nǐ yīng gāi qù kàn bìng jì de dài jiàn bǎo kǎ","id":"Kamu sebaiknya berobat, ingat bawa kartu asuransi kesehatan.","en":"You should see a doctor. Remember to bring your NHI card.","sp":"A"},{"zh":"好，我下班以後就去。","py":"hǎo wǒ xià bān yǐ hòu jiù qù","id":"Baik, setelah pulang kerja aku langsung pergi.","en":"Okay, I'll go right after work.","sp":"B"},{"zh":"吃完藥要多休息喔。","py":"chī wán yào yào duō xiū xí o","id":"Setelah minum obat, banyak istirahat ya.","en":"After taking the medicine, rest a lot.","sp":"A"},{"zh":"謝謝你。","py":"xiè xie nǐ","id":"Terima kasih.","en":"Thank you.","sp":"B"}],"n":"05"},{"k":"pakaian","zh":"衣服顏色","py":"yī fú yán sè","title":{"id":"Pakaian dan warna","en":"Clothes and colors","tl":"Damit at kulay","vi":"Quần áo và màu sắc"},"desc":{"id":"Kamu bisa menyebut pakaian, sepatu, aksesori, dan warna, serta memilih dan mencoba baju di toko.","en":"You can name clothes, shoes, accessories and colors, and shop for and try on clothing."},"icon":"shirt","sets":[{"title":{"id":"Pakaian","en":"Clothes"},"words":[{"hz":"衣服","ex":{"zh":"這件衣服很好看。","py":"zhè jiàn yī fu hěn hǎo kàn","id":"Baju ini bagus sekali.","en":"This top looks nice."},"mw":"件"},{"hz":"外套","ex":{"zh":"外面很冷，穿外套吧。","py":"wài miàn hěn lěng chuān wài tào ba","id":"Di luar dingin, pakai jaket saja.","en":"It's cold outside, put on a jacket."},"mw":"件"},{"hz":"洋裝","ex":{"zh":"她今天穿了一件洋裝。","py":"tā jīn tiān chuān le yí jiàn yáng zhuāng","id":"Hari ini dia memakai gaun.","en":"She is wearing a dress today."},"mw":"件"},{"hz":"制服","ex":{"zh":"學生都要穿制服。","py":"xué shēng dōu yào chuān zhì fú","id":"Semua siswa harus memakai seragam.","en":"All students must wear uniforms."},"mw":"套"},{"hz":"長袖","ex":{"zh":"冬天我常穿長袖。","py":"dōng tiān wǒ cháng chuān cháng xiù","id":"Waktu musim dingin aku sering memakai baju lengan panjang.","en":"In winter I often wear long sleeves."}},{"hz":"短袖","ex":{"zh":"夏天我都穿短袖。","py":"xià tiān wǒ dōu chuān duǎn xiù","id":"Waktu musim panas aku selalu memakai baju lengan pendek.","en":"In summer I always wear short sleeves."}},{"hz":"長褲","ex":{"zh":"他穿著一條黑色長褲。","py":"tā chuān zhe yì tiáo hēi sè cháng kù","id":"Dia memakai celana panjang hitam.","en":"He is wearing black trousers."},"mw":"條"},{"hz":"短褲","ex":{"zh":"天氣很熱，我穿短褲。","py":"tiān qì hěn rè wǒ chuān duǎn kù","id":"Cuacanya panas, aku pakai celana pendek.","en":"It's hot, so I'm wearing shorts."},"mw":"條"},{"hz":"裙子","ex":{"zh":"這條裙子很漂亮。","py":"zhè tiáo qún zi hěn piào liang","id":"Rok ini cantik sekali.","en":"This skirt is very pretty."},"mw":"條"},{"hz":"褲子","ex":{"zh":"這條褲子太長了。","py":"zhè tiáo kù zi tài cháng le","id":"Celana ini terlalu panjang.","en":"These pants are too long."},"mw":"條"}]},{"title":{"id":"Sepatu","en":"Shoes"},"words":[{"hz":"運動鞋","ex":{"zh":"我有一雙運動鞋。","py":"wǒ yǒu yì shuāng yùn dòng xié","id":"Aku punya sepasang sepatu olahraga.","en":"I have a pair of sports shoes."},"mw":"雙"},{"hz":"皮鞋","ex":{"zh":"爸爸穿皮鞋去上班。","py":"bà ba chuān pí xié qù shàng bān","id":"Ayah memakai sepatu kulit ke tempat kerja.","en":"Dad wears leather shoes to work."},"mw":"雙"},{"hz":"拖鞋","ex":{"zh":"在家我穿拖鞋。","py":"zài jiā wǒ chuān tuō xié","id":"Di rumah aku pakai sandal rumah.","en":"At home I wear slippers."},"mw":"雙"},{"hz":"涼鞋","ex":{"zh":"夏天我喜歡穿涼鞋。","py":"xià tiān wǒ xǐ huān chuān liáng xié","id":"Waktu musim panas aku suka memakai sandal.","en":"I like wearing sandals in summer."},"mw":"雙"},{"hz":"高跟鞋","ex":{"zh":"她穿高跟鞋很漂亮。","py":"tā chuān gāo gēn xié hěn piào liang","id":"Dia cantik memakai sepatu hak tinggi.","en":"She looks pretty in high heels."},"mw":"雙"},{"hz":"鞋子","ex":{"zh":"這雙鞋子很好穿。","py":"zhè shuāng xié zi hěn hǎo chuān","id":"Sepatu ini enak dipakai.","en":"These shoes are comfortable to wear."},"mw":"雙"},{"hz":"襪子","ex":{"zh":"我要買一雙襪子。","py":"wǒ yào mǎi yì shuāng wà zi","id":"Aku mau beli sepasang kaus kaki.","en":"I want to buy a pair of socks."},"mw":"雙"}]},{"title":{"id":"Aksesori","en":"Accessories"},"words":[{"hz":"手錶","ex":{"zh":"他戴著一隻手錶。","py":"tā dài zhe yì zhī shǒu biǎo","id":"Dia memakai sebuah jam tangan.","en":"He is wearing a watch."},"mw":"隻"},{"hz":"眼鏡","ex":{"zh":"我戴眼鏡看書。","py":"wǒ dài yǎn jìng kàn shū","id":"Aku memakai kacamata untuk membaca.","en":"I wear glasses to read."},"mw":"副"},{"hz":"太陽眼鏡","ex":{"zh":"外面太陽很大，戴太陽眼鏡吧。","py":"wài miàn tài yáng hěn dà dài tài yáng yǎn jìng ba","id":"Di luar matahari terik, pakai kacamata hitam saja.","en":"The sun is strong outside, put on sunglasses."},"mw":"副"},{"hz":"項鍊","ex":{"zh":"這條項鍊多少錢？","py":"zhè tiáo xiàng liàn duō shǎo qián","id":"Kalung ini harganya berapa?","en":"How much is this necklace?"},"mw":"條"},{"hz":"耳環","ex":{"zh":"她戴著一對耳環。","py":"tā dài zhe yí duì ěr huán","id":"Dia memakai sepasang anting.","en":"She is wearing a pair of earrings."},"mw":"對"},{"hz":"手套","ex":{"zh":"冬天要戴手套。","py":"dōng tiān yào dài shǒu tào","id":"Waktu musim dingin harus pakai sarung tangan.","en":"You need gloves in winter."},"mw":"雙"},{"hz":"背包","ex":{"zh":"我的背包很重。","py":"wǒ de bēi bāo hěn zhòng","id":"Ranselku berat sekali.","en":"My backpack is very heavy."},"mw":"個"},{"hz":"錢包","ex":{"zh":"我的錢包不見了。","py":"wǒ de qián bāo bú jiàn le","id":"Dompetku hilang.","en":"My wallet is missing."},"mw":"個"},{"hz":"帽子","ex":{"zh":"他戴著一頂帽子。","py":"tā dài zhe yì dǐng mào zi","id":"Dia memakai sebuah topi.","en":"He is wearing a hat."},"mw":"頂"}]},{"title":{"id":"Warna","en":"Colors"},"words":[{"hz":"紅色","ex":{"zh":"我喜歡紅色。","py":"wǒ xǐ huān hóng sè","id":"Aku suka warna merah.","en":"I like red."}},{"hz":"黃色","ex":{"zh":"計程車是黃色的。","py":"jì chéng chē shì huáng sè de","id":"Taksi berwarna kuning.","en":"Taxis are yellow."}},{"hz":"藍色","ex":{"zh":"天空是藍色的。","py":"tiān kōng shì lán sè de","id":"Langit berwarna biru.","en":"The sky is blue."}},{"hz":"綠色","ex":{"zh":"他有一件綠色外套。","py":"tā yǒu yí jiàn lǜ sè wài tào","id":"Dia punya jaket hijau.","en":"He has a green jacket."}},{"hz":"黑色","ex":{"zh":"我想買黑色的鞋。","py":"wǒ xiǎng mǎi hēi sè de xié","id":"Aku mau beli sepatu hitam.","en":"I want to buy black shoes."}},{"hz":"白色","ex":{"zh":"她穿白色的裙子。","py":"tā chuān bái sè de qún zi","id":"Dia memakai rok putih.","en":"She is wearing a white skirt."}},{"hz":"紫色","ex":{"zh":"紫色的帽子很特別。","py":"zǐ sè de mào zi hěn tè bié","id":"Topi ungu itu unik.","en":"The purple hat is very special."}},{"hz":"咖啡色","ex":{"zh":"我的包包是咖啡色的。","py":"wǒ de bāo bāo shì kā fēi sè de","id":"Tasku berwarna cokelat.","en":"My bag is brown."}}]},{"title":{"id":"Memakai dan mencoba","en":"Wearing and trying on"},"words":[{"hz":"穿","ex":{"zh":"你今天穿得很好看。","py":"nǐ jīn tiān chuān de hěn hǎo kàn","id":"Hari ini kamu berpakaian bagus.","en":"You look great today."}},{"hz":"戴","ex":{"zh":"出門要戴口罩。","py":"chū mén yào dài kǒu zhào","id":"Kalau keluar rumah harus pakai masker.","en":"You need to wear a mask when going out."}},{"hz":"脫","ex":{"zh":"進門請脫鞋。","py":"jìn mén qǐng tuō xié","id":"Silakan lepas sepatu saat masuk.","en":"Please take off your shoes when you come in."}},{"hz":"試穿","ex":{"zh":"我可以試穿嗎？","py":"wǒ kě yǐ shì chuān ma","id":"Boleh aku coba pakai?","en":"May I try it on?"}},{"hz":"換衣服","ex":{"zh":"我要先換衣服。","py":"wǒ yào xiān huàn yī fu","id":"Aku mau ganti baju dulu.","en":"I want to change clothes first."}},{"hz":"合適","ex":{"zh":"這件衣服很合適。","py":"zhè jiàn yī fu hěn hé shì","id":"Baju ini cocok sekali.","en":"This one fits well."}},{"hz":"顏色","ex":{"zh":"這個顏色我很喜歡。","py":"zhè ge yán sè wǒ hěn xǐ huān","id":"Aku suka warna ini.","en":"I really like this color."},"mw":"種"}]}],"grammar":[{"title":{"id":"穿 dan 戴: dua kata untuk 'memakai'","en":"穿 vs 戴"},"pattern":"穿 + 衣服/褲子/鞋 / 戴 + 帽子/眼鏡/手錶","note":{"id":"Bahasa Indonesia hanya punya 'memakai', tetapi bahasa Mandarin membedakan: 穿 untuk baju, celana, rok, sepatu, kaus kaki; 戴 untuk topi, kacamata, jam tangan, masker, kalung, anting, sarung tangan. Kesalahan umum: 穿帽子 atau 戴衣服.","en":"Indonesian uses one word, 'memakai', but Mandarin splits it: 穿 for clothes, trousers, skirts, shoes and socks; 戴 for hats, glasses, watches, masks, gloves and jewelry. Common mistakes: 穿帽子 or 戴衣服."},"ex":[{"zh":"我穿外套，也戴帽子。","py":"wǒ chuān wài tào yě dài mào zi","id":"Aku memakai jaket dan juga topi.","en":"I wear a jacket and also a hat."},{"zh":"他穿運動鞋，戴手錶。","py":"tā chuān yùn dòng xié dài shǒu biǎo","id":"Dia memakai sepatu olahraga dan jam tangan.","en":"He wears sports shoes and a watch."},{"zh":"你要戴口罩。","py":"nǐ yào dài kǒu zhào","id":"Kamu harus memakai masker.","en":"You need to wear a mask."}]},{"title":{"id":"Kata satuan pakaian: 件, 條, 雙","en":"Measure words for clothes"},"pattern":"Num + 件/條/雙 + N","note":{"id":"Pakaian atas dan jaket pakai 件, celana, rok, dan kalung pakai 條, benda berpasangan seperti sepatu dan kaus kaki pakai 雙. Jangan memakai 個 untuk semuanya. Untuk menanyakan 'yang ini' pakai 這件, 這條, 這雙.","en":"Use 件 for tops and jackets, 條 for pants, skirts and necklaces, and 雙 for paired items like shoes and socks. Do not use 個 for everything."},"ex":[{"zh":"我想買一件外套。","py":"wǒ xiǎng mǎi yí jiàn wài tào","id":"Aku mau membeli sebuah jaket.","en":"I want to buy a jacket."},{"zh":"這雙鞋多少錢？","py":"zhè shuāng xié duō shǎo qián","id":"Sepatu ini harganya berapa?","en":"How much are these shoes?"},{"zh":"她有三條長褲。","py":"tā yǒu sān tiáo cháng kù","id":"Dia punya tiga celana panjang.","en":"She has three pairs of long pants."}]},{"title":{"id":"Menyebut warna: 顏色 + 的 + benda","en":"Color + 的 + noun"},"pattern":"顏色 + 的 + N / 這件是 + 顏色 + 的","note":{"id":"Warna ditaruh sebelum benda dan biasanya diberi 的: 黑色的鞋 (sepatu hitam). Kalau bendanya sudah jelas, boleh dihilangkan: 我要黑色的 (aku mau yang hitam). Kata benda tidak ditaruh sebelum warna seperti di bahasa Indonesia.","en":"Put the color before the noun, usually with 的: 黑色的鞋. If the noun is obvious you can drop it: 我要黑色的 'I want the black one'."},"ex":[{"zh":"我要黑色的。","py":"wǒ yào hēi sè de","id":"Aku mau yang hitam.","en":"I want the black one."},{"zh":"這件是藍色的。","py":"zhè jiàn shì lán sè de","id":"Yang ini berwarna biru.","en":"This one is blue."},{"zh":"她有一雙白色的鞋。","py":"tā yǒu yì shuāng bái sè de xié","id":"Dia punya sepasang sepatu putih.","en":"She has a pair of white shoes."}]},{"title":{"id":"Terlalu…: 太 + sifat + 了","en":"Too…: 太 + Adj + 了"},"pattern":"太 + Adj + 了","note":{"id":"太…了 berarti 'terlalu…' atau 'sangat…'. Saat belanja, ini dipakai untuk bilang ukuran tidak pas atau harga mahal. Jangan lupa 了 di akhir. Untuk 'agak besar' pakai 有一點大.","en":"太…了 means 'too…' (or 'so…'). It is useful for sizes and prices when shopping. Keep the 了 at the end. For 'a bit big' say 有一點大."},"ex":[{"zh":"這雙鞋太貴了。","py":"zhè shuāng xié tài guì le","id":"Sepatu ini terlalu mahal.","en":"These shoes are too expensive."},{"zh":"這件衣服太短了。","py":"zhè jiàn yī fu tài duǎn le","id":"Baju ini terlalu pendek.","en":"This top is too short."}]}],"dialog":[{"zh":"您好，請問您要找什麼？","py":"nín hǎo qǐng wèn nín yào zhǎo shén me","id":"Halo, sedang cari apa?","en":"Hello, what are you looking for?","sp":"A"},{"zh":"我想買一件外套。","py":"wǒ xiǎng mǎi yí jiàn wài tào","id":"Saya mau beli sebuah jaket.","en":"I want to buy a jacket.","sp":"B"},{"zh":"這件黑色的怎麼樣？","py":"zhè jiàn hēi sè de zěn me yàng","id":"Yang hitam ini bagaimana?","en":"How about this black one?","sp":"A"},{"zh":"我可以試穿嗎？","py":"wǒ kě yǐ shì chuān ma","id":"Boleh saya coba?","en":"Can I try it on?","sp":"B"},{"zh":"可以，試衣間在那裡。","py":"kě yǐ shì yī jiān zài nà lǐ","id":"Boleh, ruang ganti ada di sana.","en":"Sure, the fitting room is over there.","sp":"A"},{"zh":"這件有一點大，有小一點的嗎？","py":"zhè jiàn yǒu yì diǎn dà yǒu xiǎo yì diǎn de ma","id":"Ini agak besar, ada yang lebih kecil?","en":"This one is a bit big. Do you have a smaller one?","sp":"B"},{"zh":"有，這是小號的。","py":"yǒu zhè shì xiǎo hào de","id":"Ada, ini ukuran kecil.","en":"Yes, this is a small.","sp":"A"},{"zh":"這件很合適，我要買。","py":"zhè jiàn hěn hé shì wǒ yào mǎi","id":"Yang ini pas sekali, saya beli.","en":"This one fits well. I'll buy it.","sp":"B"}],"n":"06"},{"k":"kota","zh":"城市地點","py":"chéng shì dì diǎn","title":{"id":"Tempat di kota","en":"Places in town","tl":"Mga lugar sa lungsod","vi":"Địa điểm trong thành phố"},"desc":{"id":"Kamu bisa menyebut tempat-tempat di kota dan bilang di mana letaknya.","en":"You can name places in town and say where they are."},"icon":"city","sets":[{"title":{"id":"Toko dan pasar","en":"Shops and markets"},"words":[{"hz":"商店","ex":{"zh":"這家商店賣很多東西。","py":"zhè jiā shāng diàn mài hěn duō dōng xi","id":"Toko ini menjual banyak barang.","en":"This store sells many things."},"mw":"家"},{"hz":"書店","ex":{"zh":"我常去書店看書。","py":"wǒ cháng qù shū diàn kàn shū","id":"Aku sering ke toko buku untuk membaca.","en":"I often go to the bookstore to read."},"mw":"家"},{"hz":"麵包店","ex":{"zh":"麵包店的蛋糕很好吃。","py":"miàn bāo diàn de dàn gāo hěn hǎo chī","id":"Kue di toko roti itu enak sekali.","en":"The cakes at the bakery are delicious."},"mw":"家"},{"hz":"超級市場","ex":{"zh":"超級市場在車站旁邊。","py":"chāo jí shì chǎng zài chē zhàn páng biān","id":"Supermarket ada di samping stasiun.","en":"The supermarket is next to the station."},"mw":"家"},{"hz":"菜市場","ex":{"zh":"媽媽早上去菜市場買菜。","py":"mā ma zǎo shàng qù cài shì chǎng mǎi cài","id":"Ibu pergi ke pasar tradisional pagi hari untuk belanja sayur.","en":"Mom goes to the traditional market in the morning to buy groceries."},"mw":"個"},{"hz":"夜市","ex":{"zh":"晚上我們去夜市吃小吃。","py":"wǎn shàng wǒ men qù yè shì chī xiǎo chī","id":"Malam ini kami ke pasar malam untuk jajan.","en":"Tonight we are going to the night market for snacks."},"mw":"個"},{"hz":"百貨公司","ex":{"zh":"百貨公司的人很多。","py":"bǎi huò gōng sī de rén hěn duō","id":"Di mal banyak orang.","en":"There are a lot of people at the department store."},"mw":"家"},{"hz":"藥局","ex":{"zh":"藥局在醫院對面。","py":"yào jú zài yī yuàn duì miàn","id":"Apotek ada di seberang rumah sakit.","en":"The pharmacy is across from the hospital."},"mw":"家"},{"hz":"花店","ex":{"zh":"我想去花店買花。","py":"wǒ xiǎng qù huā diàn mǎi huā","id":"Aku mau ke toko bunga untuk beli bunga.","en":"I want to go to the flower shop to buy flowers."},"mw":"家"}]},{"title":{"id":"Tempat umum","en":"Public places"},"words":[{"hz":"學校","ex":{"zh":"我的學校離車站很近。","py":"wǒ de xué xiào lí chē zhàn hěn jìn","id":"Sekolahku dekat dengan stasiun.","en":"My school is very close to the station."},"mw":"所"},{"hz":"醫院","ex":{"zh":"他生病了，要去醫院。","py":"tā shēng bìng le yào qù yī yuàn","id":"Dia sakit, jadi harus pergi ke rumah sakit.","en":"He is sick and needs to go to the hospital."},"mw":"家"},{"hz":"郵局","ex":{"zh":"我要去郵局寄信。","py":"wǒ yào qù yóu jú jì xìn","id":"Aku mau ke kantor pos untuk mengirim surat.","en":"I am going to the post office to mail a letter."},"mw":"間"},{"hz":"銀行","ex":{"zh":"銀行幾點開門？","py":"yín háng jǐ diǎn kāi mén","id":"Bank buka jam berapa?","en":"What time does the bank open?"},"mw":"家"},{"hz":"圖書館","ex":{"zh":"我們在圖書館看書。","py":"wǒ men zài tú shū guǎn kàn shū","id":"Kami membaca buku di perpustakaan.","en":"We read books in the library."},"mw":"間"},{"hz":"公園","ex":{"zh":"週末我常去公園散步。","py":"zhōu mò wǒ cháng qù gōng yuán sàn bù","id":"Akhir pekan aku sering jalan-jalan di taman.","en":"On weekends I often walk in the park."},"mw":"座"},{"hz":"警察局","ex":{"zh":"警察局就在前面。","py":"jǐng chá jú jiù zài qián miàn","id":"Kantor polisi ada tepat di depan.","en":"The police station is right ahead."},"mw":"間"},{"hz":"電影院","ex":{"zh":"我們在電影院看電影。","py":"wǒ men zài diàn yǐng yuàn kàn diàn yǐng","id":"Kami menonton film di bioskop.","en":"We watch a movie at the cinema."},"mw":"家"}]},{"title":{"id":"Makan, menginap, bekerja","en":"Eating, staying, working"},"words":[{"hz":"餐廳","ex":{"zh":"這家餐廳的牛肉麵很好吃。","py":"zhè jiā cān tīng de niú ròu miàn hěn hǎo chī","id":"Mi daging sapi di restoran ini enak sekali.","en":"The beef noodles at this restaurant are delicious."},"mw":"家"},{"hz":"咖啡廳","ex":{"zh":"我在咖啡廳等朋友。","py":"wǒ zài kā fēi tīng děng péng yǒu","id":"Aku menunggu teman di kafe.","en":"I am waiting for a friend at the cafe."},"mw":"家"},{"hz":"飯店","ex":{"zh":"我們住在台北的一家飯店。","py":"wǒ men zhù zài tái běi de yì jiā fàn diàn","id":"Kami menginap di hotel di Taipei.","en":"We are staying at a hotel in Taipei."},"mw":"家"},{"hz":"公司","ex":{"zh":"我的公司在這棟大樓裡。","py":"wǒ de gōng sī zài zhè dòng dà lóu lǐ","id":"Kantorku ada di gedung ini.","en":"My company is in this building."},"mw":"家"},{"hz":"大樓","ex":{"zh":"這棟大樓有二十層。","py":"zhè dòng dà lóu yǒu èr shí céng","id":"Gedung ini punya dua puluh lantai.","en":"This building has twenty floors."},"mw":"棟"},{"hz":"洗手間","ex":{"zh":"請問洗手間在哪裡？","py":"qǐng wèn xǐ shǒu jiān zài nǎ lǐ","id":"Permisi, toilet ada di mana?","en":"Excuse me, where is the restroom?"},"mw":"間"}]},{"title":{"id":"Kata letak","en":"Location words"},"words":[{"hz":"對面","ex":{"zh":"郵局在學校對面。","py":"yóu jú zài xué xiào duì miàn","id":"Kantor pos ada di seberang sekolah.","en":"The post office is across from the school."}},{"hz":"附近","ex":{"zh":"這附近有便利商店嗎？","py":"zhè fù jìn yǒu biàn lì shāng diàn ma","id":"Di dekat sini ada minimarket?","en":"Is there a convenience store nearby?"}},{"hz":"裡面","ex":{"zh":"書店裡面有咖啡廳。","py":"shū diàn lǐ miàn yǒu kā fēi tīng","id":"Di dalam toko buku ada kafe.","en":"There is a cafe inside the bookstore."}},{"hz":"外頭","ex":{"zh":"外頭在下雨。","py":"wài tou zài xià yǔ","id":"Di luar sedang hujan.","en":"It is raining outside."}},{"hz":"樓上","ex":{"zh":"洗手間在樓上。","py":"xǐ shǒu jiān zài lóu shàng","id":"Toilet ada di lantai atas.","en":"The restroom is upstairs."}},{"hz":"樓下","ex":{"zh":"樓下有一家麵店。","py":"lóu xià yǒu yì jiā miàn diàn","id":"Di lantai bawah ada kedai mi.","en":"There is a noodle shop downstairs."}},{"hz":"中間","ex":{"zh":"銀行在郵局和書店中間。","py":"yín háng zài yóu jú hé shū diàn zhōng jiān","id":"Bank ada di antara kantor pos dan toko buku.","en":"The bank is between the post office and the bookstore."}},{"hz":"北邊","ex":{"zh":"公園在學校的北邊。","py":"gōng yuán zài xué xiào de běi biān","id":"Taman ada di sebelah utara sekolah.","en":"The park is north of the school."}}]},{"title":{"id":"Posisi & letak","en":"Position and location"},"words":[{"hz":"上面","ex":{"zh":"書在桌子上面。","py":"shū zài zhuō zi shàng miàn","id":"Bukunya ada di atas meja.","en":"The book is on top of the table."}},{"hz":"下面","ex":{"zh":"貓在椅子下面。","py":"māo zài yǐ zi xià miàn","id":"Kucing ada di bawah kursi.","en":"The cat is under the chair."}},{"hz":"外面","ex":{"zh":"外面很冷，多穿一點。","py":"wài miàn hěn lěng duō chuān yì diǎn","id":"Di luar dingin, pakai baju yang lebih tebal.","en":"It's cold outside, so wear more layers."}},{"hz":"前面","ex":{"zh":"前面有一家便利商店。","py":"qián miàn yǒu yì jiā biàn lì shāng diàn","id":"Di depan ada minimarket.","en":"There is a convenience store ahead."}},{"hz":"後面","ex":{"zh":"學校後面有一個公園。","py":"xué xiào hòu miàn yǒu yí ge gōng yuán","id":"Di belakang sekolah ada taman.","en":"There is a park behind the school."}},{"hz":"左邊","ex":{"zh":"洗手間在左邊。","py":"xǐ shǒu jiān zài zuǒ biān","id":"Toilet ada di sebelah kiri.","en":"The restroom is on the left."}},{"hz":"右邊","ex":{"zh":"銀行在郵局右邊。","py":"yín háng zài yóu jú yòu biān","id":"Bank ada di sebelah kanan kantor pos.","en":"The bank is to the right of the post office."}},{"hz":"旁邊","ex":{"zh":"我家旁邊有夜市。","py":"wǒ jiā páng biān yǒu yè shì","id":"Di samping rumahku ada pasar malam.","en":"There is a night market next to my home."}}]}],"grammar":[{"title":{"id":"Menyatakan lokasi: 在 + tempat","en":"Saying where something is"},"pattern":"N + 在 + tempat / kata letak","note":{"id":"在 berarti 'berada di'. Benda atau orang di depan 在, tempatnya di belakang. Untuk menunjukkan letak lebih tepat, tambahkan kata seperti 對面, 裡面 atau 樓上. 在 + tempat juga bisa diletakkan sebelum kata kerja: 他在銀行工作. Jangan menaruh tempat di depan benda.","en":"在 means 'to be at'. The thing or person comes first and the place follows 在. Add words like 對面, 裡面 or 樓上 to be more exact. 在 + place can also come before a verb: 他在銀行工作."},"ex":[{"zh":"銀行在郵局對面。","py":"yín háng zài yóu jú duì miàn","id":"Bank ada di seberang kantor pos.","en":"The bank is across from the post office."},{"zh":"他在銀行工作。","py":"tā zài yín háng gōng zuò","id":"Dia bekerja di bank.","en":"He works at a bank."},{"zh":"咖啡廳在書店裡面。","py":"kā fēi tīng zài shū diàn lǐ miàn","id":"Kafenya ada di dalam toko buku.","en":"The cafe is inside the bookstore."}]},{"title":{"id":"Menyatakan keberadaan: tempat + 有 + benda","en":"Saying what is somewhere"},"pattern":"tempat + 有 + (數量) + N","note":{"id":"Untuk bilang 'di tempat X ada Y', tempat ditaruh di depan 有. Ini beda dengan 在: 在 menunjukkan letak sesuatu yang sudah diketahui, 有 memperkenalkan sesuatu yang baru. Jangan pakai 是 untuk 'ada'.","en":"Put the place first, then 有, then the thing. Use 在 for where a known thing is, and 有 to say what exists in a place."},"ex":[{"zh":"這附近有一家書店。","py":"zhè fù jìn yǒu yì jiā shū diàn","id":"Di dekat sini ada sebuah toko buku.","en":"There is a bookstore nearby."},{"zh":"公園裡面有很多人。","py":"gōng yuán lǐ miàn yǒu hěn duō rén","id":"Di dalam taman ada banyak orang.","en":"There are many people in the park."},{"zh":"樓下有咖啡廳。","py":"lóu xià yǒu kā fēi tīng","id":"Di lantai bawah ada kafe.","en":"There is a cafe downstairs."}]},{"title":{"id":"Jarak: A 離 B 近 / 遠","en":"Distance between places"},"pattern":"A + 離 + B + 很近 / 不遠","note":{"id":"離 berarti 'berjarak dari'. Tempat yang dibicarakan ada di depan 離, titik acuan di belakangnya. Setelahnya pakai sifat 近 atau 遠, biasanya dengan 很 atau 不. Jangan pakai 從 di sini; 從 itu untuk 'dari' sebagai titik awal gerakan.","en":"離 means 'away from'. Use it with 近 or 遠, usually with 很 or 不. Do not use 從 for distance; 從 marks a starting point of movement."},"ex":[{"zh":"學校離我家很近。","py":"xué xiào lí wǒ jiā hěn jìn","id":"Sekolah dekat dengan rumahku.","en":"The school is close to my home."},{"zh":"夜市離這裡不遠。","py":"yè shì lí zhè lǐ bù yuǎn","id":"Pasar malam tidak jauh dari sini.","en":"The night market is not far from here."}]},{"title":{"id":"Pergi ke tempat untuk melakukan sesuatu","en":"Going somewhere to do something"},"pattern":"去 + tempat + V","note":{"id":"Setelah 去 dan tempat, langsung sebut kegiatannya tanpa kata penghubung seperti untuk. Jangan tambah 到 setelah 去. Urutannya selalu: pergi, tempat, kegiatan.","en":"After 去 and the place, add the activity directly. No word for 'to' or 'in order to' is needed."},"ex":[{"zh":"我們去圖書館看書。","py":"wǒ men qù tú shū guǎn kàn shū","id":"Kami pergi ke perpustakaan untuk membaca.","en":"We go to the library to read."},{"zh":"星期天她去百貨公司逛街。","py":"xīng qí tiān tā qù bǎi huò gōng sī guàng jiē","id":"Hari Minggu dia pergi jalan-jalan ke mal.","en":"On Sunday she goes shopping at the department store."}]}],"dialog":[{"sp":"A","zh":"請問，這附近有銀行嗎？","py":"qǐng wèn zhè fù jìn yǒu yín háng ma","id":"Permisi, di dekat sini ada bank?","en":"Excuse me, is there a bank nearby?"},{"sp":"B","zh":"有，銀行在郵局對面。","py":"yǒu yín háng zài yóu jú duì miàn","id":"Ada, bank ada di seberang kantor pos.","en":"Yes, the bank is across from the post office."},{"sp":"A","zh":"離這裡遠不遠？","py":"lí zhè lǐ yuǎn bu yuǎn","id":"Jauh nggak dari sini?","en":"Is it far from here?"},{"sp":"B","zh":"不遠，走路五分鐘就到了。","py":"bù yuǎn zǒu lù wǔ fēn zhōng jiù dào le","id":"Nggak jauh, jalan kaki lima menit sudah sampai.","en":"Not far. It is a five minute walk."},{"sp":"A","zh":"郵局旁邊是什麼店？","py":"yóu jú páng biān shì shén me diàn","id":"Di sebelah kantor pos itu toko apa?","en":"What shop is next to the post office?"},{"sp":"B","zh":"是一家書店，樓上有咖啡廳。","py":"shì yì jiā shū diàn lóu shàng yǒu kā fēi tīng","id":"Toko buku, di lantai atasnya ada kafe.","en":"A bookstore, and there is a cafe upstairs."},{"sp":"A","zh":"謝謝你！","py":"xiè xie nǐ","id":"Terima kasih ya!","en":"Thank you!"}],"n":"07"},{"k":"transport","zh":"交通方向","py":"jiāo tōng fāng xiàng","title":{"id":"Transportasi dan arah","en":"Transport and directions","tl":"Transportasyon at direksyon","vi":"Giao thông và chỉ đường"},"desc":{"id":"Kamu bisa menyebut kendaraan, naik transportasi umum, dan bertanya atau memberi arah jalan.","en":"You can name vehicles, ride public transport, and ask for or give directions."},"icon":"bus","sets":[{"title":{"id":"Kendaraan","en":"Vehicles"},"words":[{"hz":"捷運","ex":{"zh":"我每天搭捷運上班。","py":"wǒ měi tiān dā jié yùn shàng bān","id":"Setiap hari aku naik MRT ke kantor.","en":"I take the MRT to work every day."}},{"hz":"火車","ex":{"zh":"這班火車去高雄。","py":"zhè bān huǒ chē qù gāo xióng","id":"Kereta ini menuju Kaohsiung.","en":"This train goes to Kaohsiung."},"mw":"班"},{"hz":"高鐵","ex":{"zh":"坐高鐵去台中很快。","py":"zuò gāo tiě qù tái zhōng hěn kuài","id":"Naik kereta cepat (HSR) ke Taichung tidak makan waktu lama.","en":"Taking the high-speed rail to Taichung is fast."},"mw":"班"},{"hz":"計程車","ex":{"zh":"下雨了，我們坐計程車吧。","py":"xià yǔ le wǒ men zuò jì chéng chē ba","id":"Hujan nih, kita naik taksi saja.","en":"It's raining, so let's take a taxi."},"mw":"輛"},{"hz":"腳踏車","ex":{"zh":"他每天騎腳踏車去學校。","py":"tā měi tiān qí jiǎo tà chē qù xué xiào","id":"Dia setiap hari naik sepeda ke sekolah.","en":"He rides a bicycle to school every day."},"mw":"輛"},{"hz":"摩托車","ex":{"zh":"台灣有很多摩托車。","py":"tái wān yǒu hěn duō mó tuō chē","id":"Di Taiwan ada banyak sepeda motor.","en":"There are many motorcycles in Taiwan."},"mw":"輛"},{"hz":"飛機","ex":{"zh":"坐飛機一個小時就到了。","py":"zuò fēi jī yí ge xiǎo shí jiù dào le","id":"Naik pesawat satu jam sudah sampai.","en":"By plane it takes just one hour."},"mw":"架"},{"hz":"巴士","ex":{"zh":"這輛巴士去機場。","py":"zhè liàng bā shì qù jī chǎng","id":"Bus ini menuju bandara.","en":"This bus goes to the airport."},"mw":"輛"},{"hz":"車子","ex":{"zh":"我家有一輛車子。","py":"wǒ jiā yǒu yí liàng chē zi","id":"Keluargaku punya sebuah mobil.","en":"My family has a car."},"mw":"輛"}]},{"title":{"id":"Stasiun dan tiket","en":"Stations and tickets"},"words":[{"hz":"捷運站","ex":{"zh":"捷運站就在前面。","py":"jié yùn zhàn jiù zài qián miàn","id":"Stasiun MRT ada tepat di depan.","en":"The MRT station is right ahead."},"mw":"個"},{"hz":"公車站","ex":{"zh":"公車站在銀行旁邊。","py":"gōng chē zhàn zài yín háng páng biān","id":"Halte bus ada di samping bank.","en":"The bus stop is next to the bank."},"mw":"個"},{"hz":"火車站","ex":{"zh":"火車站的人很多。","py":"huǒ chē zhàn de rén hěn duō","id":"Di stasiun kereta banyak orang.","en":"There are many people at the train station."},"mw":"個"},{"hz":"飛機場","ex":{"zh":"從台北到飛機場要一個小時。","py":"cóng tái běi dào fēi jī chǎng yào yí ge xiǎo shí","id":"Dari Taipei ke bandara butuh satu jam.","en":"From Taipei to the airport takes one hour."},"mw":"座"},{"hz":"悠遊卡","ex":{"zh":"坐捷運可以用悠遊卡。","py":"zuò jié yùn kě yǐ yòng yōu yóu kǎ","id":"Naik MRT bisa pakai kartu EasyCard.","en":"You can use an EasyCard on the MRT."},"mw":"張"},{"hz":"票","ex":{"zh":"我買了兩張票。","py":"wǒ mǎi le liǎng zhāng piào","id":"Aku sudah membeli dua tiket.","en":"I bought two tickets."},"mw":"張"},{"hz":"月台","ex":{"zh":"火車在三號月台。","py":"huǒ chē zài sān hào yuè tái","id":"Kereta ada di peron nomor tiga.","en":"The train is at platform three."},"mw":"個"},{"hz":"出口","ex":{"zh":"請從二號出口出去。","py":"qǐng cóng èr hào chū kǒu chū qù","id":"Silakan keluar lewat pintu keluar nomor dua.","en":"Please go out through exit number two."},"mw":"個"},{"hz":"站牌","ex":{"zh":"站牌上有公車的號碼。","py":"zhàn pái shàng yǒu gōng chē de hào mǎ","id":"Di papan halte ada nomor bus.","en":"The bus stop sign shows the bus numbers."},"mw":"個"},{"hz":"票價","ex":{"zh":"捷運的票價不貴。","py":"jié yùn de piào jià bú guì","id":"Harga tiket MRT tidak mahal.","en":"The MRT fare is not expensive."}}]},{"title":{"id":"Naik, turun, menuju","en":"Getting around"},"words":[{"hz":"搭","ex":{"zh":"你要搭幾號公車？","py":"nǐ yào dā jǐ hào gōng chē","id":"Kamu mau naik bus nomor berapa?","en":"Which bus number will you take?"}},{"hz":"坐","ex":{"zh":"我坐捷運去上班。","py":"wǒ zuò jié yùn qù shàng bān","id":"Aku naik MRT ke tempat kerja.","en":"I take the MRT to work."}},{"hz":"騎","ex":{"zh":"他騎機車去上班。","py":"tā qí jī chē qù shàng bān","id":"Dia naik motor ke kantor.","en":"He rides a scooter to work."}},{"hz":"開車","ex":{"zh":"爸爸開車去公司。","py":"bà ba kāi chē qù gōng sī","id":"Ayah menyetir mobil ke kantor.","en":"Dad drives to the office."}},{"hz":"上車","ex":{"zh":"上車請刷悠遊卡。","py":"shàng chē qǐng shuā yōu yóu kǎ","id":"Saat naik, silakan tap kartu EasyCard.","en":"Please tap your EasyCard when you get on."}},{"hz":"下車","ex":{"zh":"下一站我要下車。","py":"xià yí zhàn wǒ yào xià chē","id":"Di pemberhentian berikutnya aku turun.","en":"I will get off at the next stop."}},{"hz":"轉車","ex":{"zh":"我們在台北車站轉車。","py":"wǒ men zài tái běi chē zhàn zhuǎn chē","id":"Kita ganti kereta di Stasiun Taipei.","en":"We transfer at Taipei Main Station."}},{"hz":"走路","ex":{"zh":"從這裡走路要十分鐘。","py":"cóng zhè lǐ zǒu lù yào shí fēn zhōng","id":"Dari sini jalan kaki sepuluh menit.","en":"It's a ten-minute walk from here."}},{"hz":"停車","ex":{"zh":"這裡不能停車。","py":"zhè lǐ bù néng tíng chē","id":"Di sini tidak boleh parkir.","en":"You cannot park here."}},{"hz":"等","ex":{"zh":"我在站牌等公車。","py":"wǒ zài zhàn pái děng gōng chē","id":"Aku menunggu bus di halte.","en":"I am waiting for the bus at the bus stop."}}]},{"title":{"id":"Arah dan jarak","en":"Directions and distance"},"words":[{"hz":"左轉","ex":{"zh":"到了路口請左轉。","py":"dào le lù kǒu qǐng zuǒ zhuǎn","id":"Sampai di perempatan, silakan belok kiri.","en":"At the intersection, please turn left."}},{"hz":"右轉","ex":{"zh":"看到銀行就右轉。","py":"kàn dào yín háng jiù yòu zhuǎn","id":"Begitu lihat bank, belok kanan.","en":"Turn right when you see the bank."}},{"hz":"直走","ex":{"zh":"請直走，不要轉彎。","py":"qǐng zhí zǒu bú yào zhuǎn wān","id":"Silakan jalan lurus, jangan belok.","en":"Please go straight and do not turn."}},{"hz":"路口","ex":{"zh":"前面的路口有紅綠燈。","py":"qián miàn de lù kǒu yǒu hóng lǜ dēng","id":"Di perempatan depan ada lampu lalu lintas.","en":"There are traffic lights at the intersection ahead."},"mw":"個"},{"hz":"紅燈","ex":{"zh":"紅燈的時候要停。","py":"hóng dēng de shí hòu yào tíng","id":"Saat lampu merah, kita harus berhenti.","en":"You must stop at a red light."}},{"hz":"綠燈","ex":{"zh":"綠燈了，我們過馬路吧。","py":"lǜ dēng le wǒ men guò mǎ lù ba","id":"Sudah lampu hijau, ayo kita menyeberang.","en":"The light is green, so let's cross the road."}},{"hz":"近","ex":{"zh":"我家離捷運站很近。","py":"wǒ jiā lí jié yùn zhàn hěn jìn","id":"Rumahku dekat dengan stasiun MRT.","en":"My home is close to the MRT station."}},{"hz":"遠","ex":{"zh":"夜市離這裡不遠。","py":"yè shì lí zhè lǐ bù yuǎn","id":"Pasar malam tidak jauh dari sini.","en":"The night market is not far from here."}},{"hz":"方向","ex":{"zh":"你走錯方向了。","py":"nǐ zǒu cuò fāng xiàng le","id":"Kamu salah arah.","en":"You are going the wrong way."}},{"hz":"問路","ex":{"zh":"他在街上向人問路。","py":"tā zài jiē shàng xiàng rén wèn lù","id":"Dia bertanya arah kepada orang di jalan.","en":"He asks people for directions on the street."}}]}],"grammar":[{"title":{"id":"Naik kendaraan: 坐 / 搭 + kendaraan + 去 + tempat","en":"Taking transport"},"pattern":"坐 / 搭 + 交通工具 + 去 + 地點","note":{"id":"Untuk kendaraan umum atau mobil pakai 坐 atau 搭. Untuk motor dan sepeda pakai 騎, untuk menyetir mobil pakai 開車, dan untuk jalan kaki pakai 走路. Cara naiknya disebut sebelum 去, jangan ditaruh di akhir kalimat.","en":"Use 坐 or 搭 for buses, trains and taxis, 騎 for bikes and scooters, 開車 for driving. The way of travel comes before 去."},"ex":[{"zh":"我坐捷運去學校。","py":"wǒ zuò jié yùn qù xué xiào","id":"Aku naik MRT ke sekolah.","en":"I take the MRT to school."},{"zh":"我們搭高鐵去台中。","py":"wǒ men dā gāo tiě qù tái zhōng","id":"Kami naik kereta cepat ke Taichung.","en":"We take the high-speed rail to Taichung."},{"zh":"他騎腳踏車去公園。","py":"tā qí jiǎo tà chē qù gōng yuán","id":"Dia naik sepeda ke taman.","en":"He rides a bicycle to the park."}]},{"title":{"id":"Memberi arah: 在 + tempat + 左轉 / 右轉","en":"Giving directions"},"pattern":"在 / 到 + 路口 + 左轉 / 右轉","note":{"id":"Untuk memberi arah, sebut tempat dulu lalu arahnya: 在路口左轉. 直走 berarti terus lurus. Orang Indonesia sering lupa menyebut tempat belok, padahal di Taiwan biasanya disebut jelas, seperti 路口 atau 銀行.","en":"Say where to turn first and then the direction. 直走 means keep going straight."},"ex":[{"zh":"在前面的路口右轉。","py":"zài qián miàn de lù kǒu yòu zhuǎn","id":"Di perempatan depan, belok kanan.","en":"Turn right at the intersection ahead."},{"zh":"先直走，到銀行就左轉。","py":"xiān zhí zǒu dào yín háng jiù zuǒ zhuǎn","id":"Lurus dulu, sampai bank belok kiri.","en":"Go straight first, then turn left at the bank."}]},{"title":{"id":"Dari titik awal ke tujuan: 從…到…","en":"From … to …"},"pattern":"從 + 起點 + 到 + 終點 + (要 + 時間)","note":{"id":"從 menandai titik awal dan 到 menandai tujuan. Lama perjalanan memakai 要 dan ditaruh setelah tujuan. Jangan memakai 離 di sini; 離 hanya untuk jarak antara dua tempat.","en":"從 marks the start and 到 marks the end. Add 要 plus a time to say how long it takes."},"ex":[{"zh":"從台北到高雄坐高鐵很快。","py":"cóng tái běi dào gāo xióng zuò gāo tiě hěn kuài","id":"Dari Taipei ke Kaohsiung naik kereta cepat itu cepat.","en":"From Taipei to Kaohsiung the high-speed rail is fast."},{"zh":"從我家到學校走路要十分鐘。","py":"cóng wǒ jiā dào xué xiào zǒu lù yào shí fēn zhōng","id":"Dari rumahku ke sekolah jalan kaki sepuluh menit.","en":"It takes ten minutes to walk from my home to school."}]},{"title":{"id":"Bertanya lama perjalanan: 要多久","en":"Asking how long it takes"},"pattern":"去 + 地點 + 要 + 多久？","note":{"id":"Pakai 多久 untuk bertanya berapa lama. Jawabannya memakai 要 diikuti lama waktu, misalnya 要二十分鐘. Jangan tertukar: 多久 untuk lamanya waktu, 幾點 untuk jam berapa.","en":"Use 多久 to ask how long. Answer with 要 plus the length of time. Don't confuse 多久 (how long) with 幾點 (what time)."},"ex":[{"zh":"去夜市要多久？","py":"qù yè shì yào duō jiǔ","id":"Ke pasar malam butuh berapa lama?","en":"How long does it take to get to the night market?"},{"zh":"坐捷運要二十分鐘。","py":"zuò jié yùn yào èr shí fēn zhōng","id":"Naik MRT butuh dua puluh menit.","en":"It takes twenty minutes by MRT."}]}],"dialog":[{"sp":"A","zh":"請問，去台北車站怎麼走？","py":"qǐng wèn qù tái běi chē zhàn zěn me zǒu","id":"Permisi, ke Stasiun Taipei lewat mana ya?","en":"Excuse me, how do I get to Taipei Main Station?"},{"sp":"B","zh":"你可以搭捷運，捷運站就在前面。","py":"nǐ kě yǐ dā jié yùn jié yùn zhàn jiù zài qián miàn","id":"Kamu bisa naik MRT, stasiunnya tepat di depan.","en":"You can take the MRT. The station is right ahead."},{"sp":"A","zh":"走路要多久？","py":"zǒu lù yào duō jiǔ","id":"Jalan kaki butuh berapa lama?","en":"How long does it take on foot?"},{"sp":"B","zh":"五分鐘就到了，到路口右轉。","py":"wǔ fēn zhōng jiù dào le dào lù kǒu yòu zhuǎn","id":"Lima menit sudah sampai, di perempatan belok kanan.","en":"Five minutes. Turn right at the intersection."},{"sp":"A","zh":"捷運可以用悠遊卡嗎？","py":"jié yùn kě yǐ yòng yōu yóu kǎ ma","id":"Naik MRT bisa pakai kartu EasyCard?","en":"Can I use an EasyCard on the MRT?"},{"sp":"B","zh":"可以，出站的時候也要刷卡。","py":"kě yǐ chū zhàn de shí hòu yě yào shuā kǎ","id":"Bisa, waktu keluar stasiun juga harus tap kartu.","en":"Yes, and you tap it again when you exit the station."},{"sp":"A","zh":"好，謝謝你！","py":"hǎo xiè xie nǐ","id":"Oke, terima kasih ya!","en":"Okay, thank you!"}],"n":"08"},{"k":"waktu","zh":"時間日期","py":"shí jiān rì qí","title":{"id":"Waktu dan tanggal","en":"Time and dates","tl":"Oras at petsa","vi":"Thời gian và ngày tháng"},"desc":{"id":"Kamu bisa menyebut jam, hari, tanggal, dan urutan waktu dalam percakapan sehari-hari.","en":"You can talk about clock time, days, dates and the order of events in daily life."},"icon":"clock","sets":[{"title":{"id":"Jam dan durasi","en":"Clock time and duration"},"words":[{"hz":"點","ex":{"zh":"我早上七點起床。","py":"wǒ zǎo shàng qī diǎn qǐ chuáng","id":"Aku bangun jam tujuh pagi.","en":"I get up at seven in the morning."}},{"hz":"分","ex":{"zh":"現在三點十分。","py":"xiàn zài sān diǎn shí fēn","id":"Sekarang jam tiga lewat sepuluh menit.","en":"It is ten past three now."}},{"hz":"半","ex":{"zh":"我們六點半吃晚餐。","py":"wǒ men liù diǎn bàn chī wǎn cān","id":"Kami makan malam jam setengah tujuh.","en":"We eat dinner at half past six."}},{"hz":"小時","ex":{"zh":"我每天睡八個小時。","py":"wǒ měi tiān shuì bā ge xiǎo shí","id":"Aku tidur delapan jam setiap hari.","en":"I sleep eight hours every day."},"mw":"個"},{"hz":"分鐘","ex":{"zh":"走路到車站要十分鐘。","py":"zǒu lù dào chē zhàn yào shí fēn zhōng","id":"Jalan kaki ke stasiun butuh sepuluh menit.","en":"It takes ten minutes to walk to the station."}},{"hz":"幾點","ex":{"zh":"你明天幾點上課？","py":"nǐ míng tiān jǐ diǎn shàng kè","id":"Besok kamu kuliah jam berapa?","en":"What time is your class tomorrow?"}},{"hz":"現在","ex":{"zh":"現在幾點了？","py":"xiàn zài jǐ diǎn le","id":"Sekarang jam berapa?","en":"What time is it now?"}},{"hz":"時間","ex":{"zh":"我今天沒有時間。","py":"wǒ jīn tiān méi yǒu shí jiān","id":"Hari ini aku tidak ada waktu.","en":"I do not have time today."},"mw":"個"}]},{"title":{"id":"Bagian hari","en":"Parts of the day"},"words":[{"hz":"早上","ex":{"zh":"我早上喝咖啡。","py":"wǒ zǎo shàng hē kā fēi","id":"Aku minum kopi di pagi hari.","en":"I drink coffee in the morning."}},{"hz":"中午","ex":{"zh":"中午我們一起吃飯。","py":"zhōng wǔ wǒ men yì qǐ chī fàn","id":"Siang hari kita makan bersama.","en":"We eat together at noon."}},{"hz":"下午","ex":{"zh":"下午我要去銀行。","py":"xià wǔ wǒ yào qù yín háng","id":"Sore ini aku mau ke bank.","en":"I am going to the bank this afternoon."}},{"hz":"晚上","ex":{"zh":"晚上我常去夜市。","py":"wǎn shàng wǒ cháng qù yè shì","id":"Malam hari aku sering ke pasar malam.","en":"I often go to the night market in the evening."}},{"hz":"半夜","ex":{"zh":"他半夜才回家。","py":"tā bàn yè cái huí jiā","id":"Dia baru pulang tengah malam.","en":"He didn't get home until the middle of the night."}},{"hz":"今天","ex":{"zh":"今天天氣很好。","py":"jīn tiān tiān qì hěn hǎo","id":"Cuaca hari ini bagus.","en":"The weather is nice today."}},{"hz":"昨天","ex":{"zh":"昨天我去了圖書館。","py":"zuó tiān wǒ qù le tú shū guǎn","id":"Kemarin aku pergi ke perpustakaan.","en":"I went to the library yesterday."}},{"hz":"明天","ex":{"zh":"明天是我的生日。","py":"míng tiān shì wǒ de shēng rì","id":"Besok hari ulang tahunku.","en":"Tomorrow is my birthday."}}]},{"title":{"id":"Hari, tanggal, tahun","en":"Days, dates and years"},"words":[{"hz":"星期一","ex":{"zh":"星期一我要去上班。","py":"xīng qí yī wǒ yào qù shàng bān","id":"Hari Senin aku harus berangkat kerja.","en":"On Monday I have to go to work."}},{"hz":"星期天","ex":{"zh":"星期天我們去看電影。","py":"xīng qí tiān wǒ men qù kàn diàn yǐng","id":"Hari Minggu kami pergi menonton film.","en":"On Sunday we're going to see a movie."}},{"hz":"週末","ex":{"zh":"週末你有空嗎？","py":"zhōu mò nǐ yǒu kòng ma","id":"Akhir pekan kamu ada waktu luang?","en":"Are you free this weekend?"}},{"hz":"星期幾","ex":{"zh":"今天是星期幾？","py":"jīn tiān shì xīng qí jǐ","id":"Hari ini hari apa?","en":"What day of the week is it today?"}},{"hz":"號","ex":{"zh":"今天是十月十三號。","py":"jīn tiān shì shí yuè shí sān hào","id":"Hari ini tanggal tiga belas Oktober.","en":"Today is October 13th."}},{"hz":"月","ex":{"zh":"我的生日在三月。","py":"wǒ de shēng rì zài sān yuè","id":"Ulang tahunku di bulan Maret.","en":"My birthday is in March."}},{"hz":"今年","ex":{"zh":"今年我二十二歲。","py":"jīn nián wǒ èr shí èr suì","id":"Tahun ini aku berumur dua puluh dua tahun.","en":"I am twenty-two years old this year."}},{"hz":"去年","ex":{"zh":"去年我去過日本。","py":"qù nián wǒ qù guò rì běn","id":"Tahun lalu aku ke Jepang.","en":"I went to Japan last year."}},{"hz":"明年","ex":{"zh":"明年我想去日本。","py":"míng nián wǒ xiǎng qù rì běn","id":"Tahun depan aku ingin pergi ke Jepang.","en":"Next year I want to go to Japan."}},{"hz":"生日","ex":{"zh":"你的生日是幾月幾號？","py":"nǐ de shēng rì shì jǐ yuè jǐ hào","id":"Ulang tahunmu bulan dan tanggal berapa?","en":"What month and day is your birthday?"},"mw":"個"}]},{"title":{"id":"Urutan dan keseringan","en":"Order and frequency"},"words":[{"hz":"以前","ex":{"zh":"以前我住在高雄。","py":"yǐ qián wǒ zhù zài gāo xióng","id":"Dulu aku tinggal di Kaohsiung.","en":"I used to live in Kaohsiung."}},{"hz":"以後","ex":{"zh":"下課以後，我們去吃飯。","py":"xià kè yǐ hòu wǒ men qù chī fàn","id":"Setelah kelas selesai, kita pergi makan.","en":"After class, let's go eat."}},{"hz":"先","ex":{"zh":"我先回家，再去公園。","py":"wǒ xiān huí jiā zài qù gōng yuán","id":"Aku pulang dulu, baru pergi ke taman.","en":"I go home first, then go to the park."}},{"hz":"然後","ex":{"zh":"先吃飯，然後看電影。","py":"xiān chī fàn rán hòu kàn diàn yǐng","id":"Makan dulu, lalu nonton film.","en":"Eat first, then watch a movie."}},{"hz":"已經","ex":{"zh":"他已經下班了。","py":"tā yǐ jīng xià bān le","id":"Dia sudah pulang kerja.","en":"He has already finished work."}},{"hz":"馬上","ex":{"zh":"請等一下，我馬上到。","py":"qǐng děng yí xià wǒ mǎ shàng dào","id":"Tunggu sebentar, aku segera sampai.","en":"Please wait a moment, I will be there right away."}},{"hz":"常常","ex":{"zh":"我常常搭捷運。","py":"wǒ cháng cháng dā jié yùn","id":"Aku sering naik MRT.","en":"I often take the MRT."}},{"hz":"每天","ex":{"zh":"我每天早上跑步。","py":"wǒ měi tiān zǎo shàng pǎo bù","id":"Setiap pagi aku lari.","en":"I run every morning."}},{"hz":"什麼時候","ex":{"zh":"你什麼時候下班？","py":"nǐ shén me shí hòu xià bān","id":"Kamu pulang kerja kapan?","en":"When do you get off work?"}},{"hz":"剛剛","ex":{"zh":"他剛剛才出門。","py":"tā gāng gāng cái chū mén","id":"Dia baru saja keluar rumah.","en":"He just left home a moment ago."}}]}],"grammar":[{"title":{"id":"Urutan kata: waktu dulu, baru kegiatan","en":"Time words come before the verb"},"pattern":"Subjek + waktu + V  (atau waktu + Subjek + V)","note":{"id":"Kata waktu ditaruh sebelum kata kerja, dari yang besar ke yang kecil: hari, bagian hari, lalu jam. Jangan taruh waktu di akhir kalimat seperti di bahasa Indonesia ('aku pergi ke bank besok'). Kata waktu boleh juga di awal kalimat.","en":"Place time words before the verb, from big to small: day, part of day, hour. Do not put them at the end of the sentence."},"ex":[{"zh":"我明天下午三點去銀行。","py":"wǒ míng tiān xià wǔ sān diǎn qù yín háng","id":"Besok jam tiga sore aku pergi ke bank.","en":"Tomorrow at 3 p.m. I'm going to the bank."},{"zh":"他星期天早上不上班。","py":"tā xīng qí tiān zǎo shàng bú shàng bān","id":"Hari Minggu pagi dia tidak kerja.","en":"He does not work on Sunday morning."}]},{"title":{"id":"Menyebut jam: Num + 點 + Num + 分 / 半","en":"Telling the clock time"},"pattern":"Num + 點 + Num + 分  /  Num + 點半","note":{"id":"Jam disebut dengan 點, menit dengan 分, dan setengah dengan 半. Untuk jam dua pakai 兩點, bukan 二點. Tidak ada kata 'pukul' atau 'jam' tambahan; cukup angka lalu 點.","en":"Use 點 for the hour, 分 for minutes and 半 for half past. Say 兩點 for two o'clock, not 二點."},"ex":[{"zh":"現在是兩點半。","py":"xiàn zài shì liǎng diǎn bàn","id":"Sekarang jam setengah tiga.","en":"It is half past two now."},{"zh":"火車九點十五分到。","py":"huǒ chē jiǔ diǎn shí wǔ fēn dào","id":"Kereta tiba jam sembilan lewat lima belas.","en":"The train arrives at nine fifteen."}]},{"title":{"id":"Tanggal dan hari: 月 / 號 / 星期","en":"Months, dates and days"},"pattern":"Num + 月 + Num + 號  ;  星期 + Num","note":{"id":"Bulan dan tanggal berurutan dari besar ke kecil: 月 lalu 號. Nama bulan memakai angka, misalnya 五月 untuk Mei. Hari dibuat dengan 星期 plus angka satu sampai enam; hari Minggu adalah 星期天. Untuk bertanya pakai 幾月幾號 atau 星期幾.","en":"Months are numbers plus 月, dates are numbers plus 號. Weekdays are 星期 plus a number, and Sunday is 星期天."},"ex":[{"zh":"今天是幾月幾號？","py":"jīn tiān shì jǐ yuè jǐ hào","id":"Hari ini tanggal berapa?","en":"What is the date today?"},{"zh":"我的生日是五月二十號。","py":"wǒ de shēng rì shì wǔ yuè èr shí hào","id":"Ulang tahunku tanggal dua puluh Mei.","en":"My birthday is on May 20th."}]},{"title":{"id":"Sebelum dan sesudah: 以前 / 以後 / 的時候","en":"Before, after and when"},"pattern":"V + 以前 / 以後 / 的時候","note":{"id":"Taruh 以前 (sebelum), 以後 (setelah), atau 的時候 (ketika) di belakang kegiatan. Kegiatan penjelas waktu ada di awal, lalu kegiatan utama menyusul. Urutannya terbalik dari bahasa Indonesia: 'sebelum makan' menjadi 吃飯以前, bukan 以前吃飯.","en":"Put 以前, 以後 or 的時候 after the event it refers to, then give the main clause."},"ex":[{"zh":"吃飯以前要洗手。","py":"chī fàn yǐ qián yào xǐ shǒu","id":"Sebelum makan harus cuci tangan.","en":"Wash your hands before eating."},{"zh":"下班以後我去運動。","py":"xià bān yǐ hòu wǒ qù yùn dòng","id":"Setelah pulang kerja aku berolahraga.","en":"After work I go exercise."},{"zh":"我在台灣的時候，常去夜市。","py":"wǒ zài tái wān de shí hòu cháng qù yè shì","id":"Waktu di Taiwan, aku sering ke pasar malam.","en":"When I was in Taiwan, I often went to night markets."}]}],"dialog":[{"sp":"A","zh":"我們什麼時候去夜市？","py":"wǒ men shén me shí hòu qù yè shì","id":"Kapan kita ke pasar malam?","en":"When shall we go to the night market?"},{"sp":"B","zh":"星期六晚上，好不好？","py":"xīng qí liù wǎn shàng hǎo bu hǎo","id":"Sabtu malam, bagaimana?","en":"Saturday night, okay?"},{"sp":"A","zh":"星期六幾點？","py":"xīng qí liù jǐ diǎn","id":"Sabtu jam berapa?","en":"What time on Saturday?"},{"sp":"B","zh":"六點半在捷運站見面。","py":"liù diǎn bàn zài jié yùn zhàn jiàn miàn","id":"Jam setengah tujuh ketemu di stasiun MRT.","en":"Let's meet at the MRT station at half past six."},{"sp":"A","zh":"好，我下午先去銀行，然後回家。","py":"hǎo wǒ xià wǔ xiān qù yín háng rán hòu huí jiā","id":"Oke, sore aku ke bank dulu, lalu pulang.","en":"Okay, in the afternoon I'll go to the bank first, then go home."},{"sp":"B","zh":"沒問題，星期六見！","py":"méi wèn tí xīng qí liù jiàn","id":"Siap, sampai ketemu Sabtu!","en":"No problem, see you Saturday!"}],"n":"09"},{"k":"angka","zh":"數字量詞","py":"shù zì liàng cí","title":{"id":"Angka dan kata satuan","en":"Numbers and measure words","tl":"Mga numero at measure word","vi":"Số đếm và lượng từ"},"desc":{"id":"Kamu bisa menyebut angka, menanyakan jumlah, dan menghitung benda dengan kata satuan yang tepat.","en":"You can say numbers, ask about quantities, and count things with the right measure word."},"icon":"coin","sets":[{"title":{"id":"Angka","en":"Numbers"},"words":[{"hz":"零","ex":{"zh":"我的房間號碼是二零五。","py":"wǒ de fáng jiān hào mǎ shì èr líng wǔ","id":"Nomor kamarku 205.","en":"My room number is 205."}},{"hz":"一","ex":{"zh":"我有一個哥哥。","py":"wǒ yǒu yí ge gē ge","id":"Aku punya satu kakak laki-laki.","en":"I have one older brother."}},{"hz":"二","ex":{"zh":"二樓有一家書店。","py":"èr lóu yǒu yì jiā shū diàn","id":"Di lantai dua ada sebuah toko buku.","en":"There is a bookstore on the second floor."}},{"hz":"兩","ex":{"zh":"我買了兩杯茶。","py":"wǒ mǎi le liǎng bēi chá","id":"Aku membeli dua gelas teh.","en":"I bought two cups of tea."}},{"hz":"十","ex":{"zh":"這本書十塊錢。","py":"zhè běn shū shí kuài qián","id":"Buku ini sepuluh dolar.","en":"This book is ten dollars."}},{"hz":"百","ex":{"zh":"這件衣服三百元。","py":"zhè jiàn yī fú sān bǎi yuán","id":"Baju ini tiga ratus dolar.","en":"This top is three hundred dollars."}},{"hz":"千","ex":{"zh":"這支手機要三千塊。","py":"zhè zhī shǒu jī yào sān qiān kuài","id":"Ponsel ini tiga ribu dolar.","en":"This phone costs three thousand dollars."}},{"hz":"萬","ex":{"zh":"這台筆電要三萬塊。","py":"zhè tái bǐ diàn yào sān wàn kuài","id":"Laptop ini tiga puluh ribu dolar.","en":"This laptop costs thirty thousand dollars."}},{"hz":"半","ex":{"zh":"我等了半個小時。","py":"wǒ děng le bàn ge xiǎo shí","id":"Aku menunggu setengah jam.","en":"I waited half an hour."}}]},{"title":{"id":"Bertanya jumlah dan urutan","en":"Asking quantity and order"},"words":[{"hz":"幾","ex":{"zh":"你家有幾個人？","py":"nǐ jiā yǒu jǐ ge rén","id":"Di rumahmu ada berapa orang?","en":"How many people are in your family?"}},{"hz":"多少","ex":{"zh":"這個多少錢？","py":"zhè ge duō shǎo qián","id":"Ini berapa harganya?","en":"How much is this?"}},{"hz":"第","ex":{"zh":"我在第三站下車。","py":"wǒ zài dì sān zhàn xià chē","id":"Aku turun di stasiun ketiga.","en":"I get off at the third stop."}},{"hz":"第一","ex":{"zh":"他是我們班第一名。","py":"tā shì wǒ men bān dì yī míng","id":"Dia peringkat pertama di kelas kami.","en":"He is first in our class."}},{"hz":"第二","ex":{"zh":"第二課比第一課難。","py":"dì èr kè bǐ dì yī kè nán","id":"Pelajaran kedua lebih sulit daripada pelajaran pertama.","en":"Lesson two is harder than lesson one."}},{"hz":"一共","ex":{"zh":"一共三百二十元。","py":"yí gòng sān bǎi èr shí yuán","id":"Totalnya tiga ratus dua puluh dolar.","en":"The total is 320 dollars."}},{"hz":"一半","ex":{"zh":"這杯茶我喝了一半。","py":"zhè bēi chá wǒ hē le yí bàn","id":"Teh ini sudah kuminum setengahnya.","en":"I drank half of this tea."}},{"hz":"倍","ex":{"zh":"他的書是我的兩倍。","py":"tā de shū shì wǒ de liǎng bèi","id":"Bukunya dua kali lipat dari bukuku.","en":"He has twice as many books as I do."}},{"hz":"每","ex":{"zh":"我每天喝兩杯咖啡。","py":"wǒ měi tiān hē liǎng bēi kā fēi","id":"Aku minum dua cangkir kopi setiap hari.","en":"I drink two cups of coffee every day."}}]},{"title":{"id":"Kata satuan umum","en":"Common measure words"},"words":[{"hz":"個","ex":{"zh":"教室裡有十個學生。","py":"jiào shì lǐ yǒu shí ge xué shēng","id":"Di kelas ada sepuluh murid.","en":"There are ten students in the classroom."}},{"hz":"本","ex":{"zh":"我買了兩本書。","py":"wǒ mǎi le liǎng běn shū","id":"Aku membeli dua buku.","en":"I bought two books."}},{"hz":"張","ex":{"zh":"我要買兩張票。","py":"wǒ yào mǎi liǎng zhāng piào","id":"Aku mau beli dua tiket.","en":"I want to buy two tickets."}},{"hz":"杯","ex":{"zh":"請給我一杯茶。","py":"qǐng gěi wǒ yì bēi chá","id":"Tolong beri aku secangkir teh.","en":"Please give me a cup of tea."}},{"hz":"件","ex":{"zh":"我有三件外套。","py":"wǒ yǒu sān jiàn wài tào","id":"Aku punya tiga jaket.","en":"I have three jackets."}},{"hz":"隻","ex":{"zh":"我家有兩隻貓。","py":"wǒ jiā yǒu liǎng zhī māo","id":"Di rumahku ada dua ekor kucing.","en":"I have two cats at home."}},{"hz":"條","ex":{"zh":"這條路很長。","py":"zhè tiáo lù hěn cháng","id":"Jalan ini panjang sekali.","en":"This road is very long."}},{"hz":"輛","ex":{"zh":"門口有三輛汽車。","py":"mén kǒu yǒu sān liàng qì chē","id":"Di depan pintu ada tiga mobil.","en":"There are three cars at the entrance."}},{"hz":"雙","ex":{"zh":"我有一雙新鞋。","py":"wǒ yǒu yì shuāng xīn xié","id":"Aku punya sepasang sepatu baru.","en":"I have a pair of new shoes."}}]},{"title":{"id":"Kata satuan untuk makanan dan lainnya","en":"More measure words"},"words":[{"hz":"瓶","ex":{"zh":"我想喝一瓶水。","py":"wǒ xiǎng hē yì píng shuǐ","id":"Aku mau minum sebotol air.","en":"I want to drink a bottle of water."}},{"hz":"碗","ex":{"zh":"我要一碗牛肉麵。","py":"wǒ yào yì wǎn niú ròu miàn","id":"Aku mau semangkuk mi sapi.","en":"I want a bowl of beef noodles."}},{"hz":"位","ex":{"zh":"請問你們有幾位？","py":"qǐng wèn nǐ men yǒu jǐ wèi","id":"Permisi, kalian berapa orang?","en":"Excuse me, how many of you are there?"}},{"hz":"盤","ex":{"zh":"我們點了一盤青菜。","py":"wǒ men diǎn le yì pán qīng cài","id":"Kami memesan sepiring sayur.","en":"We ordered a plate of greens."}},{"hz":"盒","ex":{"zh":"我買了一盒蛋糕。","py":"wǒ mǎi le yì hé dàn gāo","id":"Aku membeli sekotak kue.","en":"I bought a box of cake."}},{"hz":"次","ex":{"zh":"我去過台北兩次。","py":"wǒ qù guò tái běi liǎng cì","id":"Aku sudah pernah ke Taipei dua kali.","en":"I have been to Taipei twice."}},{"hz":"歲","ex":{"zh":"我今年二十二歲。","py":"wǒ jīn nián èr shí èr suì","id":"Tahun ini aku berumur dua puluh dua tahun.","en":"I am twenty-two years old this year."}},{"hz":"台","ex":{"zh":"我家有一台電視。","py":"wǒ jiā yǒu yì tái diàn shì","id":"Di rumahku ada satu televisi.","en":"We have a TV at home."}}]}],"grammar":[{"title":{"id":"Menghitung benda: Angka + kata satuan + benda","en":"Counting things: Num + MW + N"},"pattern":"Num + MW + N","note":{"id":"Dalam bahasa Mandarin, angka tidak boleh langsung bertemu benda; harus ada kata satuan di antaranya, misalnya 個, 本, 杯. Orang Indonesia sering lupa kata satuan (bukan 我有三書, tetapi 我有三本書). Kalau ragu, 個 bisa dipakai untuk banyak benda dan orang.","en":"In Chinese a number cannot go directly before a noun; a measure word must come between them, such as 個, 本 or 杯. Learners often forget it (not 我有三書 but 我有三本書). When unsure, 個 works for many things and people."},"ex":[{"zh":"我有兩個哥哥。","py":"wǒ yǒu liǎng ge gē ge","id":"Aku punya dua kakak laki-laki.","en":"I have two older brothers."},{"zh":"我買了三本書。","py":"wǒ mǎi le sān běn shū","id":"Aku membeli tiga buku.","en":"I bought three books."},{"zh":"桌上有一杯茶。","py":"zhuō shàng yǒu yì bēi chá","id":"Di meja ada secangkir teh.","en":"There is a cup of tea on the table."}]},{"title":{"id":"Bertanya jumlah: 幾 dan 多少","en":"Asking how many: 幾 and 多少"},"pattern":"幾 + MW + N？ / 多少 + N？","note":{"id":"幾 dipakai untuk jumlah kecil (kira-kira di bawah sepuluh) dan harus diikuti kata satuan. 多少 dipakai untuk jumlah yang bisa besar, kata satuan boleh dihilangkan, dan dipakai untuk menanyakan harga: 多少錢？","en":"幾 is for small numbers (roughly under ten) and must be followed by a measure word. 多少 is for any size of number, the measure word is optional, and it is used for prices: 多少錢？"},"ex":[{"zh":"你有幾隻貓？","py":"nǐ yǒu jǐ zhī māo","id":"Kamu punya berapa ekor kucing?","en":"How many cats do you have?"},{"zh":"你們班有多少學生？","py":"nǐ men bān yǒu duō shǎo xué shēng","id":"Di kelasmu ada berapa murid?","en":"How many students are in your class?"},{"zh":"這本書多少錢？","py":"zhè běn shū duō shǎo qián","id":"Buku ini berapa harganya?","en":"How much is this book?"}]},{"title":{"id":"二 dan 兩: dua","en":"二 vs 兩: two"},"pattern":"兩 + MW + N / 二 (angka, urutan)","note":{"id":"Sebelum kata satuan, \"dua\" memakai 兩 (兩個人, 兩杯茶), bukan 二. Jam dua juga 兩點. 二 dipakai saat menghitung (一、二、三), untuk nomor, lantai, urutan, dan di dalam bilangan seperti 十二, 二十. Untuk 200, orang Taiwan biasa bilang 兩百.","en":"Before a measure word, \"two\" is 兩 (兩個人, 兩杯茶), not 二; two o'clock is also 兩點. 二 is used when counting (一、二、三), for numbers, floors and ordinals, and inside numbers like 十二, 二十. For 200, people in Taiwan usually say 兩百."},"ex":[{"zh":"我有兩個妹妹。","py":"wǒ yǒu liǎng ge mèi mei","id":"Aku punya dua adik perempuan.","en":"I have two younger sisters."},{"zh":"我住在二樓。","py":"wǒ zhù zài èr lóu","id":"Aku tinggal di lantai dua.","en":"I live on the second floor."},{"zh":"現在是兩點二十分。","py":"xiàn zài shì liǎng diǎn èr shí fēn","id":"Sekarang pukul dua lewat dua puluh menit.","en":"It is twenty past two now."}]},{"title":{"id":"Urutan: 第 + angka","en":"Ordinals: 第 + Num"},"pattern":"第 + Num (+ MW)","note":{"id":"Tambahkan 第 di depan angka untuk membuat urutan: 第一 (pertama), 第二 (kedua). Setelah itu biasanya diikuti kata satuan atau benda, misalnya 第一次 (pertama kali), 第三站 (stasiun ketiga).","en":"Put 第 before a number to make an ordinal: 第一 (first), 第二 (second). It is usually followed by a measure word or noun, such as 第一次 (the first time) or 第三站 (the third stop)."},"ex":[{"zh":"這是我第一次來台灣。","py":"zhè shì wǒ dì yī cì lái tái wān","id":"Ini pertama kalinya aku datang ke Taiwan.","en":"This is my first time in Taiwan."},{"zh":"請看第二十頁。","py":"qǐng kàn dì èr shí yè","id":"Silakan lihat halaman dua puluh.","en":"Please look at page twenty."},{"zh":"我在第三站下車。","py":"wǒ zài dì sān zhàn xià chē","id":"Aku turun di stasiun ketiga.","en":"I get off at the third stop."}]}],"dialog":[{"zh":"你好，請問幾位？","py":"nǐ hǎo qǐng wèn jǐ wèi","id":"Halo, berapa orang?","en":"Hello, how many people?","sp":"A"},{"zh":"兩位。","py":"liǎng wèi","id":"Dua orang.","en":"Two.","sp":"B"},{"zh":"請坐。你們想喝什麼？","py":"qǐng zuò nǐ men xiǎng hē shén me","id":"Silakan duduk. Kalian mau minum apa?","en":"Please sit. What would you like to drink?","sp":"A"},{"zh":"我要一杯茶，他要一杯咖啡。","py":"wǒ yào yì bēi chá tā yào yì bēi kā fēi","id":"Aku mau secangkir teh, dia mau secangkir kopi.","en":"I'd like a cup of tea, and he'd like a cup of coffee.","sp":"B"},{"zh":"要吃什麼？","py":"yào chī shén me","id":"Mau makan apa?","en":"What would you like to eat?","sp":"A"},{"zh":"我們要一碗牛肉麵和一盤青菜。","py":"wǒ men yào yì wǎn niú ròu miàn hé yì pán qīng cài","id":"Kami mau semangkuk mi sapi dan sepiring sayur.","en":"We'd like a bowl of beef noodles and a plate of greens.","sp":"B"},{"zh":"好的，一共兩百八十元。","py":"hǎo de yí gòng liǎng bǎi bā shí yuán","id":"Baik, totalnya dua ratus delapan puluh dolar.","en":"Okay, that's 280 dollars in total.","sp":"A"},{"zh":"好，謝謝。","py":"hǎo xiè xie","id":"Baik, terima kasih.","en":"Okay, thank you.","sp":"B"}],"n":"10"},{"k":"belanja","zh":"購物付錢","py":"gòu wù fù qián","title":{"id":"Belanja dan membayar","en":"Shopping and paying","tl":"Pamimili at pagbabayad","vi":"Mua sắm và thanh toán"},"desc":{"id":"Kamu bisa menanyakan harga, menawar, mencoba baju, dan membayar di toko atau pasar malam.","en":"You can ask prices, bargain, try on clothes, and pay in a shop or night market."},"icon":"cart","sets":[{"title":{"id":"Tempat belanja dan orangnya","en":"Places and people"},"words":[{"hz":"商店","ex":{"zh":"這家商店賣很多東西。","py":"zhè jiā shāng diàn mài hěn duō dōng xi","id":"Toko ini menjual banyak barang.","en":"This shop sells many things."},"mw":"家"},{"hz":"市場","ex":{"zh":"我媽媽常去市場買菜。","py":"wǒ mā ma cháng qù shì chǎng mǎi cài","id":"Ibuku sering pergi ke pasar membeli sayur.","en":"My mom often goes to the market to buy vegetables."},"mw":"個"},{"hz":"超級市場","ex":{"zh":"超級市場在捷運站旁邊。","py":"chāo jí shì chǎng zài jié yùn zhàn páng biān","id":"Supermarket ada di sebelah stasiun MRT.","en":"The supermarket is next to the MRT station."},"mw":"家"},{"hz":"書店","ex":{"zh":"我想去書店買一本書。","py":"wǒ xiǎng qù shū diàn mǎi yì běn shū","id":"Aku mau ke toko buku untuk beli buku.","en":"I want to go to the bookstore to buy a book."},"mw":"家"},{"hz":"夜市","ex":{"zh":"週末我們去夜市吃東西。","py":"zhōu mò wǒ men qù yè shì chī dōng xi","id":"Akhir pekan kami ke pasar malam untuk makan-makan.","en":"On the weekend we go to the night market to eat."},"mw":"個"},{"hz":"百貨公司","ex":{"zh":"百貨公司十點開門。","py":"bǎi huò gōng sī shí diǎn kāi mén","id":"Mal buka jam sepuluh.","en":"The department store opens at ten."},"mw":"家"},{"hz":"老闆","ex":{"zh":"老闆，這個多少錢？","py":"lǎo bǎn zhè ge duō shǎo qián","id":"Bos, ini berapa harganya?","en":"Boss, how much is this?"},"mw":"位"},{"hz":"店員","ex":{"zh":"店員說這件賣完了。","py":"diàn yuán shuō zhè jiàn mài wán le","id":"Pegawai toko bilang yang ini sudah habis.","en":"The clerk said this one is sold out."},"mw":"位"},{"hz":"客人","ex":{"zh":"今天店裡有很多客人。","py":"jīn tiān diàn lǐ yǒu hěn duō kè rén","id":"Hari ini di toko ada banyak pelanggan.","en":"There are many customers in the shop today."},"mw":"位"}]},{"title":{"id":"Menanyakan harga","en":"Talking about prices"},"words":[{"hz":"多少錢","ex":{"zh":"這杯茶多少錢？","py":"zhè bēi chá duō shǎo qián","id":"Teh ini berapa harganya?","en":"How much is this tea?"}},{"hz":"貴","ex":{"zh":"這件外套太貴了。","py":"zhè jiàn wài tào tài guì le","id":"Jaket ini terlalu mahal.","en":"This jacket is too expensive."}},{"hz":"便宜","ex":{"zh":"夜市的東西比較便宜。","py":"yè shì de dōng xi bǐ jiào pián yí","id":"Barang di pasar malam lebih murah.","en":"Things at the night market are cheaper."}},{"hz":"特價","ex":{"zh":"今天牛奶特價。","py":"jīn tiān niú nǎi tè jià","id":"Hari ini susu sedang diskon.","en":"Milk is on special today."}},{"hz":"打折","ex":{"zh":"這家店今天全部打折。","py":"zhè jiā diàn jīn tiān quán bù dǎ zhé","id":"Toko ini hari ini diskon semuanya.","en":"This shop has everything on sale today."}},{"hz":"半價","ex":{"zh":"下午五點以後麵包半價。","py":"xià wǔ wǔ diǎn yǐ hòu miàn bāo bàn jià","id":"Setelah jam lima sore roti setengah harga.","en":"After five in the afternoon bread is half price."}},{"hz":"元","ex":{"zh":"這本書三百元。","py":"zhè běn shū sān bǎi yuán","id":"Buku ini tiga ratus dolar.","en":"This book is three hundred dollars."}},{"hz":"塊","ex":{"zh":"一杯咖啡四十五塊。","py":"yì bēi kā fēi sì shí wǔ kuài","id":"Secangkir kopi empat puluh lima dolar.","en":"A cup of coffee is forty-five dollars."}},{"hz":"買一送一","ex":{"zh":"這家店的飲料買一送一。","py":"zhè jiā diàn de yǐn liào mǎi yí sòng yī","id":"Minuman di toko ini beli satu gratis satu.","en":"The drinks at this shop are buy one get one free."}},{"hz":"算便宜","ex":{"zh":"老闆，可以算便宜一點嗎？","py":"lǎo bǎn kě yǐ suàn pián yí yì diǎn ma","id":"Bos, bisa kurangi harganya sedikit?","en":"Boss, can you give me a bit of a discount?"}}]},{"title":{"id":"Uang dan cara bayar","en":"Money and paying"},"words":[{"hz":"錢","ex":{"zh":"我今天沒帶錢。","py":"wǒ jīn tiān méi dài qián","id":"Hari ini aku tidak bawa uang.","en":"I didn't bring money today."}},{"hz":"台幣","ex":{"zh":"我想換一些台幣。","py":"wǒ xiǎng huàn yì xiē tái bì","id":"Aku mau menukar uang ke dolar Taiwan.","en":"I want to exchange some money into Taiwan dollars."}},{"hz":"零錢","ex":{"zh":"你有零錢嗎？","py":"nǐ yǒu líng qián ma","id":"Kamu punya uang receh?","en":"Do you have small change?"}},{"hz":"付錢","ex":{"zh":"我來付錢。","py":"wǒ lái fù qián","id":"Biar aku yang bayar.","en":"I'll pay."}},{"hz":"花錢","ex":{"zh":"在台北生活很花錢。","py":"zài tái běi shēng huó hěn huā qián","id":"Hidup di Taipei butuh banyak uang.","en":"Living in Taipei costs a lot of money."}},{"hz":"信用卡","ex":{"zh":"這裡可以用信用卡嗎？","py":"zhè lǐ kě yǐ yòng xìn yòng kǎ ma","id":"Di sini bisa pakai kartu kredit?","en":"Can I use a credit card here?"},"mw":"張"},{"hz":"悠遊卡","ex":{"zh":"我用悠遊卡坐捷運。","py":"wǒ yòng yōu yóu kǎ zuò jié yùn","id":"Aku naik MRT pakai kartu EasyCard.","en":"I ride the MRT with an EasyCard."},"mw":"張"},{"hz":"刷卡","ex":{"zh":"我想刷卡，可以嗎？","py":"wǒ xiǎng shuā kǎ kě yǐ ma","id":"Aku mau bayar pakai kartu, boleh?","en":"I'd like to pay by card, is that okay?"}},{"hz":"收銀台","ex":{"zh":"收銀台在門口旁邊。","py":"shōu yín tái zài mén kǒu páng biān","id":"Kasir ada di samping pintu.","en":"The cashier counter is next to the door."}}]},{"title":{"id":"Memilih dan mencoba","en":"Choosing and trying on"},"words":[{"hz":"衣服","ex":{"zh":"這件衣服很好看。","py":"zhè jiàn yī fú hěn hǎo kàn","id":"Baju ini bagus sekali.","en":"This top looks nice."},"mw":"件"},{"hz":"外套","ex":{"zh":"我想買一件新外套。","py":"wǒ xiǎng mǎi yí jiàn xīn wài tào","id":"Aku mau beli jaket baru.","en":"I want to buy a new jacket."},"mw":"件"},{"hz":"顏色","ex":{"zh":"你喜歡什麼顏色？","py":"nǐ xǐ huān shén me yán sè","id":"Kamu suka warna apa?","en":"What color do you like?"},"mw":"種"},{"hz":"試穿","ex":{"zh":"我可以試穿嗎？","py":"wǒ kě yǐ shì chuān ma","id":"Boleh aku coba pakai?","en":"Can I try it on?"}},{"hz":"合適","ex":{"zh":"這個大小很合適。","py":"zhè ge dà xiǎo hěn hé shì","id":"Ukuran ini pas sekali.","en":"This size fits well."}},{"hz":"號碼","ex":{"zh":"請問你的電話號碼是多少？","py":"qǐng wèn nǐ de diàn huà hào mǎ shì duō shǎo","id":"Boleh tahu nomor teleponmu berapa?","en":"May I have your phone number?"},"mw":"個"},{"hz":"賣完","ex":{"zh":"這個顏色已經賣完了。","py":"zhè ge yán sè yǐ jīng mài wán le","id":"Warna ini sudah habis terjual.","en":"This color is already sold out."}},{"hz":"袋子","ex":{"zh":"請問要袋子嗎？","py":"qǐng wèn yào dài zi ma","id":"Permisi, mau pakai kantong?","en":"Excuse me, would you like a bag?"},"mw":"個"}]}],"grammar":[{"title":{"id":"Menyebut harga: Benda + angka + 塊/元","en":"Stating prices: N + Num + 塊/元"},"pattern":"N + Num + 塊 / 元","note":{"id":"Harga cukup disebut setelah bendanya, tanpa kata kerja \"adalah\". Dalam percakapan orang Taiwan bilang 塊, di tulisan atau label harga 元. Untuk bertanya pakai 多少錢？ Angka besar: 三百、兩千、三萬.","en":"State the price right after the item, with no verb like \"is\". In speech Taiwanese say 塊; on labels and in writing it is 元. To ask, use 多少錢？ Large numbers: 三百, 兩千, 三萬."},"ex":[{"zh":"這件衣服八百元。","py":"zhè jiàn yī fú bā bǎi yuán","id":"Baju ini delapan ratus dolar.","en":"This top is 800 dollars."},{"zh":"一杯咖啡六十五塊。","py":"yì bēi kā fēi liù shí wǔ kuài","id":"Secangkir kopi enam puluh lima dolar.","en":"A cup of coffee is 65 dollars."},{"zh":"這個麵包多少錢？","py":"zhè ge miàn bāo duō shǎo qián","id":"Roti ini berapa harganya?","en":"How much is this bread?"}]},{"title":{"id":"Mengomentari harga atau ukuran: 太…了 / 有點…","en":"Commenting: 太…了 / 有點…"},"pattern":"太 + Adj + 了  /  有點 + Adj","note":{"id":"太…了 berarti \"terlalu\" dan biasanya dipakai dengan sifat yang tidak diinginkan (太貴了). 有點 + sifat berarti \"agak\", dan juga biasanya untuk hal yang kurang menyenangkan (有點大). Jangan pakai 有點 untuk pujian.","en":"太…了 means \"too (much)\" and is usually used for something undesirable (太貴了). 有點 + adjective means \"a bit\", also mostly for unwanted things (有點大). Do not use 有點 for compliments."},"ex":[{"zh":"這杯咖啡太貴了。","py":"zhè bēi kā fēi tài guì le","id":"Kopi ini terlalu mahal.","en":"This coffee is too expensive."},{"zh":"這件外套有點大。","py":"zhè jiàn wài tào yǒu diǎn dà","id":"Jaket ini agak besar.","en":"This jacket is a bit big."},{"zh":"夜市人太多了。","py":"yè shì rén tài duō le","id":"Pasar malam terlalu ramai.","en":"The night market is too crowded."}]},{"title":{"id":"Meminta izin atau tawaran: 可以…嗎？","en":"Polite requests: 可以…嗎？"},"pattern":"可以 + V + 嗎？","note":{"id":"Untuk bertanya \"boleh … tidak?\" taruh 可以 sebelum kata kerja, lalu tambahkan 嗎 di akhir kalimat. Jawabannya cukup 可以 (boleh) atau 不可以 (tidak boleh). Sangat berguna saat berbelanja.","en":"To ask \"may I …?\", put 可以 before the verb and add 嗎 at the end. Answer with 可以 (yes) or 不可以 (no). Very useful when shopping."},"ex":[{"zh":"可以刷卡嗎？","py":"kě yǐ shuā kǎ ma","id":"Boleh bayar pakai kartu?","en":"Can I pay by card?"},{"zh":"我可以試穿嗎？","py":"wǒ kě yǐ shì chuān ma","id":"Boleh aku coba pakai?","en":"May I try it on?"},{"zh":"可以給我一個袋子嗎？","py":"kě yǐ gěi wǒ yí ge dài zi ma","id":"Boleh minta satu kantong?","en":"Can I have a bag?"}]},{"title":{"id":"Meminta lebih … : Adj + 一點","en":"Asking for a bit more: Adj + 一點"},"pattern":"Adj + 一點 (+ 的 + N)","note":{"id":"Sifat + 一點 berarti \"sedikit lebih …\". Pakai saat menawar atau minta ukuran lain: 便宜一點 (lebih murah sedikit), 大一點 (lebih besar sedikit). Jangan tambah 很 di depan sifat dalam pola ini.","en":"Adjective + 一點 means \"a little more …\". Use it to bargain or ask for another size: 便宜一點 (a bit cheaper), 大一點 (a bit bigger). Do not add 很 before the adjective in this pattern."},"ex":[{"zh":"可以便宜一點嗎？","py":"kě yǐ pián yí yì diǎn ma","id":"Bisa lebih murah sedikit?","en":"Can it be a bit cheaper?"},{"zh":"有小一點的嗎？","py":"yǒu xiǎo yì diǎn de ma","id":"Ada yang lebih kecil?","en":"Do you have a smaller one?"}]}],"dialog":[{"zh":"歡迎光臨！你想買什麼？","py":"huān yíng guāng lín nǐ xiǎng mǎi shén me","id":"Selamat datang! Kamu mau beli apa?","en":"Welcome! What would you like to buy?","sp":"A"},{"zh":"我想買一件外套，可以試穿嗎？","py":"wǒ xiǎng mǎi yí jiàn wài tào kě yǐ shì chuān ma","id":"Aku mau beli jaket, boleh dicoba?","en":"I want a jacket. May I try it on?","sp":"B"},{"zh":"可以，這件今天打折。","py":"kě yǐ zhè jiàn jīn tiān dǎ zhé","id":"Boleh, yang ini hari ini diskon.","en":"Sure, this one is on sale today.","sp":"A"},{"zh":"有點大，有小一點的嗎？","py":"yǒu diǎn dà yǒu xiǎo yì diǎn de ma","id":"Agak besar, ada yang lebih kecil?","en":"It's a bit big. Do you have a smaller one?","sp":"B"},{"zh":"有，這件是黑色的，八百元。","py":"yǒu zhè jiàn shì hēi sè de bā bǎi yuán","id":"Ada, yang ini warna hitam, delapan ratus dolar.","en":"Yes, this one is black, 800 dollars.","sp":"A"},{"zh":"好，我要這件。可以刷卡嗎？","py":"hǎo wǒ yào zhè jiàn kě yǐ shuā kǎ ma","id":"Oke, aku ambil yang ini. Boleh pakai kartu?","en":"Okay, I'll take this. Can I pay by card?","sp":"B"},{"zh":"可以，請到收銀台付錢。","py":"kě yǐ qǐng dào shōu yín tái fù qián","id":"Boleh, silakan bayar di kasir.","en":"Yes, please pay at the cashier.","sp":"A"},{"zh":"謝謝你。","py":"xiè xie nǐ","id":"Terima kasih.","en":"Thank you.","sp":"B"}],"n":"11"},{"k":"sekolah","zh":"學校學習","py":"xué xiào xué xí","title":{"id":"Sekolah dan belajar","en":"School and study","tl":"Paaralan at pag-aaral","vi":"Trường học và học tập"},"desc":{"id":"Kamu bisa bercerita tentang sekolah, pelajaran, kegiatan di kelas, dan ujian.","en":"You can talk about school, subjects, class activities and exams."},"icon":"school","sets":[{"title":{"id":"Tempat dan orang di sekolah","en":"School places and people"},"words":[{"hz":"學校","ex":{"zh":"我的學校在高雄。","py":"wǒ de xué xiào zài gāo xióng","id":"Sekolahku ada di Kaohsiung.","en":"My school is in Kaohsiung."},"mw":"所"},{"hz":"教室","ex":{"zh":"我們的教室在三樓。","py":"wǒ men de jiào shì zài sān lóu","id":"Kelas kami ada di lantai tiga.","en":"Our classroom is on the third floor."},"mw":"間"},{"hz":"圖書館","ex":{"zh":"我常在圖書館看書。","py":"wǒ cháng zài tú shū guǎn kàn shū","id":"Aku sering membaca buku di perpustakaan.","en":"I often read in the library."},"mw":"間"},{"hz":"操場","ex":{"zh":"下課後他們在操場打球。","py":"xià kè hòu tā men zài cāo chǎng dǎ qiú","id":"Setelah pelajaran mereka main bola di lapangan.","en":"After class they play ball on the field."}},{"hz":"宿舍","ex":{"zh":"我住在學校的宿舍。","py":"wǒ zhù zài xué xiào de sù shè","id":"Aku tinggal di asrama sekolah.","en":"I live in the school dorm."},"mw":"間"},{"hz":"老師","ex":{"zh":"老師今天很早到教室。","py":"lǎo shī jīn tiān hěn zǎo dào jiào shì","id":"Hari ini guru datang ke kelas pagi sekali.","en":"The teacher got to the classroom early today."},"mw":"位"},{"hz":"學生","ex":{"zh":"這個班有二十個學生。","py":"zhè ge bān yǒu èr shí ge xué shēng","id":"Kelas ini ada dua puluh murid.","en":"This class has twenty students."},"mw":"個"},{"hz":"同學","ex":{"zh":"我和同學一起吃午餐。","py":"wǒ hé tóng xué yì qǐ chī wǔ cān","id":"Aku makan siang bersama teman sekelas.","en":"I eat lunch with my classmates."},"mw":"位"}]},{"title":{"id":"Mata pelajaran","en":"Subjects"},"words":[{"hz":"中文","ex":{"zh":"我在學校學中文。","py":"wǒ zài xué xiào xué zhōng wén","id":"Aku belajar bahasa Mandarin di sekolah.","en":"I study Chinese at school."}},{"hz":"英文","ex":{"zh":"你的英文說得很好。","py":"nǐ de yīng wén shuō de hěn hǎo","id":"Bahasa Inggrismu bagus sekali.","en":"Your English is very good."}},{"hz":"數學","ex":{"zh":"我覺得數學有點難。","py":"wǒ jué de shù xué yǒu diǎn nán","id":"Menurutku matematika agak sulit.","en":"I think math is a bit hard."}},{"hz":"歷史","ex":{"zh":"我喜歡上歷史課。","py":"wǒ xǐ huān shàng lì shǐ kè","id":"Aku suka pelajaran sejarah.","en":"I like history class."}},{"hz":"音樂","ex":{"zh":"我們星期二有音樂課。","py":"wǒ men xīng qí èr yǒu yīn yuè kè","id":"Hari Selasa kami ada pelajaran musik.","en":"We have music class on Tuesday."}},{"hz":"體育","ex":{"zh":"體育課我們打籃球。","py":"tǐ yù kè wǒ men dǎ lán qiú","id":"Di pelajaran olahraga kami main basket.","en":"In PE class we play basketball."}}]},{"title":{"id":"Di kelas","en":"In class"},"words":[{"hz":"上課","ex":{"zh":"我們八點上課。","py":"wǒ men bā diǎn shàng kè","id":"Kami mulai pelajaran jam delapan.","en":"Our class starts at eight."}},{"hz":"下課","ex":{"zh":"下課以後我去吃飯。","py":"xià kè yǐ hòu wǒ qù chī fàn","id":"Setelah pelajaran selesai aku pergi makan.","en":"After class I go to eat."}},{"hz":"課本","ex":{"zh":"請打開課本第十頁。","py":"qǐng dǎ kāi kè běn dì shí yè","id":"Tolong buka buku pelajaran halaman sepuluh.","en":"Please open your textbook to page ten."},"mw":"本"},{"hz":"黑板","ex":{"zh":"老師在黑板上寫字。","py":"lǎo shī zài hēi bǎn shàng xiě zì","id":"Guru menulis di papan tulis.","en":"The teacher writes on the blackboard."},"mw":"塊"},{"hz":"作業","ex":{"zh":"今天的作業很多。","py":"jīn tiān de zuò yè hěn duō","id":"Hari ini PR-nya banyak.","en":"There is a lot of homework today."},"mw":"份"},{"hz":"筆記本","ex":{"zh":"我的筆記本在書包裡。","py":"wǒ de bǐ jì běn zài shū bāo lǐ","id":"Buku catatanku ada di dalam tas.","en":"My notebook is in my school bag."},"mw":"本"},{"hz":"字典","ex":{"zh":"我用字典查生字。","py":"wǒ yòng zì diǎn chá shēng zì","id":"Aku mencari kata baru dengan kamus.","en":"I look up new characters in a dictionary."},"mw":"本"},{"hz":"書包","ex":{"zh":"他的書包很重。","py":"tā de shū bāo hěn zhòng","id":"Tas sekolahnya berat sekali.","en":"His school bag is very heavy."},"mw":"個"},{"hz":"例子","ex":{"zh":"請舉一個例子。","py":"qǐng jǔ yí ge lì zi","id":"Tolong beri satu contoh.","en":"Please give an example."},"mw":"個"}]},{"title":{"id":"Kata kerja belajar","en":"Study verbs"},"words":[{"hz":"學習","ex":{"zh":"我每天學習中文。","py":"wǒ měi tiān xué xí zhōng wén","id":"Setiap hari aku belajar bahasa Mandarin.","en":"I study Chinese every day."}},{"hz":"讀","ex":{"zh":"我在讀一本英文書。","py":"wǒ zài dú yì běn yīng wén shū","id":"Aku sedang membaca sebuah buku bahasa Inggris.","en":"I am reading an English book."}},{"hz":"念","ex":{"zh":"請你念這個句子。","py":"qǐng nǐ niàn zhè ge jù zi","id":"Tolong bacakan kalimat ini.","en":"Please read this sentence aloud."}},{"hz":"寫","ex":{"zh":"我寫字寫得很慢。","py":"wǒ xiě zì xiě de hěn màn","id":"Aku menulis dengan lambat.","en":"I write slowly."}},{"hz":"問","ex":{"zh":"我可以問一個問題嗎？","py":"wǒ kě yǐ wèn yí ge wèn tí ma","id":"Boleh aku bertanya satu pertanyaan?","en":"May I ask a question?"}},{"hz":"回答","ex":{"zh":"請同學回答這個問題。","py":"qǐng tóng xué huí dá zhè ge wèn tí","id":"Tolong salah satu teman menjawab pertanyaan ini.","en":"Will a classmate please answer this question?"}},{"hz":"練習","ex":{"zh":"我們每天練習說中文。","py":"wǒ men měi tiān liàn xí shuō zhōng wén","id":"Setiap hari kami berlatih berbicara bahasa Mandarin.","en":"We practice speaking Chinese every day."}},{"hz":"懂","ex":{"zh":"老師說的我都懂。","py":"lǎo shī shuō de wǒ dōu dǒng","id":"Aku mengerti semua yang guru katakan.","en":"I understand everything the teacher says."}},{"hz":"記得","ex":{"zh":"你記得今天有考試嗎？","py":"nǐ jì de jīn tiān yǒu kǎo shì ma","id":"Kamu ingat hari ini ada ujian?","en":"Do you remember there is a test today?"}}]},{"title":{"id":"Ujian dan libur","en":"Exams and holidays"},"words":[{"hz":"考試","ex":{"zh":"明天有中文考試。","py":"míng tiān yǒu zhōng wén kǎo shì","id":"Besok ada ujian bahasa Mandarin.","en":"There is a Chinese test tomorrow."},"mw":"次"},{"hz":"成績","ex":{"zh":"他的成績很好。","py":"tā de chéng jī hěn hǎo","id":"Nilainya bagus.","en":"His grades are very good."}},{"hz":"期中考","ex":{"zh":"下星期有期中考。","py":"xià xīng qí yǒu qí zhōng kǎo","id":"Minggu depan ada ujian tengah semester.","en":"There is a midterm next week."}},{"hz":"滿分","ex":{"zh":"這次考試他拿到滿分。","py":"zhè cì kǎo shì tā ná dào mǎn fēn","id":"Di ujian kali ini dia mendapat nilai penuh.","en":"He got full marks on this exam."}},{"hz":"不及格","ex":{"zh":"我數學考不及格。","py":"wǒ shù xué kǎo bù jí gé","id":"Aku tidak lulus ujian matematika.","en":"I failed my math exam."}},{"hz":"放假","ex":{"zh":"明天學校放假。","py":"míng tiān xué xiào fàng jià","id":"Besok sekolah libur.","en":"There's no school tomorrow."}},{"hz":"畢業","ex":{"zh":"他明年大學畢業。","py":"tā míng nián dà xué bì yè","id":"Tahun depan dia lulus kuliah.","en":"He graduates from university next year."}}]}],"grammar":[{"title":{"id":"Tempat kegiatan: 在 + tempat + kata kerja","en":"Where you do things: 在 + place + V"},"pattern":"S + 在 + Place + V","note":{"id":"Dalam bahasa Mandarin, tempat kegiatan ditaruh sebelum kata kerja, bukan sesudahnya: 我在圖書館讀書 (bukan 我讀書在圖書館). Pola ini dipakai untuk semua kegiatan di sekolah.","en":"In Chinese the place goes before the verb, not after: 我在圖書館讀書 (not 我讀書在圖書館). This pattern works for every school activity."},"ex":[{"zh":"我在教室上課。","py":"wǒ zài jiào shì shàng kè","id":"Aku belajar di kelas.","en":"I have class in the classroom."},{"zh":"老師在黑板上寫字。","py":"lǎo shī zài hēi bǎn shàng xiě zì","id":"Guru menulis di papan tulis.","en":"The teacher writes on the blackboard."},{"zh":"我們在操場打球。","py":"wǒ men zài cāo chǎng dǎ qiú","id":"Kami main bola di lapangan.","en":"We play ball on the field."}]},{"title":{"id":"Menilai kemampuan: Kata kerja + 得 + sifat","en":"How well you do something: V + 得 + Adj"},"pattern":"(V + O) + V + 得 + 很 + Adj","note":{"id":"Untuk menilai seberapa baik atau cepat suatu kegiatan, pakai kata kerja + 得 + sifat. Jika ada objek, ulangi kata kerjanya: 他說中文說得很好. Sebelum sifat biasanya ada 很 (atau kata keterangan lain). Jangan tulis 的 di sini: 得 dan 的 dibaca sama (de), tetapi di pola ini yang benar 得.","en":"To say how well or how fast something is done, use verb + 得 + adjective. If there is an object, repeat the verb: 他說中文說得很好. The adjective usually takes 很 (or another adverb). Do not write 的 here: both are read de, but 得 is correct in this pattern."},"ex":[{"zh":"他說中文說得很好。","py":"tā shuō zhōng wén shuō de hěn hǎo","id":"Dia bicara bahasa Mandarin dengan sangat baik.","en":"He speaks Chinese very well."},{"zh":"她寫字寫得很快。","py":"tā xiě zì xiě de hěn kuài","id":"Dia menulis dengan cepat.","en":"She writes quickly."},{"zh":"他跑得很快。","py":"tā pǎo de hěn kuài","id":"Dia larinya cepat sekali.","en":"He runs very fast."}]},{"title":{"id":"Pengalaman: Kata kerja + 過","en":"Past experience: V + 過"},"pattern":"S + V + 過 + (O)  /  S + 沒 + V + 過 + O","note":{"id":"Tambahkan 過 setelah kata kerja untuk mengatakan sudah pernah mengalami sesuatu. Bentuk negatifnya 沒 + kata kerja + 過 (belum pernah). Jangan pakai 不 di sini. Pertanyaan: V + 過 + O + 嗎？","en":"Add 過 after a verb to say you have done something before. The negative is 沒 + verb + 過 (have never). Do not use 不 here. Question: V + 過 + O + 嗎？"},"ex":[{"zh":"你學過英文嗎？","py":"nǐ xué guò yīng wén ma","id":"Kamu pernah belajar bahasa Inggris?","en":"Have you studied English?"},{"zh":"我沒學過日文。","py":"wǒ méi xué guò rì wén","id":"Aku belum pernah belajar bahasa Jepang.","en":"I have never studied Japanese."},{"zh":"我去過那間圖書館。","py":"wǒ qù guò nà jiān tú shū guǎn","id":"Aku pernah pergi ke perpustakaan itu.","en":"I have been to that library."}]},{"title":{"id":"Sebab dan akibat: 因為…所以…","en":"Cause and result: 因為…所以…"},"pattern":"因為 + Sebab，所以 + Akibat","note":{"id":"因為 memperkenalkan sebab, 所以 memperkenalkan akibat. Dalam bahasa Mandarin keduanya sering dipakai bersama dalam satu kalimat, tidak seperti bahasa Indonesia yang biasanya cukup salah satu.","en":"因為 introduces the reason and 所以 the result. In Chinese both are often used together in one sentence, while Indonesian (and English) usually uses only one of them."},"ex":[{"zh":"因為有考試，所以我不出門。","py":"yīn wèi yǒu kǎo shì suǒ yǐ wǒ bù chū mén","id":"Karena ada ujian, aku tidak keluar rumah.","en":"Because there is a test, I am not going out."},{"zh":"因為作業很多，所以我很晚睡。","py":"yīn wèi zuò yè hěn duō suǒ yǐ wǒ hěn wǎn shuì","id":"Karena PR-nya banyak, aku tidur larut.","en":"Because there is a lot of homework, I go to bed late."}]}],"dialog":[{"zh":"下課了！你要去哪裡？","py":"xià kè le nǐ yào qù nǎ lǐ","id":"Pelajaran sudah selesai! Kamu mau ke mana?","en":"Class is over! Where are you going?","sp":"A"},{"zh":"我要去圖書館寫作業。","py":"wǒ yào qù tú shū guǎn xiě zuò yè","id":"Aku mau ke perpustakaan mengerjakan PR.","en":"I'm going to the library to do homework.","sp":"B"},{"zh":"明天不是有期中考嗎？","py":"míng tiān bú shì yǒu qí zhōng kǎo ma","id":"Bukankah besok ada ujian tengah semester?","en":"Isn't there a midterm tomorrow?","sp":"A"},{"zh":"對，我的數學不太好。","py":"duì wǒ de shù xué bú tài hǎo","id":"Iya, matematikaku kurang bagus.","en":"Yes, my math is not so good.","sp":"B"},{"zh":"我們一起念書，好嗎？","py":"wǒ men yì qǐ niàn shū hǎo ma","id":"Kita belajar bareng, mau?","en":"Shall we study together?","sp":"A"},{"zh":"好啊，你可以教我嗎？","py":"hǎo a nǐ kě yǐ jiāo wǒ ma","id":"Boleh, kamu bisa mengajariku?","en":"Sure, can you teach me?","sp":"B"},{"zh":"當然可以！","py":"dāng rán kě yǐ","id":"Tentu bisa!","en":"Of course!","sp":"A"},{"zh":"謝謝你！","py":"xiè xie nǐ","id":"Terima kasih!","en":"Thank you!","sp":"B"}],"n":"12"},{"k":"alam","zh":"天氣自然","py":"tiān qì zì rán","title":{"id":"Cuaca dan alam","en":"Weather & nature","tl":"Panahon at kalikasan","vi":"Thời tiết và thiên nhiên"},"desc":{"id":"Kamu bisa membicarakan cuaca hari ini, musim, dan pemandangan alam di Taiwan.","en":"You can talk about today's weather, the seasons and natural scenery in Taiwan."},"icon":"sun","sets":[{"title":{"id":"Cuaca hari ini","en":"Today's weather"},"words":[{"hz":"天氣","ex":{"zh":"台北的天氣很好。","py":"tái běi de tiān qì hěn hǎo","id":"Cuaca di Taipei bagus.","en":"The weather in Taipei is nice."}},{"hz":"晴天","ex":{"zh":"今天是晴天，很熱。","py":"jīn tiān shì qíng tiān hěn rè","id":"Hari ini cerah dan panas.","en":"Today is sunny and hot."}},{"hz":"陰天","ex":{"zh":"明天是陰天。","py":"míng tiān shì yīn tiān","id":"Besok mendung.","en":"Tomorrow will be cloudy."}},{"hz":"下雨","ex":{"zh":"外面在下雨。","py":"wài miàn zài xià yǔ","id":"Di luar sedang hujan.","en":"It is raining outside."}},{"hz":"雨","ex":{"zh":"雨還沒停。","py":"yǔ hái méi tíng","id":"Hujannya belum berhenti.","en":"The rain hasn't stopped yet."}},{"hz":"大雨","ex":{"zh":"昨天下大雨。","py":"zuó tiān xià dà yǔ","id":"Kemarin hujan deras.","en":"It rained heavily yesterday."}},{"hz":"小雨","ex":{"zh":"今天只有小雨。","py":"jīn tiān zhǐ yǒu xiǎo yǔ","id":"Hari ini hanya gerimis.","en":"There is only light rain today."}},{"hz":"颱風","mw":"個","ex":{"zh":"這個週末有颱風。","py":"zhè ge zhōu mò yǒu tái fēng","id":"Akhir pekan ini ada topan.","en":"A typhoon is coming this weekend."}},{"hz":"打雷","ex":{"zh":"昨天晚上一直打雷。","py":"zuó tiān wǎn shàng yì zhí dǎ léi","id":"Tadi malam petir terus menggelegar.","en":"There was thunder all night last night."}},{"hz":"彩虹","mw":"道","ex":{"zh":"下雨以後有彩虹。","py":"xià yǔ yǐ hòu yǒu cǎi hóng","id":"Setelah hujan ada pelangi.","en":"There is a rainbow after the rain."}}]},{"title":{"id":"Panas, dingin, nyaman","en":"Hot, cold, comfortable"},"words":[{"hz":"熱","ex":{"zh":"夏天很熱。","py":"xià tiān hěn rè","id":"Musim panas itu panas sekali.","en":"Summer is very hot."}},{"hz":"冷","ex":{"zh":"今天好冷。","py":"jīn tiān hǎo lěng","id":"Hari ini dingin sekali.","en":"It is so cold today."}},{"hz":"涼快","ex":{"zh":"山上比較涼快。","py":"shān shàng bǐ jiào liáng kuài","id":"Di gunung lebih sejuk.","en":"It is cooler in the mountains."}},{"hz":"暖和","ex":{"zh":"這件外套很暖和。","py":"zhè jiàn wài tào hěn nuǎn huo","id":"Jaket ini hangat sekali.","en":"This jacket is very warm."}},{"hz":"濕","ex":{"zh":"下雨天，鞋子都濕了。","py":"xià yǔ tiān xié zi dōu shī le","id":"Hari hujan, sepatuku basah semua.","en":"It was a rainy day and my shoes got all wet."}},{"hz":"乾","ex":{"zh":"衣服已經乾了。","py":"yī fu yǐ jīng gān le","id":"Bajunya sudah kering.","en":"The clothes are already dry."}},{"hz":"舒服","ex":{"zh":"今天的天氣很舒服。","py":"jīn tiān de tiān qì hěn shū fu","id":"Cuaca hari ini nyaman.","en":"The weather is comfortable today."}},{"hz":"度","ex":{"zh":"今天最高三十度。","py":"jīn tiān zuì gāo sān shí dù","id":"Hari ini suhu tertinggi 30 derajat.","en":"Today's high is 30 degrees."}},{"hz":"天氣預報","ex":{"zh":"天氣預報說明天會下雨。","py":"tiān qì yù bào shuō míng tiān huì xià yǔ","id":"Prakiraan cuaca bilang besok akan hujan.","en":"The forecast says it will rain tomorrow."}}]},{"title":{"id":"Empat musim","en":"The four seasons"},"words":[{"hz":"春天","ex":{"zh":"春天花很多。","py":"chūn tiān huā hěn duō","id":"Di musim semi bunganya banyak.","en":"There are many flowers in spring."}},{"hz":"夏天","ex":{"zh":"夏天我喜歡吃西瓜。","py":"xià tiān wǒ xǐ huān chī xī guā","id":"Di musim panas aku suka makan semangka.","en":"In summer I like eating watermelon."}},{"hz":"秋天","ex":{"zh":"我最喜歡秋天。","py":"wǒ zuì xǐ huān qiū tiān","id":"Aku paling suka musim gugur.","en":"I like autumn the most."}},{"hz":"冬天","ex":{"zh":"台北的冬天常常下雨。","py":"tái běi de dōng tiān cháng cháng xià yǔ","id":"Musim dingin di Taipei sering hujan.","en":"It often rains in Taipei in winter."}},{"hz":"季節","mw":"個","ex":{"zh":"你最喜歡哪個季節？","py":"nǐ zuì xǐ huān nǎ ge jì jié","id":"Kamu paling suka musim yang mana?","en":"Which season do you like best?"}},{"hz":"風","mw":"陣","ex":{"zh":"今天風很大。","py":"jīn tiān fēng hěn dà","id":"Hari ini anginnya kencang.","en":"The wind is strong today."}},{"hz":"颳風","ex":{"zh":"昨天颳風又下雨。","py":"zuó tiān guā fēng yòu xià yǔ","id":"Kemarin berangin dan hujan.","en":"It was windy and rainy yesterday."}},{"hz":"下雪","ex":{"zh":"台北很少下雪。","py":"tái běi hěn shǎo xià xuě","id":"Di Taipei jarang turun salju.","en":"It rarely snows in Taipei."}},{"hz":"雪","ex":{"zh":"我想看雪。","py":"wǒ xiǎng kàn xuě","id":"Aku ingin melihat salju.","en":"I want to see snow."}}]},{"title":{"id":"Pemandangan alam","en":"Natural scenery"},"words":[{"hz":"太陽","ex":{"zh":"今天太陽很大。","py":"jīn tiān tài yáng hěn dà","id":"Hari ini mataharinya terik.","en":"The sun is strong today."}},{"hz":"月亮","mw":"個","ex":{"zh":"今晚的月亮很美。","py":"jīn wǎn de yuè liàng hěn měi","id":"Bulan malam ini indah sekali.","en":"The moon is beautiful tonight."}},{"hz":"星星","mw":"顆","ex":{"zh":"山上有很多星星。","py":"shān shàng yǒu hěn duō xīng xing","id":"Di gunung ada banyak bintang.","en":"There are many stars in the mountains."}},{"hz":"山","mw":"座","ex":{"zh":"我家後面有一座山。","py":"wǒ jiā hòu miàn yǒu yí zuò shān","id":"Di belakang rumahku ada sebuah gunung.","en":"There is a mountain behind my home."}},{"hz":"海","ex":{"zh":"我想去看海。","py":"wǒ xiǎng qù kàn hǎi","id":"Aku ingin pergi melihat laut.","en":"I want to go see the sea."}},{"hz":"河","mw":"條","ex":{"zh":"這條河很長。","py":"zhè tiáo hé hěn cháng","id":"Sungai ini panjang sekali.","en":"This river is very long."}},{"hz":"湖","mw":"個","ex":{"zh":"日月潭是一個湖。","py":"rì yuè tán shì yí ge hú","id":"Sun Moon Lake adalah sebuah danau.","en":"Sun Moon Lake is a lake."}},{"hz":"樹","mw":"棵","ex":{"zh":"公園裡有很多樹。","py":"gōng yuán lǐ yǒu hěn duō shù","id":"Di taman ada banyak pohon.","en":"There are many trees in the park."}},{"hz":"空氣","ex":{"zh":"山上的空氣很好。","py":"shān shàng de kōng qì hěn hǎo","id":"Udara di gunung segar.","en":"The air in the mountains is good."}}]}],"grammar":[{"title":{"id":"Menggambarkan cuaca: 很 / 不太 / 太…了 + kata sifat","en":"Describing weather with adjectives"},"pattern":"天氣 / 時間 + 很 / 不太 + Adj；太 + Adj + 了","note":{"id":"Kata sifat bahasa Mandarin langsung dipakai sebagai predikat, jadi jangan tambahkan 是 (bukan 今天是熱). 很 hanya berarti 'sangat' kalau diberi tekanan; biasanya hanya penghubung. 不太 = 'tidak terlalu', 太…了 = 'terlalu/sekali'.","en":"Adjectives work as predicates by themselves, so do not add 是 (not 今天是熱). 很 is usually just a linker, not a strong 'very'. 不太 means 'not too', and 太…了 means 'too / so'."},"ex":[{"zh":"今天很熱。","py":"jīn tiān hěn rè","id":"Hari ini panas.","en":"It is hot today."},{"zh":"山上不太冷。","py":"shān shàng bú tài lěng","id":"Di gunung tidak terlalu dingin.","en":"It is not too cold in the mountains."},{"zh":"今天太熱了！","py":"jīn tiān tài rè le","id":"Hari ini panas sekali!","en":"It is so hot today!"}]},{"title":{"id":"Membandingkan: A 比 B + kata sifat","en":"Comparing with 比"},"pattern":"A + 比 + B + Adj","note":{"id":"Untuk membandingkan, pakai 比 dan taruh kata sifat langsung di belakang B. Jangan pakai 很 di depan kata sifat (bukan 比 B 很熱). Untuk negatif pakai 不比 atau 沒有.","en":"Use 比 and put the adjective right after B. Do not add 很 before the adjective (not 比 B 很熱). For the negative use 沒有."},"ex":[{"zh":"高雄比台北熱。","py":"gāo xióng bǐ tái běi rè","id":"Kaohsiung lebih panas daripada Taipei.","en":"Kaohsiung is hotter than Taipei."},{"zh":"今天比昨天涼快。","py":"jīn tiān bǐ zuó tiān liáng kuài","id":"Hari ini lebih sejuk daripada kemarin.","en":"Today is cooler than yesterday."}]},{"title":{"id":"Prakiraan dengan 會: akan terjadi","en":"Predicting with 會"},"pattern":"S + 會 + V / Adj；不會 + V","note":{"id":"會 di sini berarti 'akan / kemungkinan akan'. Dipakai untuk ramalan cuaca. Bentuk negatifnya 不會, dan pertanyaan ya/tidak memakai 嗎 atau 會不會.","en":"Here 會 means 'will / is likely to'. It is common in forecasts. The negative is 不會, and questions use 嗎 or 會不會."},"ex":[{"zh":"明天會下雨。","py":"míng tiān huì xià yǔ","id":"Besok akan hujan.","en":"It will rain tomorrow."},{"zh":"明天會颳風嗎？","py":"míng tiān huì guā fēng ma","id":"Apakah besok akan berangin?","en":"Will it be windy tomorrow?"},{"zh":"晚上不會很冷。","py":"wǎn shàng bú huì hěn lěng","id":"Malam ini tidak akan terlalu dingin.","en":"It won't be very cold tonight."}]},{"title":{"id":"Fenomena cuaca: 下 + hujan/salju, 在下雨","en":"Weather verbs with 下"},"pattern":"下 + 雨 / 雪；在 + 下雨","note":{"id":"Hujan dan salju memakai kata kerja 下 (turun): 下雨, 下雪, 下大雨. Untuk 'sedang hujan' pakai 在下雨. Angin memakai 颳風 dan petir memakai 打雷. Tidak perlu subjek seperti 'langit' atau 'cuaca'.","en":"Rain and snow use the verb 下: 下雨, 下雪, 下大雨. Use 在下雨 for 'it is raining now'. Wind uses 颳風 and thunder uses 打雷. No subject like 'sky' is needed."},"ex":[{"zh":"外面在下雨。","py":"wài miàn zài xià yǔ","id":"Di luar sedang hujan.","en":"It is raining outside."},{"zh":"昨天下大雨。","py":"zuó tiān xià dà yǔ","id":"Kemarin hujan deras.","en":"It rained heavily yesterday."},{"zh":"冬天山上會下雪。","py":"dōng tiān shān shàng huì xià xuě","id":"Kalau musim dingin, di gunung turun salju.","en":"It snows in the mountains in winter."}]}],"dialog":[{"sp":"A","zh":"外面在下雨嗎？","py":"wài miàn zài xià yǔ ma","id":"Di luar sedang hujan, ya?","en":"Is it raining outside?"},{"sp":"B","zh":"對，雨很大，颱風要來了。","py":"duì yǔ hěn dà tái fēng yào lái le","id":"Iya, hujannya deras. Topan mau datang.","en":"Yes, it's pouring. A typhoon is coming."},{"sp":"A","zh":"天氣預報怎麼說？","py":"tiān qì yù bào zěn me shuō","id":"Prakiraan cuaca bilang apa?","en":"What does the forecast say?"},{"sp":"B","zh":"明天還會下雨，也會颳大風。","py":"míng tiān hái huì xià yǔ yě huì guā dà fēng","id":"Besok masih akan hujan, dan anginnya kencang.","en":"It will still rain tomorrow, and it'll be very windy."},{"sp":"A","zh":"那我們不去海邊了。","py":"nà wǒ men bú qù hǎi biān le","id":"Kalau begitu kita tidak jadi ke pantai.","en":"Then we won't go to the beach."},{"sp":"B","zh":"好，下次天氣好再去。","py":"hǎo xià cì tiān qì hǎo zài qù","id":"Oke, lain kali kalau cuacanya bagus baru pergi.","en":"OK, let's go next time when the weather is good."},{"sp":"A","zh":"出門要帶雨傘和外套。","py":"chū mén yào dài yǔ sǎn hé wài tào","id":"Kalau keluar rumah bawa payung dan jaket.","en":"Take an umbrella and a jacket when you go out."},{"sp":"B","zh":"好，我知道了。","py":"hǎo wǒ zhī dào le","id":"Oke, siap.","en":"OK, got it."}],"n":"13"},{"k":"hewan","zh":"動物植物","py":"dòng wù zhí wù","title":{"id":"Hewan dan tumbuhan","en":"Animals & plants","tl":"Mga hayop at halaman","vi":"Động vật và thực vật"},"desc":{"id":"Kamu bisa menyebut hewan dan tumbuhan umum, menghitungnya dengan kata satuan, dan bercerita tentang hewan peliharaan.","en":"You can name common animals and plants, count them with measure words and talk about pets."},"icon":"paw","sets":[{"title":{"id":"Hewan peliharaan","en":"Pets and small animals"},"words":[{"hz":"動物","mw":"隻","ex":{"zh":"我很喜歡動物。","py":"wǒ hěn xǐ huān dòng wù","id":"Aku suka sekali hewan.","en":"I like animals very much."}},{"hz":"狗","mw":"隻","ex":{"zh":"我家有一隻狗。","py":"wǒ jiā yǒu yì zhī gǒu","id":"Di rumahku ada seekor anjing.","en":"We have a dog at home."}},{"hz":"貓","mw":"隻","ex":{"zh":"那隻貓很可愛。","py":"nà zhī māo hěn kě ài","id":"Kucing itu lucu sekali.","en":"That cat is very cute."}},{"hz":"小狗","mw":"隻","ex":{"zh":"這隻小狗才兩個月。","py":"zhè zhī xiǎo gǒu cái liǎng ge yuè","id":"Anak anjing ini baru dua bulan.","en":"This puppy is only two months old."}},{"hz":"小貓","mw":"隻","ex":{"zh":"小貓在睡覺。","py":"xiǎo māo zài shuì jiào","id":"Anak kucing sedang tidur.","en":"The kitten is sleeping."}},{"hz":"鳥","mw":"隻","ex":{"zh":"樹上有一隻鳥。","py":"shù shàng yǒu yì zhī niǎo","id":"Di atas pohon ada seekor burung.","en":"There is a bird in the tree."}},{"hz":"小鳥","mw":"隻","ex":{"zh":"小鳥在唱歌。","py":"xiǎo niǎo zài chàng gē","id":"Burung kecil itu sedang berkicau.","en":"The little bird is singing."}},{"hz":"魚","mw":"條","ex":{"zh":"湖裡有很多魚。","py":"hú lǐ yǒu hěn duō yú","id":"Di danau ada banyak ikan.","en":"There are many fish in the lake."}}]},{"title":{"id":"Hewan lain","en":"Other animals"},"words":[{"hz":"馬","mw":"匹","ex":{"zh":"那匹馬跑得很快。","py":"nà pǐ mǎ pǎo de hěn kuài","id":"Kuda itu larinya cepat sekali.","en":"That horse runs very fast."}},{"hz":"牛","mw":"頭","ex":{"zh":"那頭牛很大。","py":"nà tóu niú hěn dà","id":"Sapi itu besar sekali.","en":"That cow is very big."}},{"hz":"豬","mw":"隻","ex":{"zh":"這隻豬很胖。","py":"zhè zhī zhū hěn pàng","id":"Babi ini gemuk sekali.","en":"This pig is very fat."}},{"hz":"雞","mw":"隻","ex":{"zh":"公雞早上會叫。","py":"gōng jī zǎo shàng huì jiào","id":"Ayam jago berkokok di pagi hari.","en":"Roosters crow in the morning."}},{"hz":"鴨","mw":"隻","ex":{"zh":"河裡有三隻鴨。","py":"hé lǐ yǒu sān zhī yā","id":"Di sungai ada tiga ekor bebek.","en":"There are three ducks in the river."}},{"hz":"熊","mw":"隻","ex":{"zh":"台灣有黑熊。","py":"tái wān yǒu hēi xióng","id":"Di Taiwan ada beruang hitam.","en":"Taiwan has black bears."}},{"hz":"鹿","mw":"隻","ex":{"zh":"山上有幾隻鹿。","py":"shān shàng yǒu jǐ zhī lù","id":"Di gunung ada beberapa ekor rusa.","en":"There are a few deer in the mountains."}},{"hz":"蟲","mw":"隻","ex":{"zh":"夏天有很多蟲。","py":"xià tiān yǒu hěn duō chóng","id":"Di musim panas banyak serangga.","en":"There are many bugs in summer."}},{"hz":"蚊子","ex":{"zh":"房間裡有很多蚊子。","py":"fáng jiān lǐ yǒu hěn duō wén zi","id":"Di kamar ada banyak nyamuk.","en":"There are many mosquitoes in the room."},"mw":"隻"}]},{"title":{"id":"Bunga, rumput, dan buah","en":"Flowers, grass and fruit"},"words":[{"hz":"花","mw":"朵","ex":{"zh":"這朵花很香。","py":"zhè duǒ huā hěn xiāng","id":"Bunga ini harum sekali.","en":"This flower smells lovely."}},{"hz":"草","ex":{"zh":"公園的草很綠。","py":"gōng yuán de cǎo hěn lǜ","id":"Rumput di taman hijau sekali.","en":"The grass in the park is very green."}},{"hz":"樹葉","mw":"片","ex":{"zh":"秋天樹葉會變黃。","py":"qiū tiān shù yè huì biàn huáng","id":"Di musim gugur daun-daun berubah kuning.","en":"Leaves turn yellow in autumn."}},{"hz":"水果","ex":{"zh":"我每天吃水果。","py":"wǒ měi tiān chī shuǐ guǒ","id":"Aku makan buah setiap hari.","en":"I eat fruit every day."}},{"hz":"蘋果","mw":"個","ex":{"zh":"這個蘋果很甜。","py":"zhè ge píng guǒ hěn tián","id":"Apel ini manis sekali.","en":"This apple is very sweet."}},{"hz":"香蕉","mw":"根","ex":{"zh":"我早餐常吃香蕉。","py":"wǒ zǎo cān cháng chī xiāng jiāo","id":"Aku sering makan pisang untuk sarapan.","en":"I often eat a banana for breakfast."}},{"hz":"草莓","mw":"顆","ex":{"zh":"冬天的草莓最好吃。","py":"dōng tiān de cǎo méi zuì hǎo chī","id":"Stroberi musim dingin paling enak.","en":"Winter strawberries taste the best."}},{"hz":"西瓜","mw":"個","ex":{"zh":"西瓜又大又甜。","py":"xī guā yòu dà yòu tián","id":"Semangka itu besar dan manis.","en":"The watermelon is big and sweet."}}]},{"title":{"id":"Sifat dan kegiatan hewan","en":"Describing animals and nature"},"words":[{"hz":"可愛","ex":{"zh":"這隻貓好可愛。","py":"zhè zhī māo hǎo kě ài","id":"Kucing ini lucu sekali.","en":"This cat is so cute."}},{"hz":"怕","ex":{"zh":"我怕蟲。","py":"wǒ pà chóng","id":"Aku takut serangga.","en":"I am afraid of bugs."}},{"hz":"飛","ex":{"zh":"鳥會飛。","py":"niǎo huì fēi","id":"Burung bisa terbang.","en":"Birds can fly."}},{"hz":"跑","ex":{"zh":"小狗跑得很快。","py":"xiǎo gǒu pǎo de hěn kuài","id":"Anak anjing itu larinya cepat.","en":"The puppy runs fast."}},{"hz":"爬","ex":{"zh":"小貓會爬樹。","py":"xiǎo māo huì pá shù","id":"Anak kucing bisa memanjat pohon.","en":"The kitten can climb trees."}},{"hz":"自然","ex":{"zh":"我喜歡大自然。","py":"wǒ xǐ huān dà zì rán","id":"Aku suka alam.","en":"I like nature."}},{"hz":"保護","ex":{"zh":"我們要保護動物。","py":"wǒ men yào bǎo hù dòng wù","id":"Kita harus melindungi hewan.","en":"We should protect animals."}},{"hz":"環境","ex":{"zh":"環境乾淨，動物才健康。","py":"huán jìng gān jìng dòng wù cái jiàn kāng","id":"Hewan baru bisa sehat kalau lingkungannya bersih.","en":"Animals are only healthy in a clean environment."}}]}],"grammar":[{"title":{"id":"Menghitung hewan: Num + kata satuan + hewan","en":"Counting animals with measure words"},"pattern":"Num + 隻 / 條 / 匹 / 頭 + 動物","note":{"id":"Hewan kecil dan sedang (anjing, kucing, burung, ayam) memakai 隻. Ikan memakai 條, kuda 匹, sapi 頭. Untuk angka 2 sebelum kata satuan pakai 兩, bukan 二. Jangan lupa kata satuan: bukan 三貓.","en":"Most animals (dog, cat, bird, chicken) use 隻. Fish use 條, horses 匹, cows 頭. Use 兩, not 二, for 'two' before a measure word. Do not drop the measure word: not 三貓."},"ex":[{"zh":"我有兩隻貓。","py":"wǒ yǒu liǎng zhī māo","id":"Aku punya dua ekor kucing.","en":"I have two cats."},{"zh":"湖裡有三條魚。","py":"hú lǐ yǒu sān tiáo yú","id":"Di danau ada tiga ekor ikan.","en":"There are three fish in the lake."},{"zh":"樹上有一隻鳥。","py":"shù shàng yǒu yì zhī niǎo","id":"Di atas pohon ada seekor burung.","en":"There is a bird in the tree."}]},{"title":{"id":"Ada di suatu tempat: Tempat + 有 + benda","en":"Saying what is in a place with 有"},"pattern":"地方 + 有 / 沒有 + Num + MW + N","note":{"id":"Untuk mengatakan 'di tempat X ada Y', taruh tempat di depan lalu 有. Sebutkan jumlahnya kalau perlu. Negatifnya 沒有, bukan 不有. Kalau sudah tahu bendanya dan ingin menyebut lokasinya, pakai 在: 貓在沙發上.","en":"To say 'there is Y at X', put the place first and then 有. The negative is 沒有, never 不有. If you already know the thing and want to give its location, use 在: 貓在沙發上."},"ex":[{"zh":"公園裡有很多花。","py":"gōng yuán lǐ yǒu hěn duō huā","id":"Di taman ada banyak bunga.","en":"There are lots of flowers in the park."},{"zh":"我家沒有狗。","py":"wǒ jiā méi yǒu gǒu","id":"Di rumahku tidak ada anjing.","en":"We don't have a dog at home."},{"zh":"貓在沙發上。","py":"māo zài shā fā shàng","id":"Kucingnya ada di atas sofa.","en":"The cat is on the sofa."}]},{"title":{"id":"Menjelaskan cara bergerak: V + 得 + kata sifat","en":"Describing how well/fast: V + 得 + Adj"},"pattern":"S + V + 得 + 很 + Adj","note":{"id":"Untuk menjelaskan seberapa cepat atau bagus suatu gerakan, taruh 得 setelah kata kerja lalu kata sifat (biasanya dengan 很). Jangan tulis 很快跑. Bentuk negatifnya V + 得 + 不 + Adj.","en":"To describe how fast or well something is done, put 得 after the verb, then the adjective (usually with 很). Do not say 很快跑. The negative is V + 得 + 不 + Adj."},"ex":[{"zh":"鳥飛得很高。","py":"niǎo fēi de hěn gāo","id":"Burung terbang tinggi sekali.","en":"The bird flies very high."},{"zh":"小狗跑得很快。","py":"xiǎo gǒu pǎo de hěn kuài","id":"Anak anjing itu larinya cepat.","en":"The puppy runs fast."}]},{"title":{"id":"Suka dan takut: 喜歡 / 怕 + benda","en":"Liking and fearing animals"},"pattern":"S + (很) 喜歡 / 怕 + N","note":{"id":"喜歡 dan 怕 langsung diikuti kata benda, tanpa kata depan. Bisa ditambah 很 untuk menekankan. Gunakan 但是 untuk kontras, seperti 'tapi'.","en":"喜歡 and 怕 take a noun directly, with no preposition. You can add 很 to strengthen them. Use 但是 for contrast ('but')."},"ex":[{"zh":"我很怕蟲。","py":"wǒ hěn pà chóng","id":"Aku sangat takut serangga.","en":"I am very afraid of bugs."},{"zh":"她喜歡小貓。","py":"tā xǐ huān xiǎo māo","id":"Dia suka anak kucing.","en":"She likes kittens."},{"zh":"我怕狗，但是喜歡貓。","py":"wǒ pà gǒu dàn shì xǐ huān māo","id":"Aku takut anjing, tapi suka kucing.","en":"I am afraid of dogs, but I like cats."}]}],"dialog":[{"sp":"A","zh":"你家有養狗或貓嗎？","py":"nǐ jiā yǒu yǎng gǒu huò māo ma","id":"Di rumahmu ada pelihara anjing atau kucing?","en":"Do you have a dog or a cat at home?"},{"sp":"B","zh":"我家養了一隻小狗。","py":"wǒ jiā yǎng le yì zhī xiǎo gǒu","id":"Kami pelihara seekor anak anjing.","en":"We have a puppy."},{"sp":"A","zh":"牠幾歲了？","py":"tā jǐ suì le","id":"Umurnya berapa?","en":"How old is it?"},{"sp":"B","zh":"才三個月，牠很可愛。","py":"cái sān ge yuè tā hěn kě ài","id":"Baru tiga bulan, lucu sekali.","en":"Only three months, and it's very cute."},{"sp":"A","zh":"牠喜歡吃什麼？","py":"tā xǐ huān chī shén me","id":"Dia suka makan apa?","en":"What does it like to eat?"},{"sp":"B","zh":"牠喜歡吃雞肉，也喜歡跑。","py":"tā xǐ huān chī jī ròu yě xǐ huān pǎo","id":"Dia suka makan daging ayam dan juga suka berlari.","en":"It likes chicken, and it likes to run too."},{"sp":"A","zh":"下次帶牠來公園玩吧。","py":"xià cì dài tā lái gōng yuán wán ba","id":"Lain kali bawa dia main ke taman, ya.","en":"Bring it to the park next time."},{"sp":"B","zh":"好啊，牠一定很開心。","py":"hǎo a tā yí dìng hěn kāi xīn","id":"Boleh, dia pasti senang sekali.","en":"Sure, it will definitely be happy."}],"n":"14"},{"k":"hobi","zh":"興趣運動","py":"xìng qù yùn dòng","title":{"id":"Hobi dan olahraga","en":"Hobbies & sports","tl":"Libangan at palakasan","vi":"Sở thích và thể thao"},"desc":{"id":"Kamu bisa menceritakan hobi, olahraga, musik, film, dan mengajak teman jalan-jalan di akhir pekan.","en":"You can talk about your hobbies, sports, music and movies, and invite friends out on the weekend."},"icon":"ball","sets":[{"title":{"id":"Hobi santai","en":"Relaxing hobbies"},"words":[{"hz":"興趣","mw":"個","ex":{"zh":"你的興趣是什麼？","py":"nǐ de xìng qù shì shén me","id":"Apa hobimu?","en":"What is your hobby?"}},{"hz":"看書","ex":{"zh":"我週末喜歡在家看書。","py":"wǒ zhōu mò xǐ huān zài jiā kàn shū","id":"Di akhir pekan aku suka membaca buku di rumah.","en":"On weekends I like reading at home."}},{"hz":"畫畫","ex":{"zh":"她很會畫畫。","py":"tā hěn huì huà huà","id":"Dia pandai menggambar.","en":"She is good at drawing."}},{"hz":"唱歌","ex":{"zh":"我們晚上去唱歌吧。","py":"wǒ men wǎn shàng qù chàng gē ba","id":"Ayo kita pergi karaoke malam ini.","en":"Let's go sing tonight."}},{"hz":"跳舞","ex":{"zh":"她每個星期都去跳舞。","py":"tā měi ge xīng qí dōu qù tiào wǔ","id":"Dia pergi menari setiap minggu.","en":"She goes dancing every week."}},{"hz":"拍照","ex":{"zh":"這裡可以拍照嗎？","py":"zhè lǐ kě yǐ pāi zhào ma","id":"Boleh memotret di sini?","en":"Can I take photos here?"}},{"hz":"彈琴","ex":{"zh":"他在房間彈琴。","py":"tā zài fáng jiān tán qín","id":"Dia bermain piano di kamar.","en":"He is playing the piano in his room."}},{"hz":"吉他","mw":"把","ex":{"zh":"我想學彈吉他。","py":"wǒ xiǎng xué tán jí tā","id":"Aku ingin belajar main gitar.","en":"I want to learn to play the guitar."}},{"hz":"散步","ex":{"zh":"晚上我常去河邊散步。","py":"wǎn shàng wǒ cháng qù hé biān sàn bù","id":"Malam hari aku sering jalan santai di tepi sungai.","en":"In the evening I often take a walk by the river."}}]},{"title":{"id":"Olahraga","en":"Sports"},"words":[{"hz":"運動","ex":{"zh":"我每天早上運動。","py":"wǒ měi tiān zǎo shàng yùn dòng","id":"Aku berolahraga setiap pagi.","en":"I exercise every morning."}},{"hz":"籃球","mw":"顆","ex":{"zh":"我哥哥籃球打得很好。","py":"wǒ gē ge lán qiú dǎ de hěn hǎo","id":"Kakakku jago main basket.","en":"My older brother plays basketball very well."}},{"hz":"棒球","ex":{"zh":"台灣人很愛棒球。","py":"tái wān rén hěn ài bàng qiú","id":"Orang Taiwan sangat suka bisbol.","en":"Taiwanese people love baseball."}},{"hz":"足球","ex":{"zh":"他們在踢足球。","py":"tā men zài tī zú qiú","id":"Mereka sedang bermain sepak bola.","en":"They are playing soccer."}},{"hz":"羽毛球","ex":{"zh":"我們下午打羽毛球。","py":"wǒ men xià wǔ dǎ yǔ máo qiú","id":"Sore ini kami main bulu tangkis.","en":"We are playing badminton this afternoon."}},{"hz":"網球","ex":{"zh":"她網球打得不錯。","py":"tā wǎng qiú dǎ de bú cuò","id":"Dia cukup bagus main tenis.","en":"She plays tennis quite well."}},{"hz":"游泳","ex":{"zh":"夏天我常去游泳。","py":"xià tiān wǒ cháng qù yóu yǒng","id":"Di musim panas aku sering pergi berenang.","en":"In summer I often go swimming."}},{"hz":"爬山","ex":{"zh":"週末我們去爬山。","py":"zhōu mò wǒ men qù pá shān","id":"Akhir pekan kami pergi mendaki gunung.","en":"We are going hiking this weekend."}},{"hz":"打球","ex":{"zh":"下課以後去打球吧。","py":"xià kè yǐ hòu qù dǎ qiú ba","id":"Setelah kelas ayo main bola.","en":"Let's play ball after class."}},{"hz":"騎腳踏車","ex":{"zh":"我騎腳踏車去學校。","py":"wǒ qí jiǎo tà chē qù xué xiào","id":"Aku naik sepeda ke sekolah.","en":"I ride my bike to school."}}]},{"title":{"id":"Musik, film, dan game","en":"Music, movies and games"},"words":[{"hz":"音樂","ex":{"zh":"我喜歡聽音樂。","py":"wǒ xǐ huān tīng yīn yuè","id":"Aku suka mendengarkan musik.","en":"I like listening to music."}},{"hz":"歌","mw":"首","ex":{"zh":"這首歌很好聽。","py":"zhè shǒu gē hěn hǎo tīng","id":"Lagu ini enak didengar.","en":"This song sounds great."}},{"hz":"電影","mw":"部","ex":{"zh":"這部電影很有趣。","py":"zhè bù diàn yǐng hěn yǒu qù","id":"Film ini menarik sekali.","en":"This movie is very interesting."}},{"hz":"看電影","ex":{"zh":"週末我想跟朋友看電影。","py":"zhōu mò wǒ xiǎng gēn péng yǒu kàn diàn yǐng","id":"Akhir pekan aku ingin nonton film dengan teman.","en":"This weekend I want to watch a movie with friends."}},{"hz":"電影院","mw":"間","ex":{"zh":"電影院在捷運站旁邊。","py":"diàn yǐng yuàn zài jié yùn zhàn páng biān","id":"Bioskop ada di sebelah stasiun MRT.","en":"The cinema is next to the MRT station."}},{"hz":"演唱會","mw":"場","ex":{"zh":"我買了演唱會的票。","py":"wǒ mǎi le yǎn chàng huì de piào","id":"Aku sudah membeli tiket konser.","en":"I bought a concert ticket."}},{"hz":"電視","mw":"台","ex":{"zh":"他在客廳看電視。","py":"tā zài kè tīng kàn diàn shì","id":"Dia menonton televisi di ruang tamu.","en":"He is watching TV in the living room."}},{"hz":"遊戲","mw":"個","ex":{"zh":"這個遊戲很好玩。","py":"zhè ge yóu xì hěn hǎo wán","id":"Game ini seru sekali.","en":"This game is really fun."}},{"hz":"玩遊戲","ex":{"zh":"弟弟在房間玩遊戲。","py":"dì di zài fáng jiān wán yóu xì","id":"Adikku bermain game di kamar.","en":"My younger brother is playing games in his room."}},{"hz":"票","mw":"張","ex":{"zh":"這張票五百元。","py":"zhè zhāng piào wǔ bǎi yuán","id":"Tiket ini harganya 500 dolar.","en":"This ticket costs 500 dollars."}}]},{"title":{"id":"Keluar bersama teman","en":"Going out"},"words":[{"hz":"逛街","ex":{"zh":"我跟朋友去逛街。","py":"wǒ gēn péng yǒu qù guàng jiē","id":"Aku pergi jalan-jalan belanja dengan teman.","en":"I am going shopping with a friend."}},{"hz":"夜市","mw":"個","ex":{"zh":"星期五晚上我們去夜市。","py":"xīng qí wǔ wǎn shàng wǒ men qù yè shì","id":"Jumat malam kami pergi ke pasar malam.","en":"On Friday night we are going to the night market."}},{"hz":"約會","ex":{"zh":"他們明天有約會。","py":"tā men míng tiān yǒu yuē huì","id":"Besok mereka ada kencan.","en":"They have a date tomorrow."}},{"hz":"週末","ex":{"zh":"週末我不用上課。","py":"zhōu mò wǒ bú yòng shàng kè","id":"Akhir pekan aku tidak perlu masuk kelas.","en":"I don't have class on weekends."}},{"hz":"假日","ex":{"zh":"假日的捷運人很多。","py":"jià rì de jié yùn rén hěn duō","id":"Di hari libur MRT ramai sekali.","en":"The MRT is crowded on holidays."}},{"hz":"有空","ex":{"zh":"你明天有空嗎？","py":"nǐ míng tiān yǒu kòng ma","id":"Apa kamu ada waktu besok?","en":"Are you free tomorrow?"}},{"hz":"好玩","ex":{"zh":"這個地方很好玩。","py":"zhè ge dì fāng hěn hǎo wán","id":"Tempat ini seru sekali.","en":"This place is really fun."}},{"hz":"無聊","ex":{"zh":"在家很無聊。","py":"zài jiā hěn wú liáo","id":"Di rumah membosankan.","en":"Staying at home is boring."}},{"hz":"比賽","mw":"場","ex":{"zh":"明天有籃球比賽。","py":"míng tiān yǒu lán qiú bǐ sài","id":"Besok ada pertandingan basket.","en":"There is a basketball game tomorrow."}},{"hz":"加油","ex":{"zh":"加油！你一定可以。","py":"jiā yóu nǐ yí dìng kě yǐ","id":"Semangat! Kamu pasti bisa.","en":"Go for it! You can definitely do it."}}]}],"grammar":[{"title":{"id":"Menyatakan hobi: 喜歡 + kata kerja","en":"Talking about hobbies with 喜歡"},"pattern":"S + (很) 喜歡 + V (+ O)","note":{"id":"喜歡 bisa langsung diikuti kata kerja tanpa kata penghubung: 我喜歡聽音樂. Untuk bertanya hobi, pakai 你喜歡什麼運動？ atau 你的興趣是什麼？ Jangan tambahkan 是 sebelum kata kerja.","en":"喜歡 can be followed directly by a verb: 我喜歡聽音樂. To ask about hobbies, say 你喜歡什麼運動？ or 你的興趣是什麼？ Do not add 是 before the verb."},"ex":[{"zh":"我喜歡聽音樂。","py":"wǒ xǐ huān tīng yīn yuè","id":"Aku suka mendengarkan musik.","en":"I like listening to music."},{"zh":"她很喜歡爬山。","py":"tā hěn xǐ huān pá shān","id":"Dia sangat suka mendaki gunung.","en":"She really likes hiking."},{"zh":"你喜歡什麼運動？","py":"nǐ xǐ huān shén me yùn dòng","id":"Kamu suka olahraga apa?","en":"What sports do you like?"}]},{"title":{"id":"Kata kerja olahraga: 打 / 踢 / 騎 / 游","en":"Choosing the right verb for each sport"},"pattern":"打 + 籃球 / 棒球 / 網球；踢 + 足球","note":{"id":"Di bahasa Mandarin tiap olahraga punya kata kerja sendiri: 打 untuk bola yang dipukul atau dilempar (籃球, 棒球, 網球, 羽毛球), 踢 untuk sepak bola, 騎 untuk sepeda. Berenang cukup 游泳, jangan pakai 打 atau 玩.","en":"Each sport has its own verb: 打 for sports played by hand or racket (basketball, baseball, tennis, badminton), 踢 for soccer, 騎 for cycling. Swimming is just 游泳, never 打 or 玩."},"ex":[{"zh":"我哥哥常打棒球。","py":"wǒ gē ge cháng dǎ bàng qiú","id":"Kakakku sering main bisbol.","en":"My older brother often plays baseball."},{"zh":"我們一起踢足球吧。","py":"wǒ men yì qǐ tī zú qiú ba","id":"Ayo kita main sepak bola bersama.","en":"Let's play soccer together."},{"zh":"她週末去游泳。","py":"tā zhōu mò qù yóu yǒng","id":"Dia berenang di akhir pekan.","en":"She goes swimming on the weekend."}]},{"title":{"id":"Menyatakan kemampuan: 會 / 不會 + kata kerja","en":"Skills with 會"},"pattern":"S + (很) 會 / 不會 + V","note":{"id":"會 berarti 'bisa' karena sudah belajar, misalnya main gitar atau berenang. 很會 berarti 'pandai'. Bentuk negatifnya 不會. Untuk izin pakai 可以, bukan 會.","en":"會 means 'can' because you have learned a skill, like playing guitar or swimming. 很會 means 'be good at'. The negative is 不會. For permission use 可以, not 會."},"ex":[{"zh":"我會彈吉他。","py":"wǒ huì tán jí tā","id":"Aku bisa main gitar.","en":"I can play the guitar."},{"zh":"他不會游泳。","py":"tā bú huì yóu yǒng","id":"Dia tidak bisa berenang.","en":"He can't swim."},{"zh":"你會打網球嗎？","py":"nǐ huì dǎ wǎng qiú ma","id":"Kamu bisa main tenis?","en":"Can you play tennis?"}]},{"title":{"id":"Mengajak teman: …吧 / 你有空嗎 / 要不要","en":"Inviting friends"},"pattern":"我們 + V + 吧；你要不要 + V？","note":{"id":"Tambahkan 吧 di akhir kalimat untuk mengajak: 我們去夜市吧. Untuk bertanya pendapat pakai 要不要 + kata kerja. Sebelum mengajak, orang Taiwan sering bertanya dulu 你有空嗎？ Jawaban sopan: 好啊 atau 不好意思，我沒空.","en":"Add 吧 at the end to suggest something: 我們去夜市吧. To ask if someone wants to, use 要不要 + verb. Before inviting, people in Taiwan often ask 你有空嗎？ Polite answers: 好啊 or 不好意思，我沒空."},"ex":[{"zh":"我們去夜市吧。","py":"wǒ men qù yè shì ba","id":"Ayo kita ke pasar malam.","en":"Let's go to the night market."},{"zh":"你要不要一起去？","py":"nǐ yào bu yào yì qǐ qù","id":"Kamu mau ikut?","en":"Do you want to go together?"},{"zh":"這個週末你有空嗎？","py":"zhè ge zhōu mò nǐ yǒu kòng ma","id":"Akhir pekan ini kamu ada waktu?","en":"Are you free this weekend?"}]}],"dialog":[{"sp":"A","zh":"這個週末你有空嗎？","py":"zhè ge zhōu mò nǐ yǒu kòng ma","id":"Akhir pekan ini kamu ada waktu?","en":"Are you free this weekend?"},{"sp":"B","zh":"有啊，怎麼了？","py":"yǒu a zěn me le","id":"Ada, kenapa?","en":"Yes, why?"},{"sp":"A","zh":"我有兩張電影票，一起去看電影吧。","py":"wǒ yǒu liǎng zhāng diàn yǐng piào yì qǐ qù kàn diàn yǐng ba","id":"Aku punya dua tiket film, ayo nonton bersama.","en":"I have two movie tickets. Let's go see a movie."},{"sp":"B","zh":"好啊！是什麼電影？","py":"hǎo a shì shén me diàn yǐng","id":"Boleh! Filmnya apa?","en":"Sure! What movie is it?"},{"sp":"A","zh":"是一部籃球電影，聽說很有趣。","py":"shì yí bù lán qiú diàn yǐng tīng shuō hěn yǒu qù","id":"Film tentang basket, katanya menarik.","en":"It's a basketball movie. I heard it's interesting."},{"sp":"B","zh":"太好了，我最喜歡運動電影。","py":"tài hǎo le wǒ zuì xǐ huān yùn dòng diàn yǐng","id":"Bagus sekali, aku paling suka film olahraga.","en":"Great, I like sports movies the most."},{"sp":"A","zh":"看完電影我們去夜市吧。","py":"kàn wán diàn yǐng wǒ men qù yè shì ba","id":"Setelah nonton ayo kita ke pasar malam.","en":"After the movie, let's go to the night market."},{"sp":"B","zh":"好，我請你吃東西。","py":"hǎo wǒ qǐng nǐ chī dōng xi","id":"Oke, aku traktir kamu makan.","en":"OK, I'll treat you to some food."}],"n":"15"},{"k":"rasa","zh":"感覺個性","py":"gǎn jué gè xìng","title":{"id":"Perasaan dan kepribadian","en":"Feelings and personality","tl":"Damdamin at personalidad","vi":"Cảm xúc và tính cách"},"desc":{"id":"Kamu bisa menyatakan perasaan, kondisi tubuh (capek, lapar, haus), dan menggambarkan sifat orang.","en":"You can talk about your feelings, how your body feels (tired, hungry, thirsty) and describe people's personalities."},"icon":"heart","sets":[{"title":{"id":"Perasaan dan suasana hati","en":"Feelings and moods"},"words":[{"hz":"高興","ex":{"zh":"今天見到你，我很高興。","py":"jīn tiān jiàn dào nǐ wǒ hěn gāo xìng","id":"Aku senang sekali bisa bertemu kamu hari ini.","en":"I'm happy to meet you today."}},{"hz":"快樂","ex":{"zh":"祝你生日快樂！","py":"zhù nǐ shēng rì kuài lè","id":"Selamat ulang tahun!","en":"Happy birthday!"}},{"hz":"開心","ex":{"zh":"我今天很開心。","py":"wǒ jīn tiān hěn kāi xīn","id":"Hari ini aku senang sekali.","en":"I'm very happy today."}},{"hz":"難過","ex":{"zh":"他沒考好，很難過。","py":"tā méi kǎo hǎo hěn nán guò","id":"Ujiannya kurang bagus, jadi dia sedih.","en":"He didn't do well on the test and is sad."}},{"hz":"傷心","ex":{"zh":"她看了電影，哭得很傷心。","py":"tā kàn le diàn yǐng kū de hěn shāng xīn","id":"Setelah menonton film itu, dia menangis tersedu-sedu.","en":"She cried her heart out after watching the movie."}},{"hz":"生氣","ex":{"zh":"你別生氣，我不是故意的。","py":"nǐ bié shēng qì wǒ bú shì gù yì de","id":"Jangan marah, aku tidak sengaja.","en":"Don't be angry, I didn't do it on purpose."}},{"hz":"緊張","ex":{"zh":"明天考試，我有一點緊張。","py":"míng tiān kǎo shì wǒ yǒu yì diǎn jǐn zhāng","id":"Besok ujian, aku agak gugup.","en":"I have an exam tomorrow and I'm a bit nervous."}},{"hz":"擔心","ex":{"zh":"別擔心，我會幫你。","py":"bié dān xīn wǒ huì bāng nǐ","id":"Jangan khawatir, aku akan membantumu.","en":"Don't worry, I'll help you."}},{"hz":"無聊","ex":{"zh":"在家很無聊，我們出去玩吧。","py":"zài jiā hěn wú liáo wǒ men chū qù wán ba","id":"Di rumah membosankan, ayo kita keluar bermain.","en":"It's boring at home, let's go out."}}]},{"title":{"id":"Kondisi tubuh","en":"How the body feels"},"words":[{"hz":"累","ex":{"zh":"我今天走了很多路，好累。","py":"wǒ jīn tiān zǒu le hěn duō lù hǎo lèi","id":"Hari ini aku banyak berjalan, capek sekali.","en":"I walked a lot today, I'm so tired."}},{"hz":"餓","ex":{"zh":"我早上沒吃飯，現在很餓。","py":"wǒ zǎo shàng méi chī fàn xiàn zài hěn è","id":"Tadi pagi aku tidak makan, sekarang lapar sekali.","en":"I didn't eat this morning, so I'm very hungry now."}},{"hz":"渴","ex":{"zh":"天氣很熱，我很渴。","py":"tiān qì hěn rè wǒ hěn kě","id":"Cuacanya panas, aku haus sekali.","en":"It's hot and I'm very thirsty."}},{"hz":"飽","ex":{"zh":"我吃飽了，不吃了。","py":"wǒ chī bǎo le bù chī le","id":"Aku sudah kenyang, tidak makan lagi.","en":"I'm full, I won't eat any more."}},{"hz":"睏","ex":{"zh":"我昨天太晚睡，今天很睏。","py":"wǒ zuó tiān tài wǎn shuì jīn tiān hěn kùn","id":"Kemarin aku tidur terlalu malam, hari ini ngantuk sekali.","en":"I went to bed too late yesterday, so I'm sleepy today."}},{"hz":"痛","ex":{"zh":"我肚子痛，想去看醫生。","py":"wǒ dù zi tòng xiǎng qù kàn yī shēng","id":"Perutku sakit, aku mau ke dokter.","en":"My stomach hurts, I want to see a doctor."}},{"hz":"舒服","ex":{"zh":"這張沙發很舒服。","py":"zhè zhāng shā fā hěn shū fu","id":"Sofa ini nyaman sekali.","en":"This sofa is very comfortable."}},{"hz":"不舒服","ex":{"zh":"我今天不舒服，想請假。","py":"wǒ jīn tiān bù shū fu xiǎng qǐng jià","id":"Hari ini aku tidak enak badan, mau izin.","en":"I don't feel well today and want to take leave."}}]},{"title":{"id":"Suka, takut, dan pikiran","en":"Likes, fears and thoughts"},"words":[{"hz":"喜歡","ex":{"zh":"我喜歡喝珍珠奶茶。","py":"wǒ xǐ huān hē zhēn zhū nǎi chá","id":"Aku suka minum bubble tea.","en":"I like drinking bubble tea."}},{"hz":"愛","ex":{"zh":"我愛我的家人。","py":"wǒ ài wǒ de jiā rén","id":"Aku sayang keluargaku.","en":"I love my family."}},{"hz":"怕","ex":{"zh":"我怕狗，你呢？","py":"wǒ pà gǒu nǐ ne","id":"Aku takut anjing, kamu?","en":"I'm afraid of dogs, how about you?"}},{"hz":"想","ex":{"zh":"我想回家睡覺。","py":"wǒ xiǎng huí jiā shuì jiào","id":"Aku mau pulang dan tidur.","en":"I want to go home and sleep."}},{"hz":"希望","ex":{"zh":"我希望明天不要下雨。","py":"wǒ xī wàng míng tiān bú yào xià yǔ","id":"Aku berharap besok tidak hujan.","en":"I hope it doesn't rain tomorrow."}},{"hz":"覺得","ex":{"zh":"我覺得夜市的東西很好吃。","py":"wǒ jué de yè shì de dōng xi hěn hǎo chī","id":"Menurutku makanan di pasar malam enak.","en":"I think the food at the night market is delicious."}},{"hz":"心情","ex":{"zh":"今天天氣好，我心情也很好。","py":"jīn tiān tiān qì hǎo wǒ xīn qíng yě hěn hǎo","id":"Cuaca hari ini bagus, suasana hatiku juga bagus.","en":"The weather is nice today and my mood is good too."}}]},{"title":{"id":"Sifat dan kepribadian","en":"Personality traits"},"words":[{"hz":"聰明","ex":{"zh":"他很聰明，什麼都學得很快。","py":"tā hěn cōng míng shén me dōu xué de hěn kuài","id":"Dia pintar, belajar apa saja cepat.","en":"He is smart and learns everything fast."}},{"hz":"笨","ex":{"zh":"我真笨，又忘了帶鑰匙。","py":"wǒ zhēn bèn yòu wàng le dài yào shi","id":"Aku bodoh sekali, lupa bawa kunci lagi.","en":"I'm so silly, I forgot my keys again."}},{"hz":"友善","ex":{"zh":"台灣人很友善。","py":"tái wān rén hěn yǒu shàn","id":"Orang Taiwan sangat ramah.","en":"Taiwanese people are very friendly."}},{"hz":"認真","ex":{"zh":"她上課很認真。","py":"tā shàng kè hěn rèn zhēn","id":"Dia serius sekali saat belajar di kelas.","en":"She is very serious in class."}},{"hz":"害羞","ex":{"zh":"他很害羞，不敢說話。","py":"tā hěn hài xiū bù gǎn shuō huà","id":"Dia pemalu, tidak berani bicara.","en":"He is shy and doesn't dare to speak."}},{"hz":"外向","ex":{"zh":"我朋友很外向，喜歡交朋友。","py":"wǒ péng yǒu hěn wài xiàng xǐ huān jiāo péng yǒu","id":"Temanku sangat ekstrovert, suka berteman.","en":"My friend is very outgoing and likes making friends."}},{"hz":"內向","ex":{"zh":"我很內向，不太愛說話。","py":"wǒ hěn nèi xiàng bú tài ài shuō huà","id":"Aku introvert, tidak terlalu suka bicara.","en":"I'm introverted and don't talk much."}},{"hz":"客氣","ex":{"zh":"不要客氣，請坐。","py":"bú yào kè qi qǐng zuò","id":"Jangan sungkan, silakan duduk.","en":"Make yourself at home, please have a seat."}}]}],"grammar":[{"title":{"id":"Menggambarkan perasaan: Subjek + 很 + kata sifat","en":"Describing feelings: S + 很 + Adj"},"pattern":"S + 很 + Adj","note":{"id":"Kata sifat bahasa Mandarin tidak memakai 是. Katakan 我很累, bukan 我是累. Kata 很 di sini sering hanya penghubung dan artinya tidak sekuat 'sangat'. Untuk negatif pakai 不: 我不累.","en":"Adjectives in Chinese don't take 是. Say 我很累, not 我是累. 很 here is often just a linker and is weaker than 'very'. For the negative use 不: 我不累."},"ex":[{"zh":"我很餓。","py":"wǒ hěn è","id":"Aku lapar.","en":"I'm hungry."},{"zh":"他不累。","py":"tā bù lèi","id":"Dia tidak capek.","en":"He is not tired."},{"zh":"她很友善。","py":"tā hěn yǒu shàn","id":"Dia ramah.","en":"She is friendly."}]},{"title":{"id":"Berpendapat dan berharap: 覺得 / 希望 + kalimat","en":"Opinions and hopes: 覺得 / 希望 + clause"},"pattern":"S + 覺得 / 希望 + kalimat","note":{"id":"覺得 berarti 'merasa / menurutku' dan langsung diikuti kalimat, tanpa kata 'bahwa'. 希望 berarti 'berharap' dan juga diikuti kalimat. Kata sifat di dalam kalimat itu biasanya tetap memakai 很: 我覺得他很聰明.","en":"覺得 means 'feel / think' and is followed directly by a clause, with no word for 'that'. 希望 means 'hope' and also takes a clause. Remember that the adjective after it still usually needs 很."},"ex":[{"zh":"我今天覺得很累。","py":"wǒ jīn tiān jué de hěn lèi","id":"Hari ini aku merasa capek.","en":"I feel tired today."},{"zh":"我希望你不要生氣。","py":"wǒ xī wàng nǐ bú yào shēng qì","id":"Aku harap kamu tidak marah.","en":"I hope you won't be angry."},{"zh":"我覺得他很聰明。","py":"wǒ jué de tā hěn cōng míng","id":"Menurutku dia pintar.","en":"I think he is smart."}]},{"title":{"id":"Tingkat perasaan: 太…了 dan 有一點","en":"Degree: 太…了 and 有一點"},"pattern":"太 + Adj + 了 / 有一點 + Adj","note":{"id":"太…了 berarti 'terlalu / sekali' dan sering dipakai untuk mengeluh atau memuji dengan semangat. 有一點 berarti 'agak' dan biasanya dipakai untuk hal yang kurang enak: 有一點累. Cara baca: 有一點 yǒu yì diǎn.","en":"太…了 means 'too / so' and is used for complaints or enthusiastic praise. 有一點 means 'a bit' and mostly goes with unpleasant things: 有一點累. Pronunciation: 有一點 is yǒu yì diǎn."},"ex":[{"zh":"我太累了。","py":"wǒ tài lèi le","id":"Aku capek sekali.","en":"I'm so tired."},{"zh":"他有一點緊張。","py":"tā yǒu yì diǎn jǐn zhāng","id":"Dia agak gugup.","en":"He is a bit nervous."},{"zh":"今天太開心了！","py":"jīn tiān tài kāi xīn le","id":"Hari ini senang sekali!","en":"I'm so happy today!"}]},{"title":{"id":"Suka dan takut: 喜歡 / 怕 / 想 + kata kerja","en":"Likes and fears: 喜歡 / 怕 / 想 + Verb"},"pattern":"S + 喜歡 / 怕 / 想 + V (+ O)","note":{"id":"喜歡, 怕, dan 想 bisa langsung diikuti kata kerja, tanpa 'untuk' atau 'me-'. 想 berarti 'ingin', sedangkan 喜歡 berarti 'suka'. Negatifnya: 不喜歡, 不怕, 不想.","en":"喜歡, 怕 and 想 can be followed directly by a verb, with no linking word. 想 means 'want to' and 喜歡 means 'like to'. Negatives: 不喜歡, 不怕, 不想."},"ex":[{"zh":"我喜歡聽音樂。","py":"wǒ xǐ huān tīng yīn yuè","id":"Aku suka mendengarkan musik.","en":"I like listening to music."},{"zh":"我想睡覺。","py":"wǒ xiǎng shuì jiào","id":"Aku mau tidur.","en":"I want to sleep."},{"zh":"她怕坐飛機。","py":"tā pà zuò fēi jī","id":"Dia takut naik pesawat.","en":"She is afraid of flying."}]}],"dialog":[{"sp":"A","zh":"你怎麼了？看起來很累。","py":"nǐ zěn me le kàn qǐ lái hěn lèi","id":"Kamu kenapa? Kelihatannya capek.","en":"What's wrong? You look tired."},{"sp":"B","zh":"我昨天太晚睡，今天很睏。","py":"wǒ zuó tiān tài wǎn shuì jīn tiān hěn kùn","id":"Kemarin aku tidur terlalu malam, hari ini ngantuk.","en":"I went to bed too late yesterday and I'm sleepy."},{"sp":"A","zh":"你餓不餓？我們去吃牛肉麵吧。","py":"nǐ è bú è wǒ men qù chī niú ròu miàn ba","id":"Kamu lapar tidak? Ayo kita makan mi sapi.","en":"Are you hungry? Let's go eat beef noodles."},{"sp":"B","zh":"好啊，我也很餓。","py":"hǎo a wǒ yě hěn è","id":"Boleh, aku juga lapar.","en":"Sure, I'm hungry too."},{"sp":"A","zh":"吃飽以後，你會覺得舒服一點。","py":"chī bǎo yǐ hòu nǐ huì jué de shū fu yì diǎn","id":"Setelah kenyang, kamu akan merasa lebih nyaman.","en":"After you eat, you'll feel a bit better."},{"sp":"B","zh":"希望是這樣，謝謝你。","py":"xī wàng shì zhè yàng xiè xie nǐ","id":"Semoga begitu, terima kasih.","en":"I hope so, thank you."}],"n":"16"},{"k":"aksi","zh":"日常動作","py":"rì cháng dòng zuò","title":{"id":"Kegiatan sehari-hari","en":"Daily actions","tl":"Mga pang-araw-araw na gawain","vi":"Hoạt động hằng ngày"},"desc":{"id":"Kamu bisa menceritakan kegiatan sehari-hari: bangun, makan, pergi, belajar, belanja, dan bekerja.","en":"You can describe your daily routine: waking up, eating, going places, studying, shopping and working."},"icon":"clock","sets":[{"title":{"id":"Rutinitas pagi dan malam","en":"Morning and evening routine"},"words":[{"hz":"起床","ex":{"zh":"我每天早上七點起床。","py":"wǒ měi tiān zǎo shàng qī diǎn qǐ chuáng","id":"Setiap pagi aku bangun jam tujuh.","en":"I get up at seven every morning."}},{"hz":"洗臉","ex":{"zh":"起床以後，我先洗臉。","py":"qǐ chuáng yǐ hòu wǒ xiān xǐ liǎn","id":"Setelah bangun, aku cuci muka dulu.","en":"After getting up, I wash my face first."}},{"hz":"洗澡","ex":{"zh":"我晚上回家以後洗澡。","py":"wǒ wǎn shàng huí jiā yǐ hòu xǐ zǎo","id":"Malam hari setelah pulang, aku mandi.","en":"I take a shower after I get home in the evening."}},{"hz":"睡覺","ex":{"zh":"我每天晚上十一點睡覺。","py":"wǒ měi tiān wǎn shàng shí yī diǎn shuì jiào","id":"Setiap malam aku tidur jam sebelas.","en":"I go to sleep at eleven every night."}},{"hz":"吃","ex":{"zh":"我早上吃蛋餅。","py":"wǒ zǎo shàng chī dàn bǐng","id":"Pagi hari aku makan dan bing (telur dadar gulung).","en":"I eat an egg crepe in the morning."}},{"hz":"喝","ex":{"zh":"你要喝咖啡還是喝茶？","py":"nǐ yào hē kā fēi hái shì hē chá","id":"Kamu mau minum kopi atau teh?","en":"Do you want coffee or tea?"}},{"hz":"洗衣服","ex":{"zh":"我週末在家洗衣服。","py":"wǒ zhōu mò zài jiā xǐ yī fu","id":"Akhir pekan aku mencuci baju di rumah.","en":"I do laundry at home on weekends."}}]},{"title":{"id":"Pergi dan datang","en":"Going and coming"},"words":[{"hz":"去","ex":{"zh":"我們明天去台北。","py":"wǒ men míng tiān qù tái běi","id":"Besok kita pergi ke Taipei.","en":"We are going to Taipei tomorrow."}},{"hz":"來","ex":{"zh":"你什麼時候來我家？","py":"nǐ shén me shí hòu lái wǒ jiā","id":"Kapan kamu datang ke rumahku?","en":"When are you coming to my place?"}},{"hz":"回家","ex":{"zh":"我六點下班回家。","py":"wǒ liù diǎn xià bān huí jiā","id":"Jam enam aku selesai kerja dan pulang ke rumah.","en":"I finish work at six and go home."}},{"hz":"走路","ex":{"zh":"我走路去捷運站。","py":"wǒ zǒu lù qù jié yùn zhàn","id":"Aku jalan kaki ke stasiun MRT.","en":"I walk to the MRT station."}},{"hz":"開車","ex":{"zh":"爸爸每天開車上班。","py":"bà ba měi tiān kāi chē shàng bān","id":"Ayah setiap hari menyetir mobil ke kantor.","en":"Dad drives to work every day."}},{"hz":"騎","ex":{"zh":"我騎機車去學校。","py":"wǒ qí jī chē qù xué xiào","id":"Aku naik sepeda motor ke sekolah.","en":"I ride a scooter to school."}},{"hz":"搭","ex":{"zh":"我搭捷運去上課。","py":"wǒ dā jié yùn qù shàng kè","id":"Aku naik MRT untuk pergi kuliah.","en":"I take the MRT to class."}},{"hz":"到","ex":{"zh":"我七點半到學校。","py":"wǒ qī diǎn bàn dào xué xiào","id":"Aku sampai di sekolah jam setengah delapan.","en":"I arrive at school at half past seven."}},{"hz":"進","ex":{"zh":"請進，請坐。","py":"qǐng jìn qǐng zuò","id":"Silakan masuk, silakan duduk.","en":"Please come in and have a seat."}}]},{"title":{"id":"Melihat, mendengar, berbicara","en":"Seeing, hearing, speaking"},"words":[{"hz":"看","ex":{"zh":"我喜歡看電影。","py":"wǒ xǐ huān kàn diàn yǐng","id":"Aku suka menonton film.","en":"I like watching movies."}},{"hz":"聽","ex":{"zh":"我在捷運上聽音樂。","py":"wǒ zài jié yùn shàng tīng yīn yuè","id":"Aku mendengarkan musik di MRT.","en":"I listen to music on the MRT."}},{"hz":"說","ex":{"zh":"請你再說一次。","py":"qǐng nǐ zài shuō yí cì","id":"Tolong katakan sekali lagi.","en":"Please say it one more time."}},{"hz":"寫","ex":{"zh":"老師叫我們寫字。","py":"lǎo shī jiào wǒ men xiě zì","id":"Guru menyuruh kami menulis huruf.","en":"The teacher asks us to write characters."}},{"hz":"讀","ex":{"zh":"請大家讀第一課。","py":"qǐng dà jiā dú dì yī kè","id":"Tolong semuanya baca pelajaran pertama.","en":"Everyone, please read Lesson 1."}},{"hz":"問","ex":{"zh":"我可以問你一個問題嗎？","py":"wǒ kě yǐ wèn nǐ yí ge wèn tí ma","id":"Boleh aku tanya satu pertanyaan?","en":"May I ask you a question?"}},{"hz":"答","ex":{"zh":"他很快就答對了。","py":"tā hěn kuài jiù dá duì le","id":"Dia cepat sekali menjawab dengan benar.","en":"He answered correctly very quickly."}},{"hz":"打電話","ex":{"zh":"我晚上打電話給媽媽。","py":"wǒ wǎn shàng dǎ diàn huà gěi mā ma","id":"Malam hari aku menelepon ibu.","en":"I call my mom in the evening."}},{"hz":"上網","ex":{"zh":"我常常上網買東西。","py":"wǒ cháng cháng shàng wǎng mǎi dōng xi","id":"Aku sering belanja lewat internet.","en":"I often shop online."}}]},{"title":{"id":"Membeli, memberi, mencari","en":"Buying, giving, looking for"},"words":[{"hz":"買","ex":{"zh":"我去便利商店買水。","py":"wǒ qù biàn lì shāng diàn mǎi shuǐ","id":"Aku pergi ke minimarket untuk membeli air.","en":"I go to the convenience store to buy water."}},{"hz":"賣","ex":{"zh":"這家店賣很多種茶。","py":"zhè jiā diàn mài hěn duō zhǒng chá","id":"Toko ini menjual banyak jenis teh.","en":"This shop sells many kinds of tea."}},{"hz":"給","ex":{"zh":"請給我一杯咖啡。","py":"qǐng gěi wǒ yì bēi kā fēi","id":"Tolong beri saya secangkir kopi.","en":"Please give me a cup of coffee."}},{"hz":"拿","ex":{"zh":"請你幫我拿一下。","py":"qǐng nǐ bāng wǒ ná yí xià","id":"Tolong pegangkan sebentar untukku.","en":"Please hold this for me for a moment."}},{"hz":"找","ex":{"zh":"我在找我的手機。","py":"wǒ zài zhǎo wǒ de shǒu jī","id":"Aku sedang mencari ponselku.","en":"I'm looking for my phone."}},{"hz":"等","ex":{"zh":"請等一下，我馬上來。","py":"qǐng děng yí xià wǒ mǎ shàng lái","id":"Tunggu sebentar, aku segera datang.","en":"Please wait a moment, I'll be right there."}},{"hz":"穿","ex":{"zh":"今天很冷，要穿外套。","py":"jīn tiān hěn lěng yào chuān wài tào","id":"Hari ini dingin, harus pakai jaket.","en":"It's cold today, you need to wear a jacket."}}]},{"title":{"id":"Kerja, belajar, santai","en":"Work, study and rest"},"words":[{"hz":"上班","ex":{"zh":"我每天九點上班。","py":"wǒ měi tiān jiǔ diǎn shàng bān","id":"Setiap hari aku mulai kerja jam sembilan.","en":"I start work at nine every day."}},{"hz":"下班","ex":{"zh":"下班以後我們去吃飯。","py":"xià bān yǐ hòu wǒ men qù chī fàn","id":"Setelah pulang kerja kita pergi makan.","en":"Let's go eat after work."}},{"hz":"上課","ex":{"zh":"我們八點上課。","py":"wǒ men bā diǎn shàng kè","id":"Kami masuk kelas jam delapan.","en":"Our class starts at eight."}},{"hz":"休息","ex":{"zh":"你累了，休息一下吧。","py":"nǐ lèi le xiū xí yí xià ba","id":"Kamu capek, istirahat sebentar ya.","en":"You're tired, take a short rest."}},{"hz":"玩","ex":{"zh":"週末我們去墾丁玩。","py":"zhōu mò wǒ men qù kěn dīng wán","id":"Akhir pekan ini kami jalan-jalan ke Kenting.","en":"We are going to Kenting for fun this weekend."}}]}],"grammar":[{"title":{"id":"Pergi untuk melakukan sesuatu: 去 / 來 + tempat + kata kerja","en":"Going somewhere to do something"},"pattern":"S + 去 / 來 + Tempat + V (+ O)","note":{"id":"Dalam bahasa Mandarin, urutan kegiatannya sesuai urutan kejadian: pergi dulu, baru melakukan sesuatu. Tidak perlu kata 'untuk'. Contoh: 我去便利商店買水 (aku pergi ke minimarket, beli air).","en":"Chinese puts the actions in the order they happen: go first, then do something. No word for 'in order to' is needed. Example: 我去便利商店買水."},"ex":[{"zh":"我去夜市吃東西。","py":"wǒ qù yè shì chī dōng xi","id":"Aku pergi ke pasar malam untuk makan.","en":"I go to the night market to eat."},{"zh":"他來我家玩。","py":"tā lái wǒ jiā wán","id":"Dia datang ke rumahku untuk bermain.","en":"He comes to my house to hang out."},{"zh":"我們去學校上課。","py":"wǒ men qù xué xiào shàng kè","id":"Kami pergi ke sekolah untuk belajar.","en":"We go to school for class."}]},{"title":{"id":"Sedang melakukan sesuatu: 在 + kata kerja","en":"Doing something right now: 在 + Verb"},"pattern":"S + 在 + V (+ O)","note":{"id":"在 di depan kata kerja menunjukkan tindakan yang sedang berlangsung, mirip 'sedang'. Jangan campur dengan 在 + tempat (我在家 = aku ada di rumah). Bisa juga memakai 正在 atau menambah 呢 di akhir kalimat, tetapi 在 saja sudah cukup.","en":"在 before a verb shows an action in progress, like 'be ...ing'. Do not confuse it with 在 + place (我在家 = I am at home). You can also use 正在 or add 呢 at the end, but 在 alone is enough."},"ex":[{"zh":"我在看書。","py":"wǒ zài kàn shū","id":"Aku sedang membaca buku.","en":"I'm reading a book."},{"zh":"他在打電話。","py":"tā zài dǎ diàn huà","id":"Dia sedang menelepon.","en":"He is making a phone call."},{"zh":"媽媽在洗衣服。","py":"mā ma zài xǐ yī fu","id":"Ibu sedang mencuci baju.","en":"Mom is doing laundry."}]},{"title":{"id":"Sebentar saja: kata kerja + 一下","en":"A short action: Verb + 一下"},"pattern":"V + 一下","note":{"id":"一下 ditaruh setelah kata kerja agar permintaan terdengar ringan dan sopan, artinya 'sebentar / sedikit'. Sangat sering dipakai bersama 請. Bacaan: yí xià.","en":"一下 after a verb makes an action short and casual, like 'for a moment' or 'just'. Very common with 請 for polite requests. Pronounced yí xià."},"ex":[{"zh":"請等一下。","py":"qǐng děng yí xià","id":"Tunggu sebentar.","en":"Please wait a moment."},{"zh":"我看一下。","py":"wǒ kàn yí xià","id":"Aku lihat sebentar.","en":"Let me take a look."},{"zh":"你休息一下吧。","py":"nǐ xiū xí yí xià ba","id":"Istirahatlah sebentar.","en":"Take a little rest."}]},{"title":{"id":"Urutan kegiatan: 先…再… / …以後","en":"Order of actions: 先…再… / …以後"},"pattern":"先 V1，再 V2 / V1 以後 V2","note":{"id":"先 berarti 'dulu' dan 再 berarti 'lalu / baru'. Pola ini dipakai untuk menceritakan urutan kegiatan. 以後 ditaruh setelah kegiatan pertama: 下班以後 (setelah pulang kerja).","en":"先 means 'first' and 再 means 'then'. Use them to tell the order of actions. 以後 comes after the first action: 下班以後 (after work)."},"ex":[{"zh":"我先洗澡，再睡覺。","py":"wǒ xiān xǐ zǎo zài shuì jiào","id":"Aku mandi dulu, lalu tidur.","en":"I take a shower first, then go to bed."},{"zh":"下課以後我去買東西。","py":"xià kè yǐ hòu wǒ qù mǎi dōng xi","id":"Setelah kelas selesai aku pergi belanja.","en":"After class I go shopping."},{"zh":"你先寫，我再看。","py":"nǐ xiān xiě wǒ zài kàn","id":"Kamu tulis dulu, nanti aku lihat.","en":"You write first, then I'll look."}]}],"dialog":[{"sp":"A","zh":"你明天要做什麼？","py":"nǐ míng tiān yào zuò shén me","id":"Besok kamu mau ngapain?","en":"What are you doing tomorrow?"},{"sp":"B","zh":"早上有課，下課以後去買東西。","py":"zǎo shàng yǒu kè xià kè yǐ hòu qù mǎi dōng xi","id":"Pagi ada kelas, setelah kelas aku pergi belanja.","en":"I have class in the morning and I'll go shopping after."},{"sp":"A","zh":"你怎麼去學校？","py":"nǐ zěn me qù xué xiào","id":"Kamu ke sekolah naik apa?","en":"How do you get to school?"},{"sp":"B","zh":"我騎機車去，你呢？","py":"wǒ qí jī chē qù nǐ ne","id":"Aku naik motor, kamu?","en":"I ride a scooter, how about you?"},{"sp":"A","zh":"我搭捷運，然後走路到學校。","py":"wǒ dā jié yùn rán hòu zǒu lù dào xué xiào","id":"Aku naik MRT, lalu jalan kaki ke sekolah.","en":"I take the MRT and then walk to school."},{"sp":"B","zh":"那我們明天學校見！","py":"nà wǒ men míng tiān xué xiào jiàn","id":"Kalau begitu sampai ketemu besok di sekolah!","en":"Then see you at school tomorrow!"}],"n":"17"},{"k":"sifat","zh":"常用形容詞","py":"cháng yòng xíng róng cí","title":{"id":"Kata sifat umum dan lawannya","en":"Common adjectives and opposites","tl":"Mga karaniwang pang-uri at kasalungat","vi":"Tính từ thông dụng và từ trái nghĩa"},"desc":{"id":"Kamu bisa menggambarkan ukuran, harga, cuaca, rasa, dan kualitas benda dengan pasangan kata sifat yang berlawanan.","en":"You can describe size, price, weather, taste and quality using common pairs of opposite adjectives."},"icon":"question","sets":[{"title":{"id":"Ukuran dan jumlah","en":"Size and amount"},"words":[{"hz":"大","ex":{"zh":"這個房間很大。","py":"zhè ge fáng jiān hěn dà","id":"Kamar ini besar.","en":"This room is big."}},{"hz":"小","ex":{"zh":"我的手機很小。","py":"wǒ de shǒu jī hěn xiǎo","id":"Ponselku kecil.","en":"My phone is small."}},{"hz":"多","ex":{"zh":"夜市的人很多。","py":"yè shì de rén hěn duō","id":"Di pasar malam orangnya banyak.","en":"There are a lot of people at the night market."}},{"hz":"少","ex":{"zh":"今天的作業很少。","py":"jīn tiān de zuò yè hěn shǎo","id":"PR hari ini sedikit.","en":"There is little homework today."}},{"hz":"深","ex":{"zh":"這條河很深，不要游泳。","py":"zhè tiáo hé hěn shēn bú yào yóu yǒng","id":"Sungai ini dalam, jangan berenang.","en":"This river is deep, don't swim."}},{"hz":"淺","ex":{"zh":"這裡的水很淺。","py":"zhè lǐ de shuǐ hěn qiǎn","id":"Air di sini dangkal.","en":"The water here is shallow."}},{"hz":"高","ex":{"zh":"那棟大樓很高。","py":"nà dòng dà lóu hěn gāo","id":"Gedung itu tinggi sekali.","en":"That building is very tall."}},{"hz":"矮","ex":{"zh":"我弟弟比我矮。","py":"wǒ dì di bǐ wǒ ǎi","id":"Adik laki-lakiku lebih pendek dariku.","en":"My younger brother is shorter than me."}},{"hz":"胖","ex":{"zh":"我最近有一點胖。","py":"wǒ zuì jìn yǒu yì diǎn pàng","id":"Belakangan ini aku agak gemuk.","en":"I've gotten a bit chubby lately."}},{"hz":"瘦","ex":{"zh":"她很瘦，吃得不多。","py":"tā hěn shòu chī de bù duō","id":"Dia kurus, makannya tidak banyak.","en":"She is thin and doesn't eat much."}}]},{"title":{"id":"Baru, lama, baik, buruk","en":"New, old, good and bad"},"words":[{"hz":"新","ex":{"zh":"我的手機是新的。","py":"wǒ de shǒu jī shì xīn de","id":"Ponselku baru.","en":"My phone is new."}},{"hz":"舊","ex":{"zh":"這輛機車很舊了。","py":"zhè liàng jī chē hěn jiù le","id":"Motor ini sudah tua.","en":"This scooter is very old."}},{"hz":"好","ex":{"zh":"這家店的服務很好。","py":"zhè jiā diàn de fú wù hěn hǎo","id":"Pelayanan toko ini bagus.","en":"The service at this shop is good."}},{"hz":"壞","ex":{"zh":"電梯壞了。","py":"diàn tī huài le","id":"Liftnya rusak.","en":"The elevator is broken."}},{"hz":"快","ex":{"zh":"高鐵很快。","py":"gāo tiě hěn kuài","id":"Kereta cepat (HSR) sangat cepat.","en":"The high-speed rail is fast."}},{"hz":"慢","ex":{"zh":"請說慢一點。","py":"qǐng shuō màn yì diǎn","id":"Tolong bicara lebih pelan.","en":"Please speak a little slower."}},{"hz":"對","ex":{"zh":"你說得對。","py":"nǐ shuō de duì","id":"Kamu benar.","en":"You are right."}},{"hz":"錯","ex":{"zh":"這個字寫錯了。","py":"zhè ge zì xiě cuò le","id":"Huruf ini salah tulis.","en":"This character is written wrong."}}]},{"title":{"id":"Harga, suhu, jarak, berat","en":"Price, temperature, distance, weight"},"words":[{"hz":"貴","ex":{"zh":"這件衣服太貴了。","py":"zhè jiàn yī fu tài guì le","id":"Baju ini terlalu mahal.","en":"This top is too expensive."}},{"hz":"便宜","ex":{"zh":"夜市的東西很便宜。","py":"yè shì de dōng xi hěn pián yí","id":"Barang di pasar malam murah.","en":"Things at the night market are cheap."}},{"hz":"冷","ex":{"zh":"冬天的台北很冷。","py":"dōng tiān de tái běi hěn lěng","id":"Musim dingin di Taipei dingin sekali.","en":"Taipei is very cold in winter."}},{"hz":"熱","ex":{"zh":"高雄夏天很熱。","py":"gāo xióng xià tiān hěn rè","id":"Musim panas di Kaohsiung panas sekali.","en":"Kaohsiung is very hot in summer."}},{"hz":"遠","ex":{"zh":"我家離學校很遠。","py":"wǒ jiā lí xué xiào hěn yuǎn","id":"Rumahku jauh dari sekolah.","en":"My home is far from school."}},{"hz":"近","ex":{"zh":"捷運站離這裡很近。","py":"jié yùn zhàn lí zhè lǐ hěn jìn","id":"Stasiun MRT dekat dari sini.","en":"The MRT station is close to here."}},{"hz":"重","ex":{"zh":"這個包包很重。","py":"zhè ge bāo bāo hěn zhòng","id":"Tas ini berat.","en":"This bag is heavy."}},{"hz":"輕","ex":{"zh":"這台電腦很輕。","py":"zhè tái diàn nǎo hěn qīng","id":"Komputer ini ringan.","en":"This computer is light."}}]},{"title":{"id":"Mudah, sulit, bersih, sibuk","en":"Easy, hard, clean and busy"},"words":[{"hz":"難","ex":{"zh":"中文的聲調很難。","py":"zhōng wén de shēng diào hěn nán","id":"Nada bahasa Mandarin sulit.","en":"Chinese tones are hard."}},{"hz":"容易","ex":{"zh":"這個問題很容易。","py":"zhè ge wèn tí hěn róng yì","id":"Pertanyaan ini mudah.","en":"This question is easy."}},{"hz":"簡單","ex":{"zh":"這個字很簡單。","py":"zhè ge zì hěn jiǎn dān","id":"Huruf ini sederhana.","en":"This character is simple."}},{"hz":"乾淨","ex":{"zh":"這間廁所很乾淨。","py":"zhè jiān cè suǒ hěn gān jìng","id":"Toilet ini bersih.","en":"This restroom is clean."}},{"hz":"髒","ex":{"zh":"桌子很髒，我來擦。","py":"zhuō zi hěn zāng wǒ lái cā","id":"Mejanya kotor, biar aku lap.","en":"The table is dirty, I'll wipe it."}},{"hz":"忙","ex":{"zh":"我最近很忙。","py":"wǒ zuì jìn hěn máng","id":"Belakangan ini aku sibuk.","en":"I've been busy lately."}}]},{"title":{"id":"Rasa dan penilaian","en":"Taste and evaluation"},"words":[{"hz":"好吃","ex":{"zh":"這家牛肉麵很好吃。","py":"zhè jiā niú ròu miàn hěn hǎo chī","id":"Mi daging sapi di tempat ini enak.","en":"The beef noodles here are delicious."}},{"hz":"好喝","ex":{"zh":"這杯奶茶很好喝。","py":"zhè bēi nǎi chá hěn hǎo hē","id":"Teh susu ini enak diminum.","en":"This milk tea tastes great."}},{"hz":"好看","ex":{"zh":"這部電影很好看。","py":"zhè bù diàn yǐng hěn hǎo kàn","id":"Film ini bagus.","en":"This movie is good."}},{"hz":"好玩","ex":{"zh":"墾丁很好玩。","py":"kěn dīng hěn hǎo wán","id":"Kenting seru sekali.","en":"Kenting is a lot of fun."}},{"hz":"方便","ex":{"zh":"台北的捷運很方便。","py":"tái běi de jié yùn hěn fāng biàn","id":"MRT di Taipei praktis.","en":"The Taipei MRT is very convenient."}},{"hz":"甜","ex":{"zh":"這個蛋糕太甜了。","py":"zhè ge dàn gāo tài tián le","id":"Kue ini terlalu manis.","en":"This cake is too sweet."}},{"hz":"苦","ex":{"zh":"這杯咖啡很苦。","py":"zhè bēi kā fēi hěn kǔ","id":"Kopi ini pahit.","en":"This coffee is bitter."}},{"hz":"辣","ex":{"zh":"這碗麵有一點辣。","py":"zhè wǎn miàn yǒu yì diǎn là","id":"Mi ini agak pedas.","en":"This bowl of noodles is a bit spicy."}},{"hz":"漂亮","ex":{"zh":"這朵花很漂亮。","py":"zhè duǒ huā hěn piào liàng","id":"Bunga ini cantik sekali.","en":"This flower is very pretty."}}]}],"grammar":[{"title":{"id":"Kata sifat sebagai predikat: S + 很 + Adj","en":"Adjective as predicate: S + 很 + Adj"},"pattern":"S + 很 + Adj","note":{"id":"Kata sifat langsung menjadi predikat, tanpa 是 ('adalah'). Kalimat 這個很大 sudah benar, 這個是大 salah. 很 di sini biasanya hanya pelengkap, tidak berarti 'sangat' kecuali ditekankan. Negatif: 不 + Adj.","en":"Adjectives are predicates by themselves and do not need 是. 這個很大 is correct, 這個是大 is wrong. 很 here is usually just a filler and is not strongly 'very' unless stressed. Negative: 不 + Adj."},"ex":[{"zh":"這杯咖啡很貴。","py":"zhè bēi kā fēi hěn guì","id":"Kopi ini mahal.","en":"This coffee is expensive."},{"zh":"我家不大。","py":"wǒ jiā bú dà","id":"Rumahku tidak besar.","en":"My home is not big."},{"zh":"今天很熱。","py":"jīn tiān hěn rè","id":"Hari ini panas.","en":"It's hot today."}]},{"title":{"id":"Membandingkan: A 比 B + Adj","en":"Comparing: A 比 B + Adj"},"pattern":"A + 比 + B + Adj","note":{"id":"Pakai 比 untuk membandingkan dua hal, dan JANGAN pakai 很 setelahnya. Salah: 他比我很高. Benar: 他比我高. Untuk 'lebih ... sedikit' tambahkan 一點 di belakang: 他比我高一點.","en":"Use 比 to compare two things and do NOT use 很 after it. Wrong: 他比我很高. Right: 他比我高. To say 'a bit more', add 一點 at the end: 他比我高一點."},"ex":[{"zh":"這家比那家便宜。","py":"zhè jiā bǐ nà jiā pián yí","id":"Toko ini lebih murah daripada toko itu.","en":"This shop is cheaper than that one."},{"zh":"今天比昨天冷。","py":"jīn tiān bǐ zuó tiān lěng","id":"Hari ini lebih dingin daripada kemarin.","en":"Today is colder than yesterday."},{"zh":"我哥哥比我高一點。","py":"wǒ gē ge bǐ wǒ gāo yì diǎn","id":"Kakakku sedikit lebih tinggi dariku.","en":"My older brother is a bit taller than me."}]},{"title":{"id":"Terlalu atau agak: 太…了 / 有一點","en":"Too or a bit: 太…了 / 有一點"},"pattern":"太 + Adj + 了 / 有一點 + Adj","note":{"id":"太…了 berarti 'terlalu', kadang juga 'sekali' untuk pujian. 有一點 berarti 'agak' dan biasanya untuk hal yang kurang menyenangkan. Jangan menghilangkan 有: katakan 有一點貴 (agak mahal).","en":"太…了 means 'too', and sometimes 'so' in praise. 有一點 means 'a bit' and mostly goes with unpleasant things. Do not drop 有: say 有一點貴 (a bit expensive)."},"ex":[{"zh":"這雙鞋太小了。","py":"zhè shuāng xié tài xiǎo le","id":"Sepatu ini terlalu kecil.","en":"These shoes are too small."},{"zh":"這道菜有一點鹹。","py":"zhè dào cài yǒu yì diǎn xián","id":"Masakan ini agak asin.","en":"This dish is a bit salty."},{"zh":"這裡太吵了。","py":"zhè lǐ tài chǎo le","id":"Di sini terlalu berisik.","en":"It's too noisy here."}]},{"title":{"id":"Meminta sedikit lebih …: Adj + 一點","en":"Asking for a bit more or less: Adj + 一點"},"pattern":"Adj + 一點","note":{"id":"Kata sifat + 一點 dipakai untuk meminta perubahan kecil, seperti 'sedikit lebih ...'. Contoh: 便宜一點 (murahkan sedikit), 慢一點 (lebih pelan). Sangat berguna saat menawar atau bicara dengan penjual.","en":"Adj + 一點 asks for a small change, 'a little more ...'. Examples: 便宜一點 (a bit cheaper), 慢一點 (a bit slower). Very useful for bargaining or talking to shopkeepers."},"ex":[{"zh":"可以便宜一點嗎？","py":"kě yǐ pián yí yì diǎn ma","id":"Bisa lebih murah sedikit?","en":"Can it be a bit cheaper?"},{"zh":"請你快一點。","py":"qǐng nǐ kuài yì diǎn","id":"Tolong lebih cepat sedikit.","en":"Please be a little faster."},{"zh":"請說慢一點。","py":"qǐng shuō màn yì diǎn","id":"Tolong bicara lebih pelan.","en":"Please speak a bit slower."}]}],"dialog":[{"sp":"A","zh":"這件衣服好看嗎？","py":"zhè jiàn yī fu hǎo kàn ma","id":"Bajunya bagus tidak?","en":"Does this top look good?"},{"sp":"B","zh":"很好看，可是有一點貴。","py":"hěn hǎo kàn kě shì yǒu yì diǎn guì","id":"Bagus, tapi agak mahal.","en":"Very nice, but a bit expensive."},{"sp":"A","zh":"那件比較便宜，也很新。","py":"nà jiàn bǐ jiào pián yí yě hěn xīn","id":"Yang itu lebih murah, dan juga baru.","en":"That one is cheaper and also new."},{"sp":"B","zh":"可是那件太大了。","py":"kě shì nà jiàn tài dà le","id":"Tapi yang itu terlalu besar.","en":"But that one is too big."},{"sp":"A","zh":"那這件小一點，你試試看。","py":"nà zhè jiàn xiǎo yì diǎn nǐ shì shì kàn","id":"Kalau begitu yang ini lebih kecil, coba saja.","en":"Then this one is a bit smaller, try it on."},{"sp":"B","zh":"好，這件剛剛好，我買這件。","py":"hǎo zhè jiàn gāng gāng hǎo wǒ mǎi zhè jiàn","id":"Oke, yang ini pas, aku beli yang ini.","en":"OK, this one fits just right. I'll take it."}],"n":"18"},{"k":"tanya","zh":"問句小詞","py":"wèn jù xiǎo cí","title":{"id":"Kata tanya & partikel","en":"Question words & particles","tl":"Mga salitang pananong at partikulo","vi":"Từ nghi vấn và trợ từ"},"desc":{"id":"Kamu bisa bertanya apa, siapa, di mana, kapan, dan berapa, serta memakai partikel seperti 嗎, 呢, 吧, 了 dan kata penguat seperti 很, 太, 就, 才.","en":"You can ask what, who, where, when and how much, and use particles like 嗎, 呢, 吧, 了 and adverbs like 很, 太, 就, 才."},"icon":"question","sets":[{"title":{"id":"Kata tanya dasar","en":"Basic question words"},"words":[{"hz":"什麼","ex":{"zh":"你想吃什麼？","py":"nǐ xiǎng chī shén me","id":"Kamu mau makan apa?","en":"What do you want to eat?"}},{"hz":"誰","ex":{"zh":"這是誰的手機？","py":"zhè shì shéi de shǒu jī","id":"Ini ponsel siapa?","en":"Whose phone is this?"}},{"hz":"哪裡","ex":{"zh":"你住在哪裡？","py":"nǐ zhù zài nǎ lǐ","id":"Kamu tinggal di mana?","en":"Where do you live?"}},{"hz":"哪個","ex":{"zh":"你要哪個？","py":"nǐ yào nǎ ge","id":"Kamu mau yang mana?","en":"Which one do you want?"}},{"hz":"哪","ex":{"zh":"你是哪國人？","py":"nǐ shì nǎ guó rén","id":"Kamu orang negara mana?","en":"Which country are you from?"}},{"hz":"幾","ex":{"zh":"你有幾個兄弟姊妹？","py":"nǐ yǒu jǐ ge xiōng dì jiě mèi","id":"Kamu punya berapa saudara kandung?","en":"How many siblings do you have?"}},{"hz":"多少","ex":{"zh":"這個多少錢？","py":"zhè ge duō shǎo qián","id":"Ini berapa harganya?","en":"How much is this?"}},{"hz":"幾點","ex":{"zh":"你幾點下課？","py":"nǐ jǐ diǎn xià kè","id":"Kelasmu selesai jam berapa?","en":"What time does your class end?"}}]},{"title":{"id":"Bagaimana, kenapa, kapan","en":"How, why, when"},"words":[{"hz":"怎麼","ex":{"zh":"你怎麼去學校？","py":"nǐ zěn me qù xué xiào","id":"Kamu ke sekolah dengan cara apa?","en":"How do you get to school?"}},{"hz":"怎麼樣","ex":{"zh":"今天天氣怎麼樣？","py":"jīn tiān tiān qì zěn me yàng","id":"Bagaimana cuaca hari ini?","en":"How is the weather today?"}},{"hz":"為什麼","ex":{"zh":"你為什麼不吃？","py":"nǐ wèi shén me bù chī","id":"Kenapa kamu tidak makan?","en":"Why aren't you eating?"}},{"hz":"什麼時候","ex":{"zh":"你什麼時候回家？","py":"nǐ shén me shí hòu huí jiā","id":"Kapan kamu pulang?","en":"When are you going home?"}},{"hz":"多久","ex":{"zh":"你學中文多久了？","py":"nǐ xué zhōng wén duō jiǔ le","id":"Sudah berapa lama kamu belajar bahasa Mandarin?","en":"How long have you been studying Chinese?"}},{"hz":"是不是","ex":{"zh":"你是不是很累？","py":"nǐ shì bu shì hěn lèi","id":"Kamu capek, ya?","en":"You're tired, aren't you?"}},{"hz":"有沒有","ex":{"zh":"你有沒有時間？","py":"nǐ yǒu méi yǒu shí jiān","id":"Apakah kamu punya waktu?","en":"Do you have time?"}},{"hz":"好不好","ex":{"zh":"我們一起去，好不好？","py":"wǒ men yì qǐ qù hǎo bu hǎo","id":"Kita pergi bareng, bagaimana?","en":"Let's go together, okay?"}}]},{"title":{"id":"Partikel akhir kalimat","en":"Sentence-final particles"},"words":[{"hz":"嗎","ex":{"zh":"你是學生嗎？","py":"nǐ shì xué shēng ma","id":"Apakah kamu pelajar?","en":"Are you a student?"}},{"hz":"呢","ex":{"zh":"我很好，你呢？","py":"wǒ hěn hǎo nǐ ne","id":"Aku baik, kalau kamu?","en":"I'm fine, and you?"}},{"hz":"吧","ex":{"zh":"我們走吧。","py":"wǒ men zǒu ba","id":"Ayo kita jalan.","en":"Let's go."}},{"hz":"了","ex":{"zh":"我吃飽了。","py":"wǒ chī bǎo le","id":"Aku sudah kenyang.","en":"I'm full."}},{"hz":"啊","ex":{"zh":"你也在這裡啊！","py":"nǐ yě zài zhè lǐ a","id":"Ternyata kamu juga di sini!","en":"Oh, you're here too!"}},{"hz":"呀","ex":{"zh":"你怎麼才來呀？","py":"nǐ zěn me cái lái ya","id":"Kenapa kamu baru datang?","en":"Why are you only getting here now?"}},{"hz":"是嗎","ex":{"zh":"是嗎？我不知道。","py":"shì ma wǒ bù zhī dào","id":"Oh ya? Aku tidak tahu.","en":"Really? I didn't know."}},{"hz":"還是","ex":{"zh":"你喝茶還是咖啡？","py":"nǐ hē chá hái shì kā fēi","id":"Kamu minum teh atau kopi?","en":"Do you want tea or coffee?"}}]},{"title":{"id":"Kata keterangan penting","en":"Key adverbs"},"words":[{"hz":"也","ex":{"zh":"我也是學生。","py":"wǒ yě shì xué shēng","id":"Aku juga pelajar.","en":"I'm a student too."}},{"hz":"都","ex":{"zh":"我們都喜歡吃麵。","py":"wǒ men dōu xǐ huān chī miàn","id":"Kami semua suka makan mi.","en":"We all like eating noodles."}},{"hz":"更","ex":{"zh":"這個更好吃。","py":"zhè ge gèng hǎo chī","id":"Yang ini lebih enak lagi.","en":"This one is even tastier."}},{"hz":"很","ex":{"zh":"今天很熱。","py":"jīn tiān hěn rè","id":"Hari ini panas.","en":"It's hot today."}},{"hz":"太","ex":{"zh":"這個太貴了。","py":"zhè ge tài guì le","id":"Ini terlalu mahal.","en":"This is too expensive."}},{"hz":"就","ex":{"zh":"我七點就到了。","py":"wǒ qī diǎn jiù dào le","id":"Aku sudah sampai jam tujuh.","en":"I was already there at seven."}},{"hz":"才","ex":{"zh":"他九點才起床。","py":"tā jiǔ diǎn cái qǐ chuáng","id":"Dia baru bangun jam sembilan.","en":"He only got up at nine."}},{"hz":"只","ex":{"zh":"我只有一個弟弟。","py":"wǒ zhǐ yǒu yí ge dì di","id":"Aku hanya punya satu adik laki-laki.","en":"I only have one younger brother."}},{"hz":"已經","ex":{"zh":"我已經吃過飯了。","py":"wǒ yǐ jīng chī guò fàn le","id":"Aku sudah makan.","en":"I have already eaten."}},{"hz":"再","ex":{"zh":"請再說一次。","py":"qǐng zài shuō yí cì","id":"Tolong katakan sekali lagi.","en":"Please say it one more time."}}]}],"grammar":[{"title":{"id":"Kata tanya tetap di tempat jawaban","en":"Question words stay in place"},"pattern":"Subjek + Kata kerja + 什麼 / 誰 / 哪裡","note":{"id":"Di bahasa Mandarin kata tanya tidak dipindah ke depan kalimat. Ia menempati posisi jawabannya. Jawaban 'aku makan mi' menjadi pertanyaan 你吃什麼 (kamu makan apa). Jangan menambahkan 嗎 pada kalimat yang sudah punya kata tanya.","en":"Chinese question words do not move to the front. They sit where the answer would be: 'I eat noodles' becomes 你吃什麼 (you eat what). Do not add 嗎 to a sentence that already has a question word."},"ex":[{"zh":"你在看什麼？","py":"nǐ zài kàn shén me","id":"Kamu sedang melihat apa?","en":"What are you looking at?"},{"zh":"他去哪裡？","py":"tā qù nǎ lǐ","id":"Dia pergi ke mana?","en":"Where is he going?"},{"zh":"你找誰？","py":"nǐ zhǎo shéi","id":"Kamu cari siapa?","en":"Who are you looking for?"}]},{"title":{"id":"Pertanyaan ya/tidak: 嗎 dan A不A","en":"Yes/no questions: 嗎 and A-not-A"},"pattern":"Kalimat + 嗎？ / V + 不 + V","note":{"id":"Tambahkan 嗎 di akhir kalimat pernyataan untuk membuat pertanyaan ya/tidak. Bisa juga memakai pola A不A, misalnya 是不是 atau 好不好. Pilih salah satu saja: 你是不是學生嗎 salah.","en":"Add 嗎 to the end of a statement to ask a yes/no question. You can also use the A-not-A pattern, such as 是不是 or 好不好. Use only one of them: 你是不是學生嗎 is wrong."},"ex":[{"zh":"你會說中文嗎？","py":"nǐ huì shuō zhōng wén ma","id":"Apakah kamu bisa bahasa Mandarin?","en":"Can you speak Chinese?"},{"zh":"你是不是台灣人？","py":"nǐ shì bu shì tái wān rén","id":"Apakah kamu orang Taiwan?","en":"Are you Taiwanese?"},{"zh":"明天去，好不好？","py":"míng tiān qù hǎo bu hǎo","id":"Pergi besok, bagaimana?","en":"Shall we go tomorrow?"}]},{"title":{"id":"也 dan 都 sebelum kata kerja","en":"也 and 都 go before the verb"},"pattern":"Subjek + 也 / 都 + Kata kerja","note":{"id":"也 (juga) dan 都 (semua) selalu diletakkan sebelum kata kerja atau kata sifat, bukan di akhir kalimat seperti 'juga' dalam bahasa Indonesia. Kalau dipakai bersama, urutannya 也都.","en":"也 (also) and 都 (all) always go before the verb or adjective, never at the end of the sentence like English 'too'. When used together, the order is 也都."},"ex":[{"zh":"我也想去。","py":"wǒ yě xiǎng qù","id":"Aku juga mau pergi.","en":"I want to go too."},{"zh":"我們都想去夜市。","py":"wǒ men dōu xiǎng qù yè shì","id":"Kami semua mau ke pasar malam.","en":"We all want to go to the night market."},{"zh":"他們也都是學生。","py":"tā men yě dōu shì xué shēng","id":"Mereka juga semuanya pelajar.","en":"They are all students too."}]},{"title":{"id":"就 (lebih awal) dan 才 (lebih lambat)","en":"就 (earlier) vs 才 (later)"},"pattern":"Waktu + 就 + V (+ 了)  /  Waktu + 才 + V","note":{"id":"就 menunjukkan sesuatu terjadi lebih cepat atau lebih mudah dari yang diharapkan, biasanya dengan 了. 才 menunjukkan sesuatu terjadi lebih lambat atau lebih sulit. Perhatikan: 就 sering diikuti 了, sedangkan 才 tidak.","en":"就 shows something happens earlier or more easily than expected, often with 了. 才 shows it happens later or with more difficulty. Note that 就 often takes 了, but 才 does not."},"ex":[{"zh":"我六點就起床了。","py":"wǒ liù diǎn jiù qǐ chuáng le","id":"Aku sudah bangun jam enam.","en":"I was up at six."},{"zh":"他八點才起床。","py":"tā bā diǎn cái qǐ chuáng","id":"Dia baru bangun jam delapan.","en":"He only got up at eight."}]}],"dialog":[{"sp":"A","zh":"你明天有空嗎？","py":"nǐ míng tiān yǒu kòng ma","id":"Apakah kamu besok ada waktu luang?","en":"Are you free tomorrow?"},{"sp":"B","zh":"有啊。你想去哪裡？","py":"yǒu a nǐ xiǎng qù nǎ lǐ","id":"Ada. Kamu mau pergi ke mana?","en":"Yes. Where do you want to go?"},{"sp":"A","zh":"我們去夜市吧，我很想吃雞排。","py":"wǒ men qù yè shì ba wǒ hěn xiǎng chī jī pái","id":"Ayo ke pasar malam, aku pengin banget makan jipai (ayam goreng tepung).","en":"Let's go to the night market. I really want fried chicken."},{"sp":"B","zh":"好啊，幾點去？","py":"hǎo a jǐ diǎn qù","id":"Boleh, jam berapa perginya?","en":"Sure. What time shall we go?"},{"sp":"A","zh":"我六點就下課了，你呢？","py":"wǒ liù diǎn jiù xià kè le nǐ ne","id":"Aku jam enam sudah selesai kuliah, kalau kamu?","en":"I finish class at six. And you?"},{"sp":"B","zh":"我七點才下課。","py":"wǒ qī diǎn cái xià kè","id":"Aku baru selesai jam tujuh.","en":"I only finish at seven."},{"sp":"A","zh":"那我們七點半見，好嗎？","py":"nà wǒ men qī diǎn bàn jiàn hǎo ma","id":"Kalau begitu kita ketemu jam setengah delapan, bagaimana?","en":"Then let's meet at seven thirty, okay?"},{"sp":"B","zh":"好，我也帶朋友去。","py":"hǎo wǒ yě dài péng yǒu qù","id":"Oke, aku juga akan ajak teman.","en":"Okay, I'll bring a friend too."}],"n":"19"},{"k":"tekno","zh":"手機網路","py":"shǒu jī wǎng lù","title":{"id":"Ponsel, komputer & internet","en":"Phone, computer & internet","tl":"Telepono, kompyuter at internet","vi":"Điện thoại, máy tính và internet"},"desc":{"id":"Kamu bisa meminta Wi-Fi dan colokan, menyebut akun dan kata sandi, serta mengirim pesan dan foto dalam bahasa Mandarin Taiwan.","en":"You can ask for Wi-Fi and a power outlet, talk about accounts and passwords, and send messages and photos in Taiwan Mandarin."},"icon":"phone","sets":[{"title":{"id":"Perangkat dan aksesori","en":"Devices and accessories"},"words":[{"hz":"手機","mw":"支","ex":{"zh":"我的手機是新的。","py":"wǒ de shǒu jī shì xīn de","id":"Ponselku baru.","en":"My phone is new."}},{"hz":"電腦","mw":"台","ex":{"zh":"我的電腦很舊。","py":"wǒ de diàn nǎo hěn jiù","id":"Komputerku sudah tua.","en":"My computer is old."}},{"hz":"筆電","mw":"台","ex":{"zh":"他每天帶筆電去學校。","py":"tā měi tiān dài bǐ diàn qù xué xiào","id":"Dia tiap hari membawa laptop ke sekolah.","en":"He takes his laptop to school every day."}},{"hz":"螢幕","mw":"個","ex":{"zh":"這個螢幕很大。","py":"zhè ge yíng mù hěn dà","id":"Layar ini besar sekali.","en":"This screen is very big."}},{"hz":"滑鼠","mw":"個","ex":{"zh":"我想買新的滑鼠。","py":"wǒ xiǎng mǎi xīn de huá shǔ","id":"Aku ingin beli mouse baru.","en":"I want to buy a new mouse."}},{"hz":"耳機","mw":"副","ex":{"zh":"我想買新耳機。","py":"wǒ xiǎng mǎi xīn ěr jī","id":"Aku ingin beli earphone baru.","en":"I want to buy new earphones."}},{"hz":"充電器","mw":"個","ex":{"zh":"你有手機充電器嗎？","py":"nǐ yǒu shǒu jī chōng diàn qì ma","id":"Apakah kamu punya charger ponsel?","en":"Do you have a phone charger?"}},{"hz":"行動電源","mw":"個","ex":{"zh":"我帶了行動電源。","py":"wǒ dài le xíng dòng diàn yuán","id":"Aku membawa power bank.","en":"I brought a power bank."}},{"hz":"充電線","mw":"條","ex":{"zh":"我的充電線壞掉了。","py":"wǒ de chōng diàn xiàn huài diào le","id":"Kabel chargerku rusak.","en":"My charging cable is broken."}},{"hz":"插座","mw":"個","ex":{"zh":"這裡有插座嗎？","py":"zhè lǐ yǒu chā zuò ma","id":"Apakah di sini ada colokan?","en":"Is there a power outlet here?"}}]},{"title":{"id":"Internet dan aplikasi","en":"Internet and apps"},"words":[{"hz":"網路","ex":{"zh":"這裡的網路很快。","py":"zhè lǐ de wǎng lù hěn kuài","id":"Internet di sini cepat sekali.","en":"The internet here is very fast."}},{"hz":"上網","ex":{"zh":"我每天都上網。","py":"wǒ měi tiān dōu shàng wǎng","id":"Aku online setiap hari.","en":"I go online every day."}},{"hz":"網站","mw":"個","ex":{"zh":"這個網站很好用。","py":"zhè ge wǎng zhàn hěn hǎo yòng","id":"Situs web ini mudah dipakai.","en":"This website is easy to use."}},{"hz":"網址","ex":{"zh":"你可以給我網址嗎？","py":"nǐ kě yǐ gěi wǒ wǎng zhǐ ma","id":"Bisakah kamu memberiku alamat situsnya?","en":"Can you give me the web address?"}},{"hz":"搜尋","ex":{"zh":"你可以上網搜尋。","py":"nǐ kě yǐ shàng wǎng sōu xún","id":"Kamu bisa mencarinya di internet.","en":"You can search for it online."}},{"hz":"下載","ex":{"zh":"我想下載這個應用程式。","py":"wǒ xiǎng xià zài zhè ge yìng yòng chéng shì","id":"Aku ingin mengunduh aplikasi ini.","en":"I want to download this app."}},{"hz":"應用程式","mw":"個","ex":{"zh":"這個應用程式很方便。","py":"zhè ge yìng yòng chéng shì hěn fāng biàn","id":"Aplikasi ini praktis sekali.","en":"This app is very convenient."}},{"hz":"更新","ex":{"zh":"手機要更新了。","py":"shǒu jī yào gēng xīn le","id":"Ponselnya perlu diperbarui.","en":"The phone needs an update."}}]},{"title":{"id":"Akun dan nomor","en":"Accounts and numbers"},"words":[{"hz":"帳號","mw":"個","ex":{"zh":"你的帳號是什麼？","py":"nǐ de zhàng hào shì shén me","id":"Akunmu apa?","en":"What is your account name?"}},{"hz":"密碼","ex":{"zh":"我忘了我的密碼。","py":"wǒ wàng le wǒ de mì mǎ","id":"Aku lupa kata sandiku.","en":"I forgot my password."}},{"hz":"登入","ex":{"zh":"請先登入帳號。","py":"qǐng xiān dēng rù zhàng hào","id":"Silakan login dulu ke akunnya.","en":"Please log in to your account first."}},{"hz":"電子郵件","mw":"封","ex":{"zh":"請寄電子郵件給我。","py":"qǐng jì diàn zǐ yóu jiàn gěi wǒ","id":"Tolong kirim email kepadaku.","en":"Please send me an email."}},{"hz":"手機號碼","ex":{"zh":"你的手機號碼是多少？","py":"nǐ de shǒu jī hào mǎ shì duō shǎo","id":"Berapa nomor ponselmu?","en":"What is your mobile number?"}},{"hz":"號碼","mw":"個","ex":{"zh":"這個號碼是誰的？","py":"zhè ge hào mǎ shì shéi de","id":"Nomor ini milik siapa?","en":"Whose number is this?"}}]},{"title":{"id":"Pesan, telepon, foto","en":"Messages, calls, photos"},"words":[{"hz":"訊息","mw":"則","ex":{"zh":"我看到你的訊息了。","py":"wǒ kàn dào nǐ de xùn xí le","id":"Aku sudah lihat pesanmu.","en":"I saw your message."}},{"hz":"簡訊","mw":"封","ex":{"zh":"我收到一封簡訊。","py":"wǒ shōu dào yì fēng jiǎn xùn","id":"Aku menerima sebuah SMS.","en":"I received a text message."}},{"hz":"傳訊息","ex":{"zh":"他常常傳訊息給我。","py":"tā cháng cháng chuán xùn xí gěi wǒ","id":"Dia sering mengirim pesan kepadaku.","en":"He often sends me messages."}},{"hz":"電話","mw":"支","ex":{"zh":"老師的電話在這裡。","py":"lǎo shī de diàn huà zài zhè lǐ","id":"Nomor telepon guru ada di sini.","en":"The teacher's phone number is here."}},{"hz":"打電話","ex":{"zh":"我晚上打電話給你。","py":"wǒ wǎn shàng dǎ diàn huà gěi nǐ","id":"Malam nanti aku telepon kamu.","en":"I'll call you tonight."}},{"hz":"照片","mw":"張","ex":{"zh":"這張照片很漂亮。","py":"zhè zhāng zhào piàn hěn piào liang","id":"Foto ini bagus sekali.","en":"This photo is very pretty."}},{"hz":"拍照","ex":{"zh":"我們在這裡拍照吧。","py":"wǒ men zài zhè lǐ pāi zhào ba","id":"Ayo kita foto di sini.","en":"Let's take photos here."}},{"hz":"截圖","ex":{"zh":"我幫你截圖。","py":"wǒ bāng nǐ jié tú","id":"Aku bantu screenshot untukmu.","en":"I'll take a screenshot for you."}}]},{"title":{"id":"Menyalakan dan masalah","en":"Power and problems"},"words":[{"hz":"開機","ex":{"zh":"我的電腦不能開機。","py":"wǒ de diàn nǎo bù néng kāi jī","id":"Komputerku tidak bisa dinyalakan.","en":"My computer won't turn on."}},{"hz":"關機","ex":{"zh":"請把手機關機。","py":"qǐng bǎ shǒu jī guān jī","id":"Tolong matikan ponselnya.","en":"Please turn off your phone."}},{"hz":"充電","ex":{"zh":"我的手機要充電。","py":"wǒ de shǒu jī yào chōng diàn","id":"Ponselku perlu diisi daya.","en":"My phone needs charging."}},{"hz":"沒電","ex":{"zh":"我的手機沒電了。","py":"wǒ de shǒu jī méi diàn le","id":"Ponselku kehabisan baterai.","en":"My phone is out of battery."}},{"hz":"壞掉","ex":{"zh":"我的電腦壞掉了。","py":"wǒ de diàn nǎo huài diào le","id":"Komputerku rusak.","en":"My computer is broken."}}]}],"grammar":[{"title":{"id":"Mengirim sesuatu kepada orang: V + benda + 給 + orang","en":"Sending something to someone"},"pattern":"傳 / 寄 / 打 + benda + 給 + orang","note":{"id":"Penerima ditaruh sesudah 給, dan 給 + orang diletakkan setelah benda yang dikirim. Orang Indonesia sering memakai urutan 'kirim kamu foto' yang kurang tepat di sini. Untuk telepon, pola yang dipakai adalah 打電話給 + orang.","en":"The recipient goes after 給, and 給 + person comes after the thing being sent. For calls, use 打電話給 + person."},"ex":[{"zh":"我傳照片給你。","py":"wǒ chuán zhào piàn gěi nǐ","id":"Aku kirim foto untukmu.","en":"I'll send you the photo."},{"zh":"他寄電子郵件給老師。","py":"tā jì diàn zǐ yóu jiàn gěi lǎo shī","id":"Dia mengirim email kepada guru.","en":"He sent an email to the teacher."},{"zh":"我明天打電話給你。","py":"wǒ míng tiān dǎ diàn huà gěi nǐ","id":"Besok aku telepon kamu.","en":"I'll call you tomorrow."}]},{"title":{"id":"Meminta izin: 可以…嗎？","en":"Asking permission"},"pattern":"我可以 + V + 嗎？","note":{"id":"Pakai 可以 sebelum kata kerja dan 嗎 di akhir untuk meminta izin atau bantuan. Di kafe atau toko di Taiwan, kalimat ini sopan dan sangat sering dipakai. Jawab singkat dengan 可以 atau 不可以.","en":"Put 可以 before the verb and 嗎 at the end to ask permission or help. It is polite and very common in Taiwanese cafes and shops. Answer briefly with 可以 or 不可以."},"ex":[{"zh":"我可以用你的充電線嗎？","py":"wǒ kě yǐ yòng nǐ de chōng diàn xiàn ma","id":"Bolehkah aku pakai kabel chargermu?","en":"Can I use your charging cable?"},{"zh":"我可以在這裡上網嗎？","py":"wǒ kě yǐ zài zhè lǐ shàng wǎng ma","id":"Bolehkah aku online di sini?","en":"Can I go online here?"}]},{"title":{"id":"Urutan langkah: 先…再…","en":"Doing things in order"},"pattern":"先 + V1，再 + V2","note":{"id":"先 berarti 'dulu' dan 再 berarti 'baru' atau 'lalu'. Kedua kata diletakkan sebelum kata kerja. Pola ini cocok untuk petunjuk, misalnya cara memakai aplikasi.","en":"先 means 'first' and 再 means 'then'. Both go before the verb. This pattern is useful for instructions, such as how to use an app."},"ex":[{"zh":"請先登入，再下載。","py":"qǐng xiān dēng rù zài xià zài","id":"Silakan login dulu, baru unduh.","en":"Please log in first, then download."},{"zh":"我先充電，再打給你。","py":"wǒ xiān chōng diàn zài dǎ gěi nǐ","id":"Aku isi daya dulu, lalu telepon kamu.","en":"I'll charge it first, then call you."}]},{"title":{"id":"Perubahan keadaan: …了","en":"A change of state with 了"},"pattern":"Benda + 沒電 / 壞掉 / 更新 + 了","note":{"id":"了 di akhir kalimat menunjukkan keadaan sudah berubah, misalnya ponsel yang tadinya hidup sekarang 沒電了. Dalam bahasa Indonesia sering cukup 'sudah' atau tanpa kata tambahan. Kalau keadaannya belum berubah, pakai 還 tanpa 了: 我的手機還有電 (ponselku masih ada baterai).","en":"了 at the end of a sentence shows that a situation has changed, such as a phone that now is 沒電了. English often uses 'has' or the present tense. If nothing has changed yet, use 還 without 了: 我的手機還有電 (my phone still has battery)."},"ex":[{"zh":"我的手機沒電了。","py":"wǒ de shǒu jī méi diàn le","id":"Ponselku sudah habis baterai.","en":"My phone has run out of battery."},{"zh":"網路壞掉了。","py":"wǎng lù huài diào le","id":"Internetnya rusak.","en":"The internet is down."}]}],"dialog":[{"sp":"A","zh":"不好意思，這裡有網路嗎？","py":"bù hǎo yì si zhè lǐ yǒu wǎng lù ma","id":"Permisi, apakah di sini ada internet?","en":"Excuse me, is there internet here?"},{"sp":"B","zh":"有，網路密碼在桌子上。","py":"yǒu wǎng lù mì mǎ zài zhuō zi shàng","id":"Ada, kata sandi internetnya ada di meja.","en":"Yes, the Wi-Fi password is on the table."},{"sp":"A","zh":"謝謝。我的手機沒電了，有插座嗎？","py":"xiè xie wǒ de shǒu jī méi diàn le yǒu chā zuò ma","id":"Terima kasih. Ponselku habis baterai, ada colokan?","en":"Thanks. My phone is out of battery. Is there an outlet?"},{"sp":"B","zh":"那邊有插座。","py":"nà biān yǒu chā zuò","id":"Di sana ada colokan.","en":"There is one over there."},{"sp":"A","zh":"太好了！我要上網傳照片給朋友。","py":"tài hǎo le wǒ yào shàng wǎng chuán zhào piàn gěi péng yǒu","id":"Bagus sekali! Aku mau online untuk kirim foto ke teman.","en":"Great! I want to go online and send photos to a friend."},{"sp":"B","zh":"你的充電線帶了嗎？","py":"nǐ de chōng diàn xiàn dài le ma","id":"Kabel chargermu sudah dibawa?","en":"Did you bring your charging cable?"},{"sp":"A","zh":"帶了，謝謝你。","py":"dài le xiè xie nǐ","id":"Sudah, terima kasih.","en":"Yes, thank you."}],"n":"20"},{"k":"wisata","zh":"旅行住宿","py":"lǚ xíng zhù sù","title":{"id":"Wisata & penginapan","en":"Travel & accommodation","tl":"Paglalakbay at tuluyan","vi":"Du lịch và chỗ ở"},"desc":{"id":"Kamu bisa membeli tiket, memesan kamar hotel, bertanya soal check-in dan check-out, serta membicarakan tempat wisata.","en":"You can buy tickets, book a hotel room, ask about check-in and check-out, and talk about sightseeing."},"icon":"plane","sets":[{"title":{"id":"Rencana perjalanan","en":"Planning a trip"},"words":[{"hz":"旅行","ex":{"zh":"我想去日本旅行。","py":"wǒ xiǎng qù rì běn lǚ xíng","id":"Aku ingin pergi wisata ke Jepang.","en":"I want to travel to Japan."}},{"hz":"出國","ex":{"zh":"我明年想出國玩。","py":"wǒ míng nián xiǎng chū guó wán","id":"Tahun depan aku ingin jalan-jalan ke luar negeri.","en":"Next year I want to travel abroad."}},{"hz":"度假","ex":{"zh":"我們下個月去墾丁度假。","py":"wǒ men xià ge yuè qù kěn dīng dù jià","id":"Bulan depan kami berlibur ke Kenting.","en":"We are going on holiday to Kenting next month."}},{"hz":"放假","ex":{"zh":"下星期一放假。","py":"xià xīng qí yī fàng jià","id":"Senin depan libur.","en":"Next Monday is a day off."}},{"hz":"簽證","mw":"張","ex":{"zh":"去美國要辦簽證。","py":"qù měi guó yào bàn qiān zhèng","id":"Untuk ke Amerika harus mengurus visa.","en":"You need a visa to go to the US."}},{"hz":"飛機場","ex":{"zh":"飛機場離市區很遠。","py":"fēi jī chǎng lí shì qū hěn yuǎn","id":"Bandara jauh dari pusat kota.","en":"The airport is far from downtown."}},{"hz":"航班","mw":"個","ex":{"zh":"你的航班是幾點的？","py":"nǐ de háng bān shì jǐ diǎn de","id":"Penerbanganmu jam berapa?","en":"What time is your flight?"}},{"hz":"登機","ex":{"zh":"請從三號門登機。","py":"qǐng cóng sān hào mén dēng jī","id":"Silakan naik pesawat lewat gerbang tiga.","en":"Please board from gate three."}}]},{"title":{"id":"Tiket dan kendaraan","en":"Tickets and transport"},"words":[{"hz":"票","mw":"張","ex":{"zh":"我有兩張票。","py":"wǒ yǒu liǎng zhāng piào","id":"Aku punya dua tiket.","en":"I have two tickets."}},{"hz":"買票","ex":{"zh":"我在網路上買票。","py":"wǒ zài wǎng lù shàng mǎi piào","id":"Aku membeli tiket lewat internet.","en":"I buy tickets online."}},{"hz":"訂票","ex":{"zh":"你訂票了嗎？","py":"nǐ dìng piào le ma","id":"Sudahkah kamu memesan tiket?","en":"Have you booked your ticket?"}},{"hz":"單程票","mw":"張","ex":{"zh":"我要一張單程票。","py":"wǒ yào yì zhāng dān chéng piào","id":"Aku mau satu tiket sekali jalan.","en":"I would like a one-way ticket."}},{"hz":"來回票","mw":"張","ex":{"zh":"來回票比較便宜。","py":"lái huí piào bǐ jiào pián yí","id":"Tiket pulang pergi lebih murah.","en":"Round-trip tickets are cheaper."}},{"hz":"高鐵","ex":{"zh":"坐高鐵去台南很快。","py":"zuò gāo tiě qù tái nán hěn kuài","id":"Ke Tainan naik kereta cepat tidak makan waktu lama.","en":"Taking the high-speed rail to Tainan is fast."}},{"hz":"火車","mw":"班","ex":{"zh":"我們坐火車去花蓮。","py":"wǒ men zuò huǒ chē qù huā lián","id":"Kami naik kereta ke Hualien.","en":"We are taking the train to Hualien."}},{"hz":"登機證","mw":"張","ex":{"zh":"請給我你的登機證。","py":"qǐng gěi wǒ nǐ de dēng jī zhèng","id":"Tolong berikan boarding pass-mu.","en":"Please give me your boarding pass."}}]},{"title":{"id":"Hotel dan penginapan","en":"Hotels and lodging"},"words":[{"hz":"飯店","mw":"家","ex":{"zh":"這家飯店很乾淨。","py":"zhè jiā fàn diàn hěn gān jìng","id":"Hotel ini bersih sekali.","en":"This hotel is very clean."}},{"hz":"民宿","mw":"家","ex":{"zh":"我們住在九份的一家民宿。","py":"wǒ men zhù zài jiǔ fèn de yì jiā mín sù","id":"Kami menginap di homestay di Jiufen.","en":"We are staying at a B&B in Jiufen."}},{"hz":"房間","mw":"間","ex":{"zh":"我的房間在三樓。","py":"wǒ de fáng jiān zài sān lóu","id":"Kamarku ada di lantai tiga.","en":"My room is on the third floor."}},{"hz":"單人房","mw":"間","ex":{"zh":"我要訂一間單人房。","py":"wǒ yào dìng yì jiān dān rén fáng","id":"Aku mau memesan satu kamar single.","en":"I'd like to book a single room."}},{"hz":"雙人房","mw":"間","ex":{"zh":"雙人房一晚多少錢？","py":"shuāng rén fáng yì wǎn duō shǎo qián","id":"Kamar double semalam berapa harganya?","en":"How much is a double room per night?"}},{"hz":"訂房","ex":{"zh":"我想在網路上訂房。","py":"wǒ xiǎng zài wǎng lù shàng dìng fáng","id":"Aku ingin memesan kamar lewat internet.","en":"I want to book a room online."}},{"hz":"入住","ex":{"zh":"幾點可以入住？","py":"jǐ diǎn kě yǐ rù zhù","id":"Jam berapa boleh check in?","en":"What time can I check in?"}},{"hz":"退房","ex":{"zh":"明天中午十二點退房。","py":"míng tiān zhōng wǔ shí èr diǎn tuì fáng","id":"Besok check out jam dua belas siang.","en":"Check-out is at twelve noon tomorrow."}}]},{"title":{"id":"Barang bawaan dan uang","en":"Luggage and money"},"words":[{"hz":"行李","mw":"件","ex":{"zh":"我的行李很重。","py":"wǒ de xíng lǐ hěn zhòng","id":"Bagasiku berat sekali.","en":"My luggage is very heavy."}},{"hz":"行李箱","mw":"個","ex":{"zh":"我的行李箱是藍色的。","py":"wǒ de xíng li xiāng shì lán sè de","id":"Koperku berwarna biru.","en":"My suitcase is blue."}},{"hz":"背包","mw":"個","ex":{"zh":"我只帶一個背包。","py":"wǒ zhǐ dài yí ge bēi bāo","id":"Aku hanya membawa satu ransel.","en":"I am only bringing one backpack."}},{"hz":"換錢","ex":{"zh":"我要去銀行換錢。","py":"wǒ yào qù yín háng huàn qián","id":"Aku mau ke bank untuk menukar uang.","en":"I'm going to the bank to exchange money."}},{"hz":"匯率","ex":{"zh":"今天的匯率怎麼樣？","py":"jīn tiān de huì lǜ zěn me yàng","id":"Bagaimana kurs hari ini?","en":"How is the exchange rate today?"}},{"hz":"地圖","mw":"張","ex":{"zh":"我用手機看地圖。","py":"wǒ yòng shǒu jī kàn dì tú","id":"Aku melihat peta dengan ponsel.","en":"I look at the map on my phone."}}]},{"title":{"id":"Tempat wisata dan oleh-oleh","en":"Sightseeing and souvenirs"},"words":[{"hz":"景點","mw":"個","ex":{"zh":"這裡有很多景點。","py":"zhè lǐ yǒu hěn duō jǐng diǎn","id":"Di sini ada banyak tempat wisata.","en":"There are many attractions here."}},{"hz":"觀光客","mw":"個","ex":{"zh":"夜市有很多觀光客。","py":"yè shì yǒu hěn duō guān guāng kè","id":"Di pasar malam banyak turis.","en":"The night market has many tourists."}},{"hz":"風景","ex":{"zh":"這裡的風景很漂亮。","py":"zhè lǐ de fēng jǐng hěn piào liang","id":"Pemandangan di sini indah sekali.","en":"The scenery here is beautiful."}},{"hz":"海邊","ex":{"zh":"我們去海邊走走吧。","py":"wǒ men qù hǎi biān zǒu zou ba","id":"Ayo kita jalan-jalan ke pantai.","en":"Let's take a walk at the beach."}},{"hz":"溫泉","ex":{"zh":"北投有很多溫泉。","py":"běi tóu yǒu hěn duō wēn quán","id":"Di Beitou banyak pemandian air panas.","en":"Beitou has many hot springs."}},{"hz":"紀念品","mw":"個","ex":{"zh":"我想買一些紀念品。","py":"wǒ xiǎng mǎi yì xiē jì niàn pǐn","id":"Aku ingin membeli beberapa suvenir.","en":"I want to buy some souvenirs."}},{"hz":"伴手禮","mw":"份","ex":{"zh":"鳳梨酥是台灣的伴手禮。","py":"fèng lí sū shì tái wān de bàn shǒu lǐ","id":"Pineapple cake adalah oleh-oleh khas Taiwan.","en":"Pineapple cakes are a classic Taiwanese souvenir gift."}},{"hz":"明信片","mw":"張","ex":{"zh":"我寄一張明信片給你。","py":"wǒ jì yì zhāng míng xìn piàn gěi nǐ","id":"Aku kirim sebuah kartu pos untukmu.","en":"I'll send you a postcard."}}]}],"grammar":[{"title":{"id":"Pergi ke tempat untuk melakukan sesuatu","en":"Going somewhere to do something"},"pattern":"去 + tempat + V","note":{"id":"Tujuan perjalanan langsung ditaruh setelah 去, lalu kegiatannya. Tidak perlu kata 'untuk' atau 'ke' tambahan. Kendaraan ditaruh sebelum 去 dengan 坐 atau 搭.","en":"Put the destination right after 去, then the activity. No extra word for 'to' is needed. Put the vehicle before 去 with 坐 or 搭."},"ex":[{"zh":"我們坐高鐵去台南玩。","py":"wǒ men zuò gāo tiě qù tái nán wán","id":"Kami naik kereta cepat ke Tainan untuk jalan-jalan.","en":"We take the high-speed rail to Tainan for a trip."},{"zh":"他去花蓮度假。","py":"tā qù huā lián dù jià","id":"Dia berlibur ke Hualien.","en":"He's going to Hualien for a holiday."}]},{"title":{"id":"Membandingkan: A 比 B + sifat","en":"Comparing: A 比 B + adjective"},"pattern":"A + 比 + B + sifat","note":{"id":"Pakai 比 untuk membandingkan dua hal, dan sifatnya ditaruh di belakang tanpa 很. Kalimat 'A 比 B 很貴' salah. Untuk menyatakan 'sedikit lebih', tambahkan 一點 di belakang sifat.","en":"Use 比 to compare two things, with the adjective after B and no 很. 'A 比 B 很貴' is wrong. To say 'a little more', add 一點 after the adjective."},"ex":[{"zh":"高鐵比火車快。","py":"gāo tiě bǐ huǒ chē kuài","id":"Kereta cepat lebih cepat daripada kereta biasa.","en":"The high-speed rail is faster than the train."},{"zh":"飯店比民宿貴。","py":"fàn diàn bǐ mín sù guì","id":"Hotel lebih mahal daripada homestay.","en":"The hotel is more expensive than the B&B."}]},{"title":{"id":"Jarak: A 離 B 很近／遠","en":"Distance: A 離 B"},"pattern":"A + 離 + B + 很近 / 很遠","note":{"id":"離 berarti 'dari' dalam arti jarak antara dua tempat. Jangan memakai 從 untuk jarak. 從 dipakai untuk titik awal gerakan, misalnya 從台北到高雄.","en":"離 means 'from' in the sense of distance between two places. Do not use 從 for distance. 從 marks a starting point of movement, as in 從台北到高雄."},"ex":[{"zh":"飯店離車站很近。","py":"fàn diàn lí chē zhàn hěn jìn","id":"Hotel dekat dari stasiun.","en":"The hotel is close to the station."},{"zh":"民宿離海邊不遠。","py":"mín sù lí hǎi biān bù yuǎn","id":"Homestay tidak jauh dari pantai.","en":"The B&B is not far from the beach."}]},{"title":{"id":"Pernah melakukan: V + 過","en":"Having done something: V + 過"},"pattern":"Subjek + (沒) + V + 過","note":{"id":"過 setelah kata kerja menyatakan pengalaman, yaitu pernah melakukan sesuatu. Bentuk negatifnya memakai 沒, contohnya 沒去過 (belum pernah pergi). Jangan memakai 不 di sini.","en":"過 after a verb shows past experience. The negative uses 沒, as in 沒去過 (have never been). Do not use 不 here."},"ex":[{"zh":"我去過日本。","py":"wǒ qù guo rì běn","id":"Aku pernah ke Jepang.","en":"I have been to Japan."},{"zh":"我沒坐過高鐵。","py":"wǒ méi zuò guo gāo tiě","id":"Aku belum pernah naik kereta cepat.","en":"I have never taken the high-speed rail."}]}],"dialog":[{"sp":"A","zh":"你好，我想訂一間雙人房。","py":"nǐ hǎo wǒ xiǎng dìng yì jiān shuāng rén fáng","id":"Halo, saya ingin memesan satu kamar double.","en":"Hello, I'd like to book a double room."},{"sp":"B","zh":"好的，請問住幾晚？","py":"hǎo de qǐng wèn zhù jǐ wǎn","id":"Baik, mau menginap berapa malam?","en":"Sure, how many nights will you stay?"},{"sp":"A","zh":"住兩晚，明天入住。","py":"zhù liǎng wǎn míng tiān rù zhù","id":"Dua malam, check in besok.","en":"Two nights, checking in tomorrow."},{"sp":"B","zh":"沒問題。早上十一點退房。","py":"méi wèn tí zǎo shàng shí yī diǎn tuì fáng","id":"Tidak masalah. Check out jam sebelas pagi.","en":"No problem. Check-out is at eleven in the morning."},{"sp":"A","zh":"飯店離高鐵站遠嗎？","py":"fàn diàn lí gāo tiě zhàn yuǎn ma","id":"Apakah hotel jauh dari stasiun kereta cepat?","en":"Is the hotel far from the high-speed rail station?"},{"sp":"B","zh":"不遠，坐捷運十分鐘就到了。","py":"bù yuǎn zuò jié yùn shí fēn zhōng jiù dào le","id":"Tidak jauh, naik MRT sepuluh menit sudah sampai.","en":"Not far. It's ten minutes by MRT."},{"sp":"A","zh":"太好了，謝謝你！","py":"tài hǎo le xiè xie nǐ","id":"Bagus sekali, terima kasih!","en":"Great, thank you!"}],"n":"21"}];